const c=5,n="dao-duc",i="Đạo đức lớp 5",h="internal",t=[{id:"biet-on-nguoi-co-cong",title:"Biết ơn những người có công với quê hương, đất nước",lessons:[{id:"dd5-nguoi-co-cong",title:"Bài 1: Những người có công với quê hương, đất nước",weeks:[1,2],learn:[{title:"Người có công là ai?",text:"Đó là những người đã góp công sức, có khi cả tính mạng, để dựng nước, giữ nước và xây dựng quê hương, đất nước.",example:"🇻🇳 dựng nước · giữ nước · xây dựng"},{title:"Trong lịch sử",text:"Các Vua Hùng dựng nước; Hai Bà Trưng, Ngô Quyền, Trần Hưng Đạo, Lê Lợi, Quang Trung, Chủ tịch Hồ Chí Minh… lãnh đạo nhân dân đánh giặc, giữ nước.",example:"⚔️ Bạch Đằng · 🏯 Lam Sơn"},{title:"Trong cuộc sống hôm nay",text:"Các anh hùng liệt sĩ, thương binh, bà mẹ Việt Nam Anh hùng, các nhà khoa học, bác sĩ, thầy cô… đều có công với quê hương, đất nước.",example:"🎖️ thương binh · 🧑‍🔬 nhà khoa học"}],practice:[{questions:[{id:"dd5-nguoi-co-cong-01",type:"multi",q:"Những ai là người có công với đất nước?",options:["Các anh hùng liệt sĩ","Thương binh","Bà mẹ Việt Nam Anh hùng","Người hay chen ngang khi xếp hàng"],answers:[0,1,2],explain:"Liệt sĩ, thương binh, bà mẹ Việt Nam Anh hùng là những người có công với đất nước."},{id:"dd5-nguoi-co-cong-02",type:"mc",q:"Ai có công dựng nước Văn Lang?",options:["Các Vua Hùng","Hai Bà Trưng","Lê Lợi"],answer:0,emoji:"🏯",explain:"Theo truyền thuyết và sử sách, các Vua Hùng có công dựng nước Văn Lang."},{id:"dd5-nguoi-co-cong-03",type:"mc",q:"Ngô Quyền đánh tan quân Nam Hán trên dòng sông nào?",options:["Sông Hồng ở Hà Nội","Sông Bạch Đằng","Sông Hương ở Huế"],answer:1,explain:"Năm 938, Ngô Quyền đánh tan quân Nam Hán trên sông Bạch Đằng."},{id:"dd5-nguoi-co-cong-04",type:"mc",q:"Ai lãnh đạo khởi nghĩa Lam Sơn chống quân Minh?",options:["Ngô Quyền","Trần Hưng Đạo","Lê Lợi"],answer:2,explain:"Lê Lợi lãnh đạo khởi nghĩa Lam Sơn, giành lại độc lập cho đất nước."},{id:"dd5-nguoi-co-cong-05",type:"tf",q:"Trần Hưng Đạo lãnh đạo quân dân nhà Trần đánh thắng quân Nguyên Mông.",answer:!0,explain:"Đúng. Ông là vị anh hùng dân tộc được nhân dân tôn kính."},{id:"dd5-nguoi-co-cong-06",type:"tf",q:"Ngày 27 tháng 7 là Ngày Thương binh – Liệt sĩ.",answer:!0,explain:"Đúng. Đây là ngày tưởng nhớ, tri ân các thương binh, liệt sĩ."},{id:"dd5-nguoi-co-cong-07",type:"tf",q:"Chỉ những người cầm súng đánh giặc mới là người có công với đất nước.",answer:!1,explain:"Sai. Nhà khoa học, bác sĩ, thầy cô… xây dựng đất nước cũng là người có công."},{id:"dd5-nguoi-co-cong-08",type:"mc",q:"Ngày Giỗ Tổ Hùng Vương là ngày nào?",options:["Mùng 10 tháng 3 âm lịch","Mùng 1 tháng 1 âm lịch","Ngày 2 tháng 9"],answer:0,explain:"Mùng 10 tháng 3 âm lịch là ngày Giỗ Tổ Hùng Vương."},{id:"dd5-nguoi-co-cong-09",type:"match",q:"Nối người có công với việc làm nổi bật.",pairs:[["Hai Bà Trưng","Khởi nghĩa chống quân Đông Hán"],["Quang Trung","Đại phá quân Thanh"],["Trần Hưng Đạo","Đánh thắng quân Nguyên Mông"],["Lê Lợi","Lãnh đạo khởi nghĩa Lam Sơn"]],explain:"Mỗi vị anh hùng gắn với một chiến công giữ nước."}]},{questions:[{id:"dd5-nguoi-co-cong-10",type:"mc",q:"Vì sao chúng ta phải biết ơn những người có công?",options:["Vì họ đều là người nổi tiếng, giàu có","Vì nhờ họ mà đất nước có hòa bình","Vì đó chỉ là quy định ở trường học"],answer:1,explain:"Biết ơn người có công là trân trọng nền độc lập, hòa bình hôm nay."},{id:"dd5-nguoi-co-cong-11",type:"mc",q:"Câu tục ngữ nào nói về lòng biết ơn?",options:["Có công mài sắt có ngày nên kim","Một cây làm chẳng nên non","Uống nước nhớ nguồn"],answer:2,explain:"“Uống nước nhớ nguồn” nhắc ta nhớ ơn những người đi trước."},{id:"dd5-nguoi-co-cong-12",type:"match",q:"Nối nhân vật với lĩnh vực đóng góp.",pairs:[["Tôn Thất Tùng","Y học, phẫu thuật gan"],["Lương Định Của","Nông học, giống lúa"],["Chu Văn An","Dạy học"],["Hải Thượng Lãn Ông","Chữa bệnh, y học cổ truyền"]],explain:"Nhiều người có công ở các lĩnh vực khác nhau."},{id:"dd5-nguoi-co-cong-13",type:"tf",q:"Biết ơn người có công là truyền thống tốt đẹp của dân tộc Việt Nam.",answer:!0,explain:"Đúng. Truyền thống “uống nước nhớ nguồn” được giữ gìn qua nhiều đời."},{id:"dd5-nguoi-co-cong-14",type:"tf",q:"Người có công chỉ có ở thời xưa, ngày nay không còn.",answer:!1,explain:"Sai. Ngày nay vẫn có nhiều người cống hiến cho đất nước ở mọi lĩnh vực."},{id:"dd5-nguoi-co-cong-15",type:"multi",q:"Những người nào đang góp công xây dựng quê hương hôm nay?",options:["Bác sĩ chống dịch bệnh","Chiến sĩ biên phòng giữ biên giới","Nhà khoa học tạo giống cây mới","Người phá hoại cây xanh nơi công cộng"],answers:[0,1,2],explain:"Những người cống hiến cho cộng đồng đều có công với quê hương."},{id:"dd5-nguoi-co-cong-16",type:"mc",q:"Bà mẹ Việt Nam Anh hùng là danh hiệu dành cho ai?",options:["Những người mẹ hi sinh lớn cho đất nước","Những người mẹ có nhiều con nhất xóm","Những người mẹ làm nghề dạy học lâu năm"],answer:0,explain:"Danh hiệu ghi nhận sự hi sinh to lớn của các mẹ cho đất nước."},{id:"dd5-nguoi-co-cong-17",type:"mc",q:"Ngày 22 tháng 12 là ngày gì?",options:["Ngày Nhà giáo Việt Nam hằng năm","Ngày thành lập Quân đội nhân dân Việt Nam","Ngày Quốc tế Thiếu nhi trên thế giới"],answer:1,explain:"Ngày 22 tháng 12 là ngày thành lập Quân đội nhân dân Việt Nam."},{id:"dd5-nguoi-co-cong-18",type:"tf",q:"Các chiến sĩ hải quân canh giữ biển đảo cũng là người có công với đất nước.",answer:!0,explain:"Đúng. Họ ngày đêm bảo vệ chủ quyền biển đảo của Tổ quốc."}]},{questions:[{id:"dd5-nguoi-co-cong-19",type:"mc",q:"Đọc tên đường “Lê Lợi”, “Trần Hưng Đạo”, Minh hỏi vì sao đặt tên như vậy. Câu trả lời nào đúng?",options:["Vì đó là tên những người giàu có","Vì những tên đó dễ đọc, dễ nhớ","Để ghi nhớ, tôn vinh người có công"],answer:2,explain:"Đặt tên đường là một cách tưởng nhớ người có công."},{id:"dd5-nguoi-co-cong-20",type:"tf",q:"Ông của Lan là thương binh. Lan tự hào và kính trọng ông. Lan thể hiện lòng biết ơn đúng đắn.",answer:!0,explain:"Đúng. Kính trọng, tự hào về ông là biểu hiện của lòng biết ơn."},{id:"dd5-nguoi-co-cong-21",type:"mc",q:"Nam nói: “Chuyện chiến tranh xưa rồi, không cần nhớ.” Em nên nói gì với Nam?",options:["Nhờ người đi trước, ta mới có hòa bình","Ừ, chuyện xưa thì quên cũng được","Chỉ người lớn mới cần nhớ chuyện đó"],answer:0,explain:"Nhớ về lịch sử giúp ta trân trọng cuộc sống hôm nay."},{id:"dd5-nguoi-co-cong-22",type:"multi",q:"Ở địa phương, em có thể tìm hiểu về người có công bằng cách nào?",options:["Hỏi ông bà, cha mẹ","Tham quan nhà truyền thống, di tích","Đọc sách, báo đáng tin cậy","Bịa thêm chuyện cho hay"],answers:[0,1,2],explain:"Tìm hiểu qua người thân, di tích và nguồn tin đáng tin giúp em hiểu đúng."},{id:"dd5-nguoi-co-cong-23",type:"mc",q:"Đi qua nghĩa trang liệt sĩ, cách cư xử nào phù hợp?",options:["Nói cười ồn ào, chạy nhảy khắp nơi","Đi nhẹ, nói khẽ, giữ thái độ trang nghiêm","Hái hoa trên mộ mang về nhà chơi"],answer:1,explain:"Nghĩa trang liệt sĩ là nơi thiêng liêng, cần giữ trang nghiêm."},{id:"dd5-nguoi-co-cong-24",type:"tf",q:"Hà nghĩ chỉ cần biết ơn những người có công nổi tiếng trên sách.",answer:!1,explain:"Sai. Em biết ơn cả những người có công thầm lặng ở quê hương mình."},{id:"dd5-nguoi-co-cong-25",type:"mc",q:"Khoa muốn giới thiệu về một người có công ở quê mình. Khoa nên bắt đầu thế nào?",options:["Chép một bài trên mạng mà không kiểm tra","Tự nghĩ ra câu chuyện cho hấp dẫn","Hỏi người lớn và tìm thông tin đáng tin cậy"],answer:2,explain:"Thông tin chính xác giúp bài giới thiệu đúng và ý nghĩa."},{id:"dd5-nguoi-co-cong-26",type:"order",q:"Sắp xếp các nhân vật theo thứ tự thời gian từ xưa đến nay.",items:["Các Vua Hùng","Hai Bà Trưng","Ngô Quyền","Trần Hưng Đạo","Chủ tịch Hồ Chí Minh"],explain:"Các nhân vật nối tiếp nhau trong lịch sử dựng nước và giữ nước."},{id:"dd5-nguoi-co-cong-27",type:"mc",q:"Vy nghe bà kể về các chú bộ đội hi sinh ở quê mình. Vy nên làm gì?",options:["Chăm chú lắng nghe và ghi nhớ công ơn các chú","Nghe qua loa một lúc rồi quên ngay","Bảo bà kể chuyện khác vui hơn"],answer:0,explain:"Lắng nghe, ghi nhớ là bước đầu của lòng biết ơn."}]}],challenge:{questions:[{id:"dd5-nguoi-co-cong-28",type:"multi",q:"Những câu nào đúng về người có công với đất nước?",options:["Có người trong lịch sử và người hôm nay","Có người trong nhiều lĩnh vực khác nhau","Chỉ là những người nổi tiếng","Đều đáng được kính trọng, biết ơn"],answers:[0,1,3],explain:"Người có công ở nhiều thời kì, nhiều lĩnh vực và đều đáng được tri ân."},{id:"dd5-nguoi-co-cong-29",type:"mc",q:"Năm 938, chiến thắng nào mở ra thời kì độc lập lâu dài cho đất nước?",options:["Khởi nghĩa của Hai Bà Trưng","Chiến thắng Bạch Đằng của Ngô Quyền","Khởi nghĩa Lam Sơn của Lê Lợi"],answer:1,explain:"Chiến thắng Bạch Đằng năm 938 mở ra thời kì độc lập lâu dài."},{id:"dd5-nguoi-co-cong-30",type:"tf",q:"Quang Trung là người lãnh đạo khởi nghĩa Lam Sơn.",answer:!1,explain:"Sai. Lê Lợi lãnh đạo khởi nghĩa Lam Sơn; Quang Trung đại phá quân Thanh."},{id:"dd5-nguoi-co-cong-25",type:"mc",q:"Khoa muốn giới thiệu về một người có công ở quê mình. Khoa nên bắt đầu thế nào?",options:["Chép một bài trên mạng mà không kiểm tra","Tự nghĩ ra câu chuyện cho hấp dẫn","Hỏi người lớn và tìm thông tin đáng tin cậy"],answer:2,explain:"Thông tin chính xác giúp bài giới thiệu đúng và ý nghĩa."},{id:"dd5-nguoi-co-cong-24",type:"tf",q:"Hà nghĩ chỉ cần biết ơn những người có công nổi tiếng trên sách.",answer:!1,explain:"Sai. Em biết ơn cả những người có công thầm lặng ở quê hương mình."},{id:"dd5-nguoi-co-cong-18",type:"tf",q:"Các chiến sĩ hải quân canh giữ biển đảo cũng là người có công với đất nước.",answer:!0,explain:"Đúng. Họ ngày đêm bảo vệ chủ quyền biển đảo của Tổ quốc."}]},summary:["Người có công là những người góp công sức dựng nước, giữ nước và xây dựng đất nước.","Có người có công trong lịch sử và trong cuộc sống hôm nay.","Cuộc sống hòa bình hôm nay có được là nhờ công lao của họ."]},{id:"dd5-bay-to-biet-on",title:"Bài 2: Bày tỏ lòng biết ơn người có công",weeks:[3,4],learn:[{title:"Bày tỏ bằng thái độ",text:"Kính trọng, tự hào, ghi nhớ công lao; trang nghiêm ở những nơi tưởng niệm.",example:"🙏 kính trọng · 🕯️ tưởng nhớ"},{title:"Bày tỏ bằng việc làm",text:"Thăm hỏi gia đình thương binh, liệt sĩ; chăm sóc nghĩa trang liệt sĩ; tham gia hoạt động đền ơn đáp nghĩa; học tập, tìm hiểu về người có công.",example:"🌸 dâng hoa · 🧹 dọn nghĩa trang"},{title:"Bày tỏ bằng sự cố gắng",text:"Chăm ngoan, học giỏi, sống có ích là cách tốt nhất để tiếp nối công lao của người đi trước.",example:"📚 học tốt · 🌱 sống có ích"}],practice:[{questions:[{id:"dd5-bay-to-biet-on-01",type:"multi",q:"Việc làm nào thể hiện lòng biết ơn người có công?",options:["Thăm hỏi gia đình thương binh, liệt sĩ","Dọn dẹp nghĩa trang liệt sĩ","Viết bậy lên bia tưởng niệm","Tìm hiểu về các anh hùng"],answers:[0,1,3],explain:"Thăm hỏi, chăm sóc nơi tưởng niệm và tìm hiểu là những cách bày tỏ lòng biết ơn."},{id:"dd5-bay-to-biet-on-02",type:"tf",q:"Học tập chăm chỉ, sống có ích cũng là cách bày tỏ lòng biết ơn người có công.",answer:!0,explain:"Đúng. Đó là cách tiếp nối công lao của người đi trước."},{id:"dd5-bay-to-biet-on-03",type:"tf",q:"Lòng biết ơn chỉ cần thể hiện vào ngày lễ.",answer:!1,explain:"Sai. Em có thể bày tỏ lòng biết ơn mỗi ngày bằng việc làm tốt."},{id:"dd5-bay-to-biet-on-04",type:"mc",q:"Khi chào cờ, em cần làm gì?",options:["Đứng nghiêm, hát Quốc ca trang nghiêm","Nói chuyện riêng với bạn bên cạnh","Cúi xuống buộc lại dây giày"],answer:0,explain:"Nghiêm trang khi chào cờ là thể hiện lòng yêu nước, biết ơn."},{id:"dd5-bay-to-biet-on-05",type:"mc",q:"Phong trào giúp đỡ gia đình người có công thường được gọi là gì?",options:["Lá lành đùm lá rách","Đền ơn đáp nghĩa","Kế hoạch nhỏ"],answer:1,explain:"“Đền ơn đáp nghĩa” là phong trào tri ân người có công."},{id:"dd5-bay-to-biet-on-06",type:"mc",q:"Việc làm nào chưa thể hiện lòng biết ơn?",options:["Dâng hoa ở đài tưởng niệm","Lắng nghe chuyện kể về anh hùng","Đùa nghịch, leo trèo ở đài tưởng niệm"],answer:2,explain:"Đài tưởng niệm cần được giữ gìn và tôn trọng."},{id:"dd5-bay-to-biet-on-07",type:"tf",q:"Giữ gìn, không làm hỏng di tích lịch sử là biết ơn người có công.",answer:!0,explain:"Đúng. Di tích ghi dấu công lao của người đi trước."},{id:"dd5-bay-to-biet-on-08",type:"tf",q:"Gặp thương binh, em không cần chào hỏi vì không quen.",answer:!1,explain:"Sai. Em lễ phép chào hỏi để thể hiện sự kính trọng."},{id:"dd5-bay-to-biet-on-09",type:"mc",q:"Ngày 27 tháng 7, trường em có thể tổ chức hoạt động gì?",options:["Thăm hỏi gia đình thương binh, liệt sĩ","Tổ chức thi ăn nhanh ở sân trường","Cho học sinh nghỉ học để đi chơi xa"],answer:0,explain:"Ngày Thương binh – Liệt sĩ là dịp tri ân người có công."}]},{questions:[{id:"dd5-bay-to-biet-on-10",type:"match",q:"Nối việc làm với cách bày tỏ lòng biết ơn.",pairs:[["Dâng hương ở đài tưởng niệm","Tưởng nhớ"],["Thăm bà mẹ Việt Nam Anh hùng","Thăm hỏi, chăm sóc"],["Tìm hiểu về anh hùng ở quê mình","Học tập, ghi nhớ"],["Chăm ngoan, học giỏi","Tiếp nối công lao"]],explain:"Có nhiều cách bày tỏ lòng biết ơn, phù hợp với từng hoàn cảnh."},{id:"dd5-bay-to-biet-on-11",type:"mc",q:"Vì sao nói học tập tốt là cách tốt nhất để biết ơn người có công?",options:["Vì học giỏi sẽ được khen thưởng nhiều","Vì đó là điều người đi trước mong mỏi","Vì học giỏi thì không phải làm gì khác"],answer:1,explain:"Người đi trước hi sinh để thế hệ sau học tập, xây dựng đất nước."},{id:"dd5-bay-to-biet-on-12",type:"tf",q:"Viết thư hỏi thăm các chú bộ đội ở biên giới, hải đảo là một cách bày tỏ lòng biết ơn.",answer:!0,explain:"Đúng. Những lá thư động viên tiếp thêm sức mạnh cho các chú."},{id:"dd5-bay-to-biet-on-13",type:"multi",q:"Hành vi nào thiếu tôn trọng người có công?",options:["Chế giễu người khuyết tật do chiến tranh","Xả rác ở nghĩa trang liệt sĩ","Đặt hoa lên đài tưởng niệm","Chạy nhảy trong buổi lễ tưởng niệm"],answers:[0,1,3],explain:"Những hành vi này làm tổn thương và thiếu tôn trọng người có công."},{id:"dd5-bay-to-biet-on-14",type:"tf",q:"Biết ơn người có công thì phải làm những việc thật lớn lao.",answer:!1,explain:"Sai. Việc nhỏ như lời chào lễ phép, bó hoa tưởng niệm cũng rất ý nghĩa."},{id:"dd5-bay-to-biet-on-15",type:"mc",q:"Phút mặc niệm trong lễ tưởng niệm có ý nghĩa gì?",options:["Để nghỉ ngơi sau khi đứng lâu","Để chờ đến lượt được phát quà","Để tưởng nhớ những người đã hi sinh"],answer:2,explain:"Phút mặc niệm thể hiện sự tưởng nhớ, biết ơn."},{id:"dd5-bay-to-biet-on-16",type:"mc",q:"Bạn nào thể hiện lòng biết ơn đúng cách?",options:["Bạn Chi kể lại chuyện anh hùng ở quê mình","Bạn Tùng nói chuyện riêng khi cô kể về liệt sĩ","Bạn Dũng chê bài hát về chiến sĩ là cũ"],answer:0,explain:"Tìm hiểu và kể lại giúp lan tỏa lòng biết ơn."},{id:"dd5-bay-to-biet-on-17",type:"tf",q:"Chăm sóc cây xanh ở nghĩa trang liệt sĩ là việc làm vừa sức của học sinh.",answer:!0,explain:"Đúng. Đó là việc làm nhỏ nhưng thể hiện tấm lòng tri ân."},{id:"dd5-bay-to-biet-on-18",type:"order",q:"Sắp xếp các bước chuẩn bị đi thăm một gia đình thương binh cùng lớp.",items:["Cùng cô chọn ngày và hỏi ý gia đình","Chuẩn bị quà nhỏ và lời thăm hỏi","Đến thăm, chào hỏi lễ phép","Lắng nghe chuyện kể và cảm ơn gia đình"],explain:"Chuẩn bị chu đáo giúp buổi thăm hỏi ý nghĩa."}]},{questions:[{id:"dd5-bay-to-biet-on-19",type:"mc",q:"Lớp Lan được giao chăm sóc một phần mộ liệt sĩ. Việc nào phù hợp?",options:["Cắm cờ trang trí thật nhiều cho đẹp","Quét lá, nhổ cỏ, lau bia mộ cẩn thận","Đến khi nào nhớ thì đến"],answer:1,explain:"Chăm sóc đều đặn, cẩn thận là cách tri ân thiết thực."},{id:"dd5-bay-to-biet-on-20",type:"tf",q:"Thấy bạn đùa nghịch trong buổi lễ dâng hương, Minh nhẹ nhàng nhắc bạn giữ trật tự. Minh làm đúng.",answer:!0,explain:"Đúng. Nhắc bạn giúp buổi lễ diễn ra trang nghiêm."},{id:"dd5-bay-to-biet-on-21",type:"multi",q:"Nhà Khoa gần một cụ bà là mẹ liệt sĩ sống một mình. Khoa có thể làm gì?",options:["Thường xuyên sang thăm hỏi","Giúp cụ quét nhà, tưới cây","Trêu đùa khi cụ đi chậm","Đọc báo cho cụ nghe"],answers:[0,1,3],explain:"Những việc vừa sức, thường xuyên làm cụ vui và ấm lòng."},{id:"dd5-bay-to-biet-on-22",type:"mc",q:"Hà được giao kể chuyện về một anh hùng trong buổi sinh hoạt. Hà nên làm gì?",options:["Kể đại khái, sai cũng không sao","Từ chối vì ngại","Tìm hiểu kĩ, kể chính xác và xúc động"],answer:2,explain:"Kể đúng và có cảm xúc giúp các bạn hiểu và biết ơn hơn."},{id:"dd5-bay-to-biet-on-23",type:"tf",q:"Phúc nói: “Thương binh được Nhà nước chăm lo rồi nên mình không cần quan tâm.” Phúc nghĩ đúng.",answer:!1,explain:"Sai. Mỗi người đều có thể bày tỏ lòng biết ơn bằng sự quan tâm của mình."},{id:"dd5-bay-to-biet-on-24",type:"mc",q:"Đi tham quan di tích, Vy thấy bạn khắc tên lên tường. Vy nên làm gì?",options:["Nhắc bạn dừng lại và báo thầy cô","Khắc tên mình ngay bên cạnh","Chụp ảnh lại để khoe với bạn"],answer:0,explain:"Bảo vệ di tích là cách tôn trọng lịch sử và người có công."},{id:"dd5-bay-to-biet-on-25",type:"mc",q:"Tùng muốn viết thư cho chú bộ đội ở hải đảo. Nội dung nào phù hợp?",options:["Kể chuyện chê bai các bạn cùng lớp","Hỏi thăm sức khỏe, cảm ơn và hứa học tập tốt","Xin chú gửi thật nhiều quà về cho mình"],answer:1,explain:"Lời hỏi thăm, cảm ơn và lời hứa học tốt sẽ làm chú vui."},{id:"dd5-bay-to-biet-on-26",type:"order",q:"Sắp xếp các việc trong buổi dâng hương ở đài tưởng niệm.",items:["Xếp hàng ngay ngắn, trật tự","Dâng hoa, dâng hương","Đứng mặc niệm tưởng nhớ"],explain:"Thực hiện trang nghiêm theo thứ tự giúp buổi lễ ý nghĩa."},{id:"dd5-bay-to-biet-on-27",type:"mc",q:"Ngọc nói: “Mình còn nhỏ, chưa làm được gì để biết ơn người có công.” Em nói gì với Ngọc?",options:["Đúng, phải lớn lên mới làm được","Bạn chỉ cần đợi đến ngày lễ là được","Bạn có thể học tốt và giữ gìn di tích"],answer:2,explain:"Ở lứa tuổi nào em cũng có việc làm phù hợp để bày tỏ lòng biết ơn."}]}],challenge:{questions:[{id:"dd5-bay-to-biet-on-28",type:"multi",q:"Những cách nào bày tỏ lòng biết ơn người có công?",options:["Thái độ kính trọng, trang nghiêm","Việc làm đền ơn đáp nghĩa","Học tập, sống có ích","Chỉ nói trên mạng cho nhiều người biết"],answers:[0,1,2],explain:"Lòng biết ơn thể hiện qua thái độ, việc làm và sự cố gắng."},{id:"dd5-bay-to-biet-on-29",type:"tf",q:"Chỉ cần dâng hoa một lần mỗi năm là đã đủ biết ơn người có công.",answer:!1,explain:"Sai. Lòng biết ơn được thể hiện thường xuyên qua lời nói, việc làm hằng ngày."},{id:"dd5-bay-to-biet-on-30",type:"mc",q:"“Ăn quả nhớ kẻ trồng cây” có ý nghĩa giống câu nào?",options:["Uống nước nhớ nguồn","Gần mực thì đen","Tốt gỗ hơn tốt nước sơn"],answer:0,explain:"Cả hai câu đều nhắc ta nhớ ơn người đã làm nên thành quả."},{id:"dd5-bay-to-biet-on-21",type:"multi",q:"Nhà Khoa gần một cụ bà là mẹ liệt sĩ sống một mình. Khoa có thể làm gì?",options:["Thường xuyên sang thăm hỏi","Giúp cụ quét nhà, tưới cây","Trêu đùa khi cụ đi chậm","Đọc báo cho cụ nghe"],answers:[0,1,3],explain:"Những việc vừa sức, thường xuyên làm cụ vui và ấm lòng."},{id:"dd5-bay-to-biet-on-24",type:"mc",q:"Đi tham quan di tích, Vy thấy bạn khắc tên lên tường. Vy nên làm gì?",options:["Nhắc bạn dừng lại và báo thầy cô","Khắc tên mình ngay bên cạnh","Chụp ảnh lại để khoe với bạn"],answer:0,explain:"Bảo vệ di tích là cách tôn trọng lịch sử và người có công."},{id:"dd5-bay-to-biet-on-26",type:"order",q:"Sắp xếp các việc trong buổi dâng hương ở đài tưởng niệm.",items:["Xếp hàng ngay ngắn, trật tự","Dâng hoa, dâng hương","Đứng mặc niệm tưởng nhớ"],explain:"Thực hiện trang nghiêm theo thứ tự giúp buổi lễ ý nghĩa."}]},summary:["Em bày tỏ lòng biết ơn bằng thái độ kính trọng và việc làm cụ thể.","Tham gia các hoạt động đền ơn đáp nghĩa phù hợp lứa tuổi.","Học tập tốt, sống có ích là cách tiếp nối công lao người đi trước."]}]},{id:"ton-trong-su-khac-biet",title:"Tôn trọng sự khác biệt của người khác",lessons:[{id:"dd5-moi-nguoi-mot-ve",title:"Bài 3: Mỗi người một vẻ",weeks:[5,6],learn:[{title:"Sự khác biệt",text:"Mỗi người khác nhau về ngoại hình, giọng nói, sở thích, tính cách, hoàn cảnh, dân tộc, phong tục, khả năng…",example:"🧒🏻 🧒🏽 🧒🏿 mỗi bạn một vẻ"},{title:"Vì sao phải tôn trọng?",text:"Ai cũng muốn được tôn trọng. Tôn trọng sự khác biệt giúp mọi người hiểu nhau, sống hòa thuận và học hỏi được nhiều điều hay.",example:"🤝 hòa thuận · 🌈 đa dạng"},{title:"Biểu hiện của sự tôn trọng",text:"Lắng nghe, không chê bai, không chế giễu, không xa lánh người khác vì họ khác mình; cư xử công bằng với mọi người.",example:"👂 lắng nghe · 🚫 chế giễu"}],practice:[{questions:[{id:"dd5-moi-nguoi-mot-ve-01",type:"multi",q:"Mọi người có thể khác nhau về những điều gì?",options:["Ngoại hình","Sở thích","Giọng nói","Hoàn cảnh gia đình"],answers:[0,1,2,3],explain:"Mỗi người đều có những điểm khác biệt riêng."},{id:"dd5-moi-nguoi-mot-ve-02",type:"tf",q:"Mỗi người có ngoại hình, sở thích, tính cách khác nhau là điều bình thường.",answer:!0,explain:"Đúng. Sự khác biệt làm cuộc sống thêm phong phú."},{id:"dd5-moi-nguoi-mot-ve-03",type:"tf",q:"Bạn có sở thích khác mình là bạn kì lạ.",answer:!1,explain:"Sai. Sở thích khác nhau là điều bình thường, không có gì kì lạ."},{id:"dd5-moi-nguoi-mot-ve-04",type:"mc",q:"Việc làm nào thể hiện sự tôn trọng sự khác biệt?",options:["Lắng nghe ý kiến khác với mình","Đặt biệt danh theo ngoại hình của bạn","Bắt chước giọng nói của bạn để trêu"],answer:0,explain:"Lắng nghe ý kiến khác mình là biểu hiện của sự tôn trọng."},{id:"dd5-moi-nguoi-mot-ve-05",type:"mc",q:"Việc làm nào chưa tôn trọng sự khác biệt?",options:["Học hỏi món ăn của bạn dân tộc khác","Chê cười trang phục truyền thống của bạn","Chơi cùng bạn có sở thích khác"],answer:1,explain:"Chê cười trang phục truyền thống là thiếu tôn trọng văn hóa của bạn."},{id:"dd5-moi-nguoi-mot-ve-06",type:"mc",q:"Việt Nam có bao nhiêu dân tộc anh em cùng chung sống?",options:["34 dân tộc","64 dân tộc","54 dân tộc"],answer:2,explain:"Việt Nam có 54 dân tộc anh em, mỗi dân tộc có nét văn hóa riêng."},{id:"dd5-moi-nguoi-mot-ve-07",type:"tf",q:"Tôn trọng sự khác biệt giúp em học hỏi được nhiều điều hay từ người khác.",answer:!0,explain:"Đúng. Mỗi người có điều riêng đáng để em học hỏi."},{id:"dd5-moi-nguoi-mot-ve-08",type:"tf",q:"Bạn khuyết tật thì không nên tham gia các hoạt động của lớp.",answer:!1,explain:"Sai. Bạn khuyết tật cũng có quyền tham gia; cả lớp cùng giúp bạn tham gia phù hợp."},{id:"dd5-moi-nguoi-mot-ve-09",type:"mc",q:"Thái độ nào đúng khi gặp người có phong tục khác mình?",options:["Tìm hiểu và tôn trọng","Chê là lạc hậu","Tránh xa không nói chuyện"],answer:0,explain:"Tìm hiểu, tôn trọng phong tục khác giúp em hiểu biết rộng hơn."}]},{questions:[{id:"dd5-moi-nguoi-mot-ve-10",type:"mc",q:"Vì sao cần tôn trọng sự khác biệt của người khác?",options:["Vì để người khác phải giống mình","Vì ai cũng muốn được tôn trọng","Vì sợ người khác sẽ giận mình"],answer:1,explain:"Tôn trọng nhau giúp mọi người hiểu nhau và sống hòa thuận."},{id:"dd5-moi-nguoi-mot-ve-11",type:"match",q:"Nối biểu hiện với nhận xét.",pairs:[["Lắng nghe ý kiến khác","Tôn trọng"],["Đặt biệt danh xấu cho bạn","Chế giễu"],["Không cho bạn mới chơi cùng","Xa lánh"],["Học hỏi điều hay của bạn","Cởi mở"]],explain:"Phân biệt biểu hiện tôn trọng và không tôn trọng giúp em cư xử đúng."},{id:"dd5-moi-nguoi-mot-ve-12",type:"tf",q:"Không phán xét người khác chỉ qua vẻ bề ngoài là tôn trọng sự khác biệt.",answer:!0,explain:"Đúng. Vẻ ngoài không nói lên hết giá trị của một người."},{id:"dd5-moi-nguoi-mot-ve-13",type:"multi",q:"Những câu nói nào thể hiện sự tôn trọng?",options:["Ý kiến của bạn hay đấy, mình nghĩ hơi khác một chút","Bạn nói gì kì vậy, chẳng ai nghĩ thế","Kể cho mình nghe về Tết của dân tộc bạn nhé","Mỗi người một sở thích mà"],answers:[0,2,3],explain:"Lời nói tôn trọng giúp mọi người thoải mái chia sẻ."},{id:"dd5-moi-nguoi-mot-ve-14",type:"tf",q:"Tôn trọng sự khác biệt nghĩa là phải đồng ý với mọi ý kiến của người khác.",answer:!1,explain:"Sai. Em có thể có ý kiến khác nhưng vẫn lắng nghe và nói lịch sự."},{id:"dd5-moi-nguoi-mot-ve-15",type:"mc",q:"Câu tục ngữ nào khuyên mọi người đoàn kết dù khác nhau?",options:["Ăn cây nào rào cây ấy, ở đâu lo đấy","Đi một ngày đàng, học một sàng khôn","Bầu ơi thương lấy bí cùng, tuy rằng khác giống nhưng chung một giàn"],answer:2,explain:"Câu ca dao khuyên mọi người thương yêu, đùm bọc nhau dù khác biệt."},{id:"dd5-moi-nguoi-mot-ve-16",type:"mc",q:"Khi bạn trong nhóm có cách làm khác mình, em nên làm gì?",options:["Lắng nghe và cùng chọn cách phù hợp","Bắt bạn làm theo đúng cách của mình","Không làm cùng bạn đó nữa"],answer:0,explain:"Lắng nghe và bàn bạc giúp nhóm tìm ra cách làm tốt nhất."},{id:"dd5-moi-nguoi-mot-ve-17",type:"tf",q:"Bạn trai thích nấu ăn, bạn gái thích đá bóng đều là điều bình thường.",answer:!0,explain:"Đúng. Sở thích không phân biệt bạn trai hay bạn gái."},{id:"dd5-moi-nguoi-mot-ve-18",type:"mc",q:"Chế giễu sự khác biệt của người khác có thể gây ra điều gì?",options:["Làm người đó vui vẻ hơn","Làm người đó buồn và tự ti","Không gây ra điều gì cả"],answer:1,explain:"Lời chế giễu gây tổn thương và chia rẽ mọi người."}]},{questions:[{id:"dd5-moi-nguoi-mot-ve-19",type:"mc",q:"Lớp có bạn mới là người dân tộc Mông, nói tiếng Việt chưa thạo. Em nên làm gì?",options:["Bắt chước giọng của bạn cho vui","Ngồi xa bạn vì khó nói chuyện","Kiên nhẫn trò chuyện và giúp bạn"],answer:2,explain:"Kiên nhẫn, thân thiện giúp bạn mới hòa nhập."},{id:"dd5-moi-nguoi-mot-ve-20",type:"tf",q:"Nam đeo kính dày, các bạn gọi Nam là “bốn mắt” cho vui. Đó là trò đùa vô hại.",answer:!1,explain:"Sai. Gọi biệt danh theo ngoại hình làm Nam buồn, cần dừng lại."},{id:"dd5-moi-nguoi-mot-ve-21",type:"multi",q:"Thảo thích đọc sách, ít nói. Có bạn bảo Thảo “khó gần”. Em có thể làm gì?",options:["Hiểu rằng mỗi người một tính cách","Rủ Thảo cùng đọc và kể chuyện về sách","Hùa theo bạn nói Thảo khó gần","Nhắc bạn đừng gán cho Thảo những lời không hay"],answers:[0,1,3],explain:"Tôn trọng tính cách của Thảo giúp bạn thấy thoải mái."},{id:"dd5-moi-nguoi-mot-ve-22",type:"mc",q:"Bình ăn chay theo thói quen gia đình. Giờ ăn bán trú, có bạn trêu. Em nên nói gì?",options:["Mỗi nhà có thói quen riêng, nên tôn trọng","Ăn chay thì lạ thật, chẳng ai như thế","Bạn nên ăn giống mọi người cho dễ"],answer:0,explain:"Tôn trọng thói quen của bạn là cách cư xử văn minh."},{id:"dd5-moi-nguoi-mot-ve-23",type:"mc",q:"Trong cuộc thi vẽ, tranh của Vy rất khác mọi người. Cách nhận xét nào phù hợp?",options:["Tranh lạ quá, chẳng giống ai trong lớp","Tranh có ý tưởng riêng, bạn kể mình nghe nhé","Bạn nên vẽ lại cho giống các bạn khác"],answer:1,explain:"Ghi nhận ý tưởng riêng là tôn trọng sự sáng tạo của bạn."},{id:"dd5-moi-nguoi-mot-ve-24",type:"tf",q:"Khoa nói giọng miền Trung, Lan thích thú hỏi Khoa về các từ địa phương. Lan tôn trọng sự khác biệt.",answer:!0,explain:"Đúng. Tò mò học hỏi một cách thân thiện là tôn trọng."},{id:"dd5-moi-nguoi-mot-ve-25",type:"mc",q:"Dũng học chậm hơn các bạn. Thái độ nào phù hợp?",options:["Gọi Dũng là “chậm chạp” cho vui","Không cho Dũng vào nhóm học tập","Kiên nhẫn giúp Dũng tiến bộ"],answer:2,explain:"Mỗi người tiến bộ theo cách riêng; giúp đỡ và động viên là tôn trọng."},{id:"dd5-moi-nguoi-mot-ve-26",type:"order",q:"Sắp xếp cách ứng xử khi nhóm có ý kiến khác nhau.",items:["Lắng nghe từng bạn nói hết ý","Hỏi lại cho rõ ý của bạn","Nêu ý kiến của mình lịch sự","Cùng thống nhất cách làm"],explain:"Lắng nghe trước, nói sau giúp nhóm hiểu nhau."},{id:"dd5-moi-nguoi-mot-ve-27",type:"mc",q:"Ngọc thấy một bạn đăng bình luận chê bai ngoại hình người khác trên mạng. Ngọc nên làm gì?",options:["Không hùa theo và nhắc bạn dừng lại","Thả biểu tượng cười để hưởng ứng","Chia sẻ thêm cho vui"],answer:0,explain:"Không hùa theo lời chê bai là cách bảo vệ sự tôn trọng."}]}],challenge:{questions:[{id:"dd5-moi-nguoi-mot-ve-28",type:"multi",q:"Những câu nào nói đúng về sự khác biệt?",options:["Mỗi người đều có điểm khác biệt","Khác biệt làm cuộc sống phong phú","Ai khác mình là người kém hơn","Cần tôn trọng sự khác biệt"],answers:[0,1,3],explain:"Khác biệt là bình thường và đáng được tôn trọng."},{id:"dd5-moi-nguoi-mot-ve-29",type:"tf",q:"Bạn nghèo hơn mình thì không cần được tôn trọng bằng.",answer:!1,explain:"Sai. Ai cũng xứng đáng được tôn trọng như nhau."},{id:"dd5-moi-nguoi-mot-ve-30",type:"mc",q:"Câu nào thể hiện thái độ cởi mở với sự khác biệt?",options:["Không giống mình thì không phải bạn","Mỗi người một vẻ, mười phân vẹn mười","Phải giống nhau mới chơi được"],answer:1,explain:"Câu này khen rằng mỗi người đều có vẻ đẹp riêng."},{id:"dd5-moi-nguoi-mot-ve-19",type:"mc",q:"Lớp có bạn mới là người dân tộc Mông, nói tiếng Việt chưa thạo. Em nên làm gì?",options:["Bắt chước giọng của bạn cho vui","Ngồi xa bạn vì khó nói chuyện","Kiên nhẫn trò chuyện và giúp bạn"],answer:2,explain:"Kiên nhẫn, thân thiện giúp bạn mới hòa nhập."},{id:"dd5-moi-nguoi-mot-ve-21",type:"multi",q:"Thảo thích đọc sách, ít nói. Có bạn bảo Thảo “khó gần”. Em có thể làm gì?",options:["Hiểu rằng mỗi người một tính cách","Rủ Thảo cùng đọc và kể chuyện về sách","Hùa theo bạn nói Thảo khó gần","Nhắc bạn đừng gán cho Thảo những lời không hay"],answers:[0,1,3],explain:"Tôn trọng tính cách của Thảo giúp bạn thấy thoải mái."},{id:"dd5-moi-nguoi-mot-ve-27",type:"mc",q:"Ngọc thấy một bạn đăng bình luận chê bai ngoại hình người khác trên mạng. Ngọc nên làm gì?",options:["Không hùa theo và nhắc bạn dừng lại","Thả biểu tượng cười để hưởng ứng","Chia sẻ thêm cho vui"],answer:0,explain:"Không hùa theo lời chê bai là cách bảo vệ sự tôn trọng."}]},summary:["Mỗi người có những điểm khác biệt riêng.","Tôn trọng sự khác biệt giúp mọi người hiểu nhau và sống hòa thuận.","Không chê bai, chế giễu, xa lánh người khác vì họ khác mình."]},{id:"dd5-ung-xu-ton-trong",title:"Bài 4: Ứng xử tôn trọng sự khác biệt",weeks:[7,8],learn:[{title:"Cách ứng xử",text:"Lắng nghe, hỏi han thân thiện, nói lời lịch sự; không gán biệt danh, không bắt người khác phải giống mình.",example:"💬 “Bạn kể cho mình nghe nhé!”"},{title:"Đối xử công bằng",text:"Không phân biệt đối xử vì giới tính, dân tộc, hoàn cảnh, ngoại hình hay khả năng. Ai cũng được tham gia, được chia sẻ ý kiến.",example:"⚖️ công bằng · 🤗 hòa nhập"},{title:"Khi thấy người khác bị phân biệt",text:"Không hùa theo; lên tiếng nhẹ nhàng; động viên người bị trêu; báo thầy cô nếu việc trêu chọc kéo dài.",example:"🙋 lên tiếng · 💛 động viên"}],practice:[{questions:[{id:"dd5-ung-xu-ton-trong-01",type:"tf",q:"Lắng nghe người khác nói hết ý là cách tôn trọng họ.",answer:!0,explain:"Đúng. Lắng nghe cho thấy em coi trọng ý kiến người khác."},{id:"dd5-ung-xu-ton-trong-02",type:"tf",q:"Chỉ nên chia nhóm với các bạn giống mình.",answer:!1,explain:"Sai. Làm việc với bạn khác mình giúp em học được nhiều điều mới."},{id:"dd5-ung-xu-ton-trong-03",type:"mc",q:"Cách hỏi nào thân thiện khi muốn tìm hiểu phong tục của bạn?",options:["Bạn kể cho mình nghe về phong tục này nhé?","Sao nhà bạn lại làm kì vậy?","Phong tục đó có gì hay đâu mà làm?"],answer:0,explain:"Hỏi thân thiện giúp bạn vui vẻ chia sẻ."},{id:"dd5-ung-xu-ton-trong-04",type:"mc",q:"Phân biệt đối xử là gì?",options:["Đối xử tốt với tất cả mọi người","Đối xử bất công với người khác mình","Chia đều phần việc cho mọi người"],answer:1,explain:"Phân biệt đối xử là việc làm sai, gây tổn thương."},{id:"dd5-ung-xu-ton-trong-05",type:"multi",q:"Những việc làm nào thể hiện ứng xử tôn trọng?",options:["Gọi bạn bằng tên","Mời bạn mới cùng chơi","Chê giọng nói địa phương của bạn","Lắng nghe bạn trình bày"],answers:[0,1,3],explain:"Gọi tên, mời chơi, lắng nghe là cách cư xử tôn trọng."},{id:"dd5-ung-xu-ton-trong-06",type:"tf",q:"Khi thấy bạn bị trêu chọc, em không nên hùa theo.",answer:!0,explain:"Đúng. Không hùa theo là bước đầu để bảo vệ bạn."},{id:"dd5-ung-xu-ton-trong-07",type:"mc",q:"Việc làm nào là phân biệt đối xử?",options:["Mời tất cả các bạn cùng tham gia","Chia đội đều theo lượt","Không cho bạn vào đội vì bạn thấp"],answer:2,explain:"Loại bạn vì ngoại hình là phân biệt đối xử."},{id:"dd5-ung-xu-ton-trong-08",type:"mc",q:"Khi ý kiến của em khác với bạn, em nên nói thế nào?",options:["Mình có ý kiến khác, bạn nghe thử nhé","Bạn sai rồi, im đi cho mình nói","Mình không thèm nói chuyện với bạn"],answer:0,explain:"Nói lịch sự giúp hai bạn cùng trao đổi vui vẻ."},{id:"dd5-ung-xu-ton-trong-09",type:"tf",q:"Gọi bạn bằng biệt danh xấu là cách thể hiện thân thiết.",answer:!1,explain:"Sai. Biệt danh xấu làm bạn buồn, em nên gọi bạn bằng tên."}]},{questions:[{id:"dd5-ung-xu-ton-trong-10",type:"match",q:"Nối tình huống với cách ứng xử tôn trọng.",pairs:[["Bạn nói giọng vùng khác","Không bắt chước để trêu"],["Bạn có hoàn cảnh khó khăn","Không bàn tán, sẵn lòng giúp"],["Bạn có ý kiến khác","Lắng nghe, trao đổi lịch sự"],["Bạn khuyết tật","Giúp bạn cùng tham gia"]],explain:"Mỗi tình huống cần một cách ứng xử tôn trọng phù hợp."},{id:"dd5-ung-xu-ton-trong-11",type:"mc",q:"Vì sao không nên phân biệt đối xử?",options:["Vì sẽ bị cô giáo phạt nặng","Vì làm người khác tổn thương","Vì mất thời gian chọn bạn chơi"],answer:1,explain:"Phân biệt đối xử gây buồn đau và chia rẽ."},{id:"dd5-ung-xu-ton-trong-12",type:"tf",q:"Đối xử công bằng giúp mọi người cảm thấy mình được tôn trọng và thuộc về tập thể.",answer:!0,explain:"Đúng. Công bằng làm tập thể gắn bó hơn."},{id:"dd5-ung-xu-ton-trong-13",type:"multi",q:"Khi thấy bạn bị chế giễu, em có thể làm gì?",options:["Không cười theo","Nói “Đừng trêu bạn nữa”","Đến hỏi han, động viên bạn","Quay video để đăng lên mạng"],answers:[0,1,2],explain:"Không hùa theo, lên tiếng và động viên là cách bảo vệ bạn."},{id:"dd5-ung-xu-ton-trong-14",type:"tf",q:"Tôn trọng sự khác biệt là để mặc người khác làm điều sai.",answer:!1,explain:"Sai. Em tôn trọng sự khác biệt nhưng vẫn góp ý khi thấy việc sai."},{id:"dd5-ung-xu-ton-trong-15",type:"mc",q:"Câu nào phù hợp khi bạn kể về món ăn lạ của quê mình?",options:["Nghe có vẻ chẳng ngon lành gì cả","Món đó chắc chẳng ai ăn được đâu","Thú vị quá, món đó làm thế nào vậy bạn?"],answer:2,explain:"Hỏi han thú vị thể hiện sự tôn trọng và ham học hỏi."},{id:"dd5-ung-xu-ton-trong-16",type:"mc",q:"Trong nhóm, bạn Hà ít nói nên ít được hỏi ý kiến. Nhóm trưởng nên làm gì?",options:["Mời Hà nói ý kiến và lắng nghe","Để Hà ngồi im cho nhanh xong","Giao hết những việc khó cho Hà"],answer:0,explain:"Mời mọi người cùng nói giúp nhóm công bằng và có nhiều ý hay."},{id:"dd5-ung-xu-ton-trong-17",type:"tf",q:"Tôn trọng sự khác biệt cũng là tôn trọng quyền được là chính mình của người khác.",answer:!0,explain:"Đúng. Ai cũng có quyền giữ nét riêng của mình."},{id:"dd5-ung-xu-ton-trong-18",type:"order",q:"Sắp xếp các việc khi thấy bạn bị trêu chọc nhiều lần.",items:["Không hùa theo","Nhắc các bạn dừng lại","Động viên bạn bị trêu","Báo thầy cô nếu việc trêu vẫn tiếp diễn"],explain:"Từng bước nhẹ nhàng đến nhờ thầy cô giúp bạn được bảo vệ."}]},{questions:[{id:"dd5-ung-xu-ton-trong-19",type:"mc",q:"Tùng mặc lại áo cũ của anh trai nên có bạn chê “áo cũ”. Em nên làm gì?",options:["Cười theo các bạn cho vui","Nhắc các bạn đừng chê áo của Tùng","Bảo Tùng đừng mặc áo đó nữa"],answer:1,explain:"Hoàn cảnh hay quần áo không làm giá trị của bạn kém đi."},{id:"dd5-ung-xu-ton-trong-20",type:"tf",q:"Lớp bầu đội trưởng đội văn nghệ, Minh đề cử bạn Chi múa giỏi dù Chi không thân với Minh. Minh cư xử công bằng.",answer:!0,explain:"Đúng. Minh đánh giá theo khả năng, không theo tình cảm riêng."},{id:"dd5-ung-xu-ton-trong-21",type:"multi",q:"Lớp có bạn Phúc đi xe lăn. Cả lớp có thể làm gì để Phúc tham gia buổi dã ngoại?",options:["Chọn lối đi bằng phẳng","Phân công bạn đi cùng hỗ trợ","Chọn trò chơi Phúc cũng chơi được","Để Phúc ở nhà cho tiện"],answers:[0,1,2],explain:"Cả lớp cùng điều chỉnh để ai cũng được tham gia."},{id:"dd5-ung-xu-ton-trong-22",type:"mc",q:"Khi tranh luận, Nam nói to và ngắt lời bạn. Em góp ý thế nào?",options:["Nói to hơn nữa để Nam phải nghe","Bỏ đi, không tranh luận nữa","Nhắc Nam để bạn nói hết rồi mới trả lời"],answer:2,explain:"Để người khác nói hết ý là cách tranh luận tôn trọng."},{id:"dd5-ung-xu-ton-trong-23",type:"tf",q:"Lan không mời bạn mới đến dự sinh nhật vì bạn “nhà ở xa, nói giọng lạ”. Lan làm vậy là hợp lí.",answer:!1,explain:"Sai. Lí do đó là phân biệt; Lan có thể mời bạn để bạn hòa nhập."},{id:"dd5-ung-xu-ton-trong-24",type:"mc",q:"Dịp Tết, bạn Khoa kể nhà bạn đón Tết theo phong tục riêng của dân tộc mình. Em nên làm gì?",options:["Hào hứng nghe và hỏi thêm","Nói rằng Tết nhà mình mới đúng","Bảo bạn đổi theo phong tục của mình"],answer:0,explain:"Tò mò, tôn trọng giúp em hiểu thêm về các dân tộc."},{id:"dd5-ung-xu-ton-trong-25",type:"mc",q:"Bạn Vy hay hỏi bài, có bạn nói “hỏi gì mà lắm thế”. Cách ứng xử nào phù hợp?",options:["Cũng chê Vy hỏi nhiều như bạn ấy","Kiên nhẫn trả lời câu hỏi của Vy","Không bao giờ trả lời Vy nữa"],answer:1,explain:"Ham hỏi là điều tốt; kiên nhẫn giúp đỡ là tôn trọng bạn."},{id:"dd5-ung-xu-ton-trong-26",type:"order",q:"Sắp xếp các bước tổ chức buổi “Giới thiệu nét đẹp quê em” ở lớp.",items:["Mỗi bạn chọn một nét đẹp quê mình","Chuẩn bị tranh ảnh, lời giới thiệu","Lần lượt trình bày trước lớp","Cả lớp đặt câu hỏi và cảm ơn"],explain:"Hoạt động giúp các bạn hiểu và trân trọng sự khác biệt."},{id:"dd5-ung-xu-ton-trong-27",type:"mc",q:"Ngọc thích một nhóm nhạc mà Thảo không thích. Hai bạn nên ứng xử thế nào?",options:["Tranh cãi xem ai đúng","Thôi không chơi với nhau","Tôn trọng sở thích của nhau"],answer:2,explain:"Sở thích khác nhau vẫn có thể là bạn tốt."}]}],challenge:{questions:[{id:"dd5-ung-xu-ton-trong-28",type:"multi",q:"Những điều nào thể hiện ứng xử tôn trọng sự khác biệt?",options:["Lắng nghe, lịch sự","Đối xử công bằng","Lên tiếng khi bạn bị phân biệt","Bắt mọi người giống mình"],answers:[0,1,2],explain:"Lắng nghe, công bằng và lên tiếng là ứng xử tôn trọng."},{id:"dd5-ung-xu-ton-trong-29",type:"tf",q:"Người khác biệt với số đông thì nên tự thay đổi cho giống mọi người.",answer:!1,explain:"Sai. Ai cũng có quyền giữ nét riêng, miễn là không làm hại ai."},{id:"dd5-ung-xu-ton-trong-30",type:"mc",q:"Cách nào giúp lớp em trở thành tập thể tôn trọng sự khác biệt?",options:["Cùng đặt nội quy “Không chế giễu”","Chỉ chơi với nhóm bạn của mình","Bỏ qua khi có bạn bị trêu chọc"],answer:0,explain:"Nội quy chung giúp cả lớp nhắc nhau cư xử tôn trọng."},{id:"dd5-ung-xu-ton-trong-19",type:"mc",q:"Tùng mặc lại áo cũ của anh trai nên có bạn chê “áo cũ”. Em nên làm gì?",options:["Cười theo các bạn cho vui","Nhắc các bạn đừng chê áo của Tùng","Bảo Tùng đừng mặc áo đó nữa"],answer:1,explain:"Hoàn cảnh hay quần áo không làm giá trị của bạn kém đi."},{id:"dd5-ung-xu-ton-trong-21",type:"multi",q:"Lớp có bạn Phúc đi xe lăn. Cả lớp có thể làm gì để Phúc tham gia buổi dã ngoại?",options:["Chọn lối đi bằng phẳng","Phân công bạn đi cùng hỗ trợ","Chọn trò chơi Phúc cũng chơi được","Để Phúc ở nhà cho tiện"],answers:[0,1,2],explain:"Cả lớp cùng điều chỉnh để ai cũng được tham gia."},{id:"dd5-ung-xu-ton-trong-23",type:"tf",q:"Lan không mời bạn mới đến dự sinh nhật vì bạn “nhà ở xa, nói giọng lạ”. Lan làm vậy là hợp lí.",answer:!1,explain:"Sai. Lí do đó là phân biệt; Lan có thể mời bạn để bạn hòa nhập."}]},summary:["Em ứng xử lịch sự, lắng nghe và công bằng với mọi người.","Không phân biệt đối xử vì bất kì điểm khác biệt nào.","Lên tiếng và động viên khi thấy bạn bị phân biệt, chế giễu."]}]},{id:"vuot-qua-kho-khan",title:"Vượt qua khó khăn",lessons:[{id:"dd5-kho-khan-va-y-chi",title:"Bài 5: Khó khăn và ý chí",weeks:[9,10],learn:[{title:"Khó khăn là gì?",text:"Khó khăn là những trở ngại em gặp trong học tập và cuộc sống: bài khó, sức khỏe yếu, hoàn cảnh gia đình thiếu thốn, chưa quen môi trường mới…",example:"🧗 trở ngại"},{title:"Ý chí vượt khó",text:"Người có ý chí không nản lòng, kiên trì, tìm cách giải quyết và biết nhờ giúp đỡ khi cần.",example:"💪 kiên trì · 🔁 thử lại"},{title:"Ý nghĩa",text:"Vượt qua khó khăn giúp em trưởng thành, tự tin, được mọi người tin yêu và đạt được mục tiêu.",example:"🌱 trưởng thành · ⭐ tự tin"}],practice:[{questions:[{id:"dd5-kho-khan-va-y-chi-01",type:"multi",q:"Đâu là khó khăn em có thể gặp?",options:["Bài toán khó chưa giải được","Bị ốm phải nghỉ học","Chuyển đến trường mới chưa quen bạn","Được tặng quyển sách hay"],answers:[0,1,2],explain:"Khó khăn có thể đến từ học tập, sức khỏe hay môi trường mới."},{id:"dd5-kho-khan-va-y-chi-02",type:"tf",q:"Ai cũng có lúc gặp khó khăn.",answer:!0,explain:"Đúng. Gặp khó khăn là bình thường; quan trọng là cách em vượt qua."},{id:"dd5-kho-khan-va-y-chi-03",type:"tf",q:"Gặp khó khăn thì nên bỏ cuộc ngay cho đỡ mệt.",answer:!1,explain:"Sai. Kiên trì tìm cách sẽ giúp em vượt qua."},{id:"dd5-kho-khan-va-y-chi-04",type:"mc",q:"Câu tục ngữ nào nói về ý chí vượt khó?",options:["Có chí thì nên","Ăn cây nào rào cây ấy","Ăn chắc mặc bền"],answer:0,explain:"“Có chí thì nên” khuyên người có ý chí sẽ thành công."},{id:"dd5-kho-khan-va-y-chi-05",type:"mc",q:"Biểu hiện nào là có ý chí vượt khó?",options:["Gặp bài khó thì chép bài của bạn","Kiên trì suy nghĩ, hỏi thầy cô khi chưa hiểu","Gặp bài khó thì bỏ trống không làm"],answer:1,explain:"Kiên trì và biết hỏi là biểu hiện của ý chí vượt khó."},{id:"dd5-kho-khan-va-y-chi-06",type:"mc",q:"Vượt qua khó khăn giúp em điều gì?",options:["Trở nên ngại khó hơn trước","Không còn cần ai giúp nữa","Trưởng thành và tự tin hơn"],answer:2,explain:"Mỗi lần vượt khó, em lớn thêm một chút."},{id:"dd5-kho-khan-va-y-chi-07",type:"tf",q:"Nhờ người khác giúp đỡ khi gặp khó khăn không phải là yếu kém.",answer:!0,explain:"Đúng. Biết nhờ giúp đỡ là cách vượt khó thông minh."},{id:"dd5-kho-khan-va-y-chi-08",type:"tf",q:"Người vượt khó là người không bao giờ thất bại.",answer:!1,explain:"Sai. Người vượt khó có thể thất bại nhưng không bỏ cuộc."},{id:"dd5-kho-khan-va-y-chi-09",type:"mc",q:"Câu nào thể hiện thái độ tích cực khi gặp khó khăn?",options:["Mình sẽ thử cách khác","Mình không làm được đâu","Khó thế này thì thôi"],answer:0,explain:"Thử cách khác là thái độ tích cực."}]},{questions:[{id:"dd5-kho-khan-va-y-chi-10",type:"mc",q:"Vì sao cần có ý chí vượt qua khó khăn?",options:["Để không bao giờ phải nhờ ai giúp","Để đạt được mục tiêu và trưởng thành hơn","Để được mọi người thương hại mình"],answer:1,explain:"Ý chí giúp em đi đến mục tiêu dù gặp trở ngại."},{id:"dd5-kho-khan-va-y-chi-11",type:"match",q:"Nối khó khăn với cách vượt qua phù hợp.",pairs:[["Bài toán khó","Đọc lại đề, thử cách khác, hỏi thầy cô"],["Sợ nói trước lớp","Tập nói ở nhà nhiều lần"],["Bị ốm nghỉ học","Mượn vở chép bài, nhờ bạn giảng"],["Chưa quen bạn mới","Chủ động làm quen"]],explain:"Mỗi khó khăn có cách vượt qua phù hợp."},{id:"dd5-kho-khan-va-y-chi-12",type:"tf",q:"Chia một việc khó thành nhiều việc nhỏ giúp em dễ vượt qua hơn.",answer:!0,explain:"Đúng. Làm từng bước nhỏ giúp việc khó bớt đáng sợ."},{id:"dd5-kho-khan-va-y-chi-13",type:"multi",q:"Những suy nghĩ nào giúp em vượt khó?",options:["Mình chưa làm được, nhưng mình sẽ cố gắng","Sai thì sửa, lần sau sẽ tốt hơn","Mình kém lắm, chẳng làm được gì","Mình sẽ hỏi người có kinh nghiệm"],answers:[0,1,3],explain:"Suy nghĩ tích cực tiếp thêm sức mạnh để vượt khó."},{id:"dd5-kho-khan-va-y-chi-14",type:"tf",q:"Gặp khó khăn chỉ cần chờ người khác giải quyết hộ.",answer:!1,explain:"Sai. Em cần tự cố gắng trước, rồi nhờ giúp đỡ khi cần."},{id:"dd5-kho-khan-va-y-chi-15",type:"mc",q:"“Thất bại là mẹ thành công” có nghĩa là gì?",options:["Thất bại thì không bao giờ thành công","Muốn thành công thì phải thất bại thật nhiều","Rút kinh nghiệm từ thất bại sẽ giúp ta thành công"],answer:2,explain:"Mỗi lần thất bại cho em bài học để làm tốt hơn."},{id:"dd5-kho-khan-va-y-chi-16",type:"mc",q:"Bạn nào có ý chí vượt khó?",options:["Bạn Chi tập viết chữ đẹp mỗi ngày dù tay còn run","Bạn Tùng bỏ tập bơi vì bị sặc nước một lần","Bạn Khoa nhờ anh làm hộ bài tập khó"],answer:0,explain:"Kiên trì luyện tập mỗi ngày là biểu hiện của ý chí."},{id:"dd5-kho-khan-va-y-chi-17",type:"tf",q:"Người có hoàn cảnh khó khăn vẫn có thể học tốt nhờ ý chí và sự giúp đỡ của mọi người.",answer:!0,explain:"Đúng. Ý chí và tình thương giúp nhiều bạn vượt lên hoàn cảnh."},{id:"dd5-kho-khan-va-y-chi-18",type:"mc",q:"Câu nào trái với tinh thần vượt khó?",options:["Có công mài sắt có ngày nên kim","Đứng núi này trông núi nọ","Kiến tha lâu cũng đầy tổ"],answer:1,explain:"“Đứng núi này trông núi nọ” chỉ người không kiên định."}]},{questions:[{id:"dd5-kho-khan-va-y-chi-19",type:"mc",q:"Lan bị điểm kém bài kiểm tra Toán. Lan nên làm gì?",options:["Giấu bài, không cho bố mẹ biết","Nghĩ rằng mình không học được Toán","Xem lại lỗi sai và ôn lại bài"],answer:2,explain:"Rút kinh nghiệm và ôn lại giúp Lan tiến bộ."},{id:"dd5-kho-khan-va-y-chi-20",type:"tf",q:"Nam bị gãy tay phải, Nam tập viết bằng tay trái và nhờ bạn chép giúp bài. Nam có ý chí vượt khó.",answer:!0,explain:"Đúng. Nam vừa tự cố gắng vừa biết nhờ giúp đỡ."},{id:"dd5-kho-khan-va-y-chi-21",type:"multi",q:"Hà rất sợ phát biểu trước lớp. Hà có thể làm gì?",options:["Chuẩn bị kĩ ý định nói","Tập nói trước gương, trước người thân","Bắt đầu bằng những câu ngắn","Không bao giờ giơ tay phát biểu"],answers:[0,1,2],explain:"Chuẩn bị và tập luyện dần giúp Hà tự tin hơn."},{id:"dd5-kho-khan-va-y-chi-22",type:"mc",q:"Minh tập đá cầu mãi chưa được. Minh nên làm gì?",options:["Nhờ bạn chỉ cách và tập đều mỗi ngày","Bỏ, chuyển sang chơi khác ngay","Ném quả cầu đi vì tức"],answer:0,explain:"Học hỏi và luyện tập đều giúp Minh tiến bộ."},{id:"dd5-kho-khan-va-y-chi-23",type:"tf",q:"Khoa nghĩ: “Mình học kém tiếng Anh vì không có năng khiếu, cố cũng vô ích.” Suy nghĩ đó giúp Khoa tiến bộ.",answer:!1,explain:"Sai. Kiên trì luyện tập mỗi ngày sẽ giúp Khoa tiến bộ."},{id:"dd5-kho-khan-va-y-chi-24",type:"mc",q:"Gia đình Phúc gặp khó khăn, Phúc không có tiền mua sách tham khảo. Phúc có thể làm gì?",options:["Bỏ học vì nhà đang khó khăn","Mượn sách ở thư viện, học nhóm cùng bạn","Lấy sách của bạn mà không hỏi"],answer:1,explain:"Thư viện và bạn bè giúp Phúc học tốt dù thiếu thốn."},{id:"dd5-kho-khan-va-y-chi-25",type:"order",q:"Sắp xếp các bước giải quyết một bài toán khó.",items:["Đọc kĩ đề bài","Tìm xem đề cho gì, hỏi gì","Thử một cách giải","Kiểm tra lại kết quả"],explain:"Làm từng bước giúp em bình tĩnh giải bài khó."},{id:"dd5-kho-khan-va-y-chi-26",type:"mc",q:"Vy tập đàn mãi chưa thuộc bài, Vy muốn bỏ. Lời khuyên nào phù hợp?",options:["Bỏ đi, chơi cái khác dễ hơn","Tập liền cả đêm cho thuộc bài","Tập từng đoạn ngắn, mỗi ngày một chút"],answer:2,explain:"Chia nhỏ và luyện đều giúp Vy tiến bộ vững chắc."},{id:"dd5-kho-khan-va-y-chi-27",type:"mc",q:"Thảo chuyển trường, chưa có bạn và thấy buồn. Thảo nên làm gì?",options:["Chủ động làm quen với các bạn","Ngồi một mình và chờ hết năm học","Xin bố mẹ chuyển về trường cũ ngay"],answer:0,explain:"Chủ động làm quen giúp Thảo vượt qua khó khăn ở môi trường mới."}]}],challenge:{questions:[{id:"dd5-kho-khan-va-y-chi-28",type:"multi",q:"Những câu nào nói đúng về vượt qua khó khăn?",options:["Cần kiên trì, không nản lòng","Biết nhờ giúp đỡ khi cần","Người vượt khó không bao giờ buồn","Giúp em trưởng thành hơn"],answers:[0,1,3],explain:"Người vượt khó cũng có lúc buồn, nhưng vẫn kiên trì đứng dậy."},{id:"dd5-kho-khan-va-y-chi-29",type:"tf",q:"Khó khăn chỉ đến với những người kém cỏi.",answer:!1,explain:"Sai. Ai cũng có thể gặp khó khăn; điều quan trọng là thái độ đối mặt."},{id:"dd5-kho-khan-va-y-chi-30",type:"mc",q:"“Kiến tha lâu cũng đầy tổ” khuyên em điều gì?",options:["Kiến là loài rất chăm chỉ","Kiên trì góp từng chút sẽ thành công","Muốn làm gì cũng phải thật nhanh"],answer:1,explain:"Kiên trì từng chút một sẽ đạt kết quả lớn."},{id:"dd5-kho-khan-va-y-chi-19",type:"mc",q:"Lan bị điểm kém bài kiểm tra Toán. Lan nên làm gì?",options:["Giấu bài, không cho bố mẹ biết","Nghĩ rằng mình không học được Toán","Xem lại lỗi sai và ôn lại bài"],answer:2,explain:"Rút kinh nghiệm và ôn lại giúp Lan tiến bộ."},{id:"dd5-kho-khan-va-y-chi-21",type:"multi",q:"Hà rất sợ phát biểu trước lớp. Hà có thể làm gì?",options:["Chuẩn bị kĩ ý định nói","Tập nói trước gương, trước người thân","Bắt đầu bằng những câu ngắn","Không bao giờ giơ tay phát biểu"],answers:[0,1,2],explain:"Chuẩn bị và tập luyện dần giúp Hà tự tin hơn."},{id:"dd5-kho-khan-va-y-chi-25",type:"order",q:"Sắp xếp các bước giải quyết một bài toán khó.",items:["Đọc kĩ đề bài","Tìm xem đề cho gì, hỏi gì","Thử một cách giải","Kiểm tra lại kết quả"],explain:"Làm từng bước giúp em bình tĩnh giải bài khó."}]},summary:["Ai cũng có lúc gặp khó khăn trong học tập và cuộc sống.","Người có ý chí kiên trì, không nản lòng, biết tìm cách vượt qua.","Vượt qua khó khăn giúp em trưởng thành và tự tin hơn."]},{id:"dd5-cach-vuot-kho",title:"Bài 6: Em vượt qua khó khăn",weeks:[11,12],learn:[{title:"Các bước vượt khó",text:"Nhận ra khó khăn, tìm nguyên nhân, nghĩ ra các cách giải quyết, chọn cách tốt nhất để làm, cuối cùng là rút kinh nghiệm.",example:"🔍 → 💡 → ✅"},{title:"Tìm sự hỗ trợ",text:"Bố mẹ, thầy cô, bạn bè, người lớn tin cậy có thể giúp em khi khó khăn quá sức.",example:"👨‍👩‍👧 gia đình · 🧑‍🏫 thầy cô"},{title:"Giúp bạn vượt khó",text:"Động viên, giảng bài, chia sẻ đồ dùng, rủ bạn cùng luyện tập là cách giúp bạn vượt khó.",example:"🤝 cùng nhau"}],practice:[{questions:[{id:"dd5-cach-vuot-kho-01",type:"order",q:"Sắp xếp các bước vượt qua khó khăn.",items:["Nhận ra khó khăn","Tìm nguyên nhân","Nghĩ ra các cách giải quyết","Chọn cách tốt nhất và thực hiện","Rút kinh nghiệm"],explain:"Làm theo các bước giúp em vượt khó có kế hoạch."},{id:"dd5-cach-vuot-kho-02",type:"tf",q:"Khi khó khăn quá sức, em nên tìm sự giúp đỡ của người lớn tin cậy.",answer:!0,explain:"Đúng. Người lớn có kinh nghiệm để giúp em."},{id:"dd5-cach-vuot-kho-03",type:"tf",q:"Nhờ bạn làm hộ bài tập là cách vượt khó tốt.",answer:!1,explain:"Sai. Em nên nhờ bạn giảng để tự hiểu và tự làm."},{id:"dd5-cach-vuot-kho-04",type:"mc",q:"Ai có thể giúp em khi gặp khó khăn trong học tập?",options:["Thầy cô, bố mẹ, bạn bè","Người lạ gặp trên mạng","Không ai giúp được"],answer:0,explain:"Thầy cô, bố mẹ, bạn bè là những người tin cậy giúp em."},{id:"dd5-cach-vuot-kho-05",type:"multi",q:"Những cách giúp bạn vượt khó là gì?",options:["Động viên bạn","Giảng bài cho bạn","Chê bạn kém","Rủ bạn cùng luyện tập"],answers:[0,1,3],explain:"Động viên, giảng bài, cùng luyện tập giúp bạn tiến bộ."},{id:"dd5-cach-vuot-kho-06",type:"mc",q:"Việc đầu tiên khi gặp khó khăn là gì?",options:["Bỏ cuộc ngay cho đỡ mệt","Bình tĩnh nhận ra khó khăn là gì","Đổ lỗi cho người khác trước"],answer:1,explain:"Bình tĩnh nhận ra vấn đề giúp em tìm đúng cách giải quyết."},{id:"dd5-cach-vuot-kho-07",type:"tf",q:"Sau khi vượt qua khó khăn, em nên rút kinh nghiệm cho lần sau.",answer:!0,explain:"Đúng. Rút kinh nghiệm giúp em làm tốt hơn khi gặp việc tương tự."},{id:"dd5-cach-vuot-kho-08",type:"mc",q:"Lời động viên nào phù hợp với bạn đang nản lòng?",options:["Thôi bỏ đi, khó lắm","Bạn chậm quá, không làm được đâu","Cố lên, mình cùng làm nhé"],answer:2,explain:"Lời động viên tiếp thêm sức mạnh cho bạn."},{id:"dd5-cach-vuot-kho-09",type:"tf",q:"Giấu khó khăn của mình, không cho ai biết là cách tốt nhất.",answer:!1,explain:"Sai. Chia sẻ với người tin cậy giúp em được hỗ trợ kịp thời."}]},{questions:[{id:"dd5-cach-vuot-kho-10",type:"match",q:"Nối mỗi bước vượt khó với ví dụ khi Bình học chưa tốt môn Tiếng Anh.",pairs:[["Nhận ra khó khăn","Bình hay quên từ mới"],["Tìm nguyên nhân","Bình ít ôn lại từ"],["Thực hiện cách giải quyết","Mỗi ngày ôn mười từ bằng thẻ"],["Rút kinh nghiệm","Ôn đều đặn thì nhớ lâu hơn"]],explain:"Áp dụng các bước giúp Bình tiến bộ rõ rệt."},{id:"dd5-cach-vuot-kho-11",type:"mc",q:"Vì sao cần tìm nguyên nhân của khó khăn?",options:["Để chọn đúng cách giải quyết","Để có lí do đổ lỗi cho người khác","Để biết ai đã sai"],answer:0,explain:"Hiểu nguyên nhân giúp em tìm đúng cách vượt qua."},{id:"dd5-cach-vuot-kho-12",type:"tf",q:"Lập kế hoạch nhỏ, làm từng phần giúp em không bị choáng ngợp trước việc khó.",answer:!0,explain:"Đúng. Từng bước nhỏ tạo nên kết quả lớn."},{id:"dd5-cach-vuot-kho-13",type:"multi",q:"Khi gặp thất bại, em nên làm gì?",options:["Bình tĩnh, không tự trách mình quá nhiều","Tìm xem mình sai ở đâu","Thử lại với cách khác","Từ bỏ luôn"],answers:[0,1,2],explain:"Bình tĩnh, rút kinh nghiệm và thử lại giúp em vượt qua thất bại."},{id:"dd5-cach-vuot-kho-14",type:"tf",q:"Nghĩ ra nhiều cách giải quyết là mất thời gian, chỉ cần làm theo cách đầu tiên nghĩ ra.",answer:!1,explain:"Sai. Cân nhắc nhiều cách giúp em chọn được cách tốt nhất."},{id:"dd5-cach-vuot-kho-15",type:"mc",q:"Khi giúp bạn vượt khó, em nên chú ý điều gì?",options:["Làm hộ hết cho nhanh","Giúp để bạn tự làm được, không làm thay","Kể với mọi người là mình giúp bạn"],answer:1,explain:"Giúp bạn tự làm được mới thật sự có ích."},{id:"dd5-cach-vuot-kho-16",type:"mc",q:"Bạn nào biết tìm sự hỗ trợ đúng lúc?",options:["Bạn Lan cố giấu việc bị bắt nạt","Bạn Hà hỏi người lạ trên mạng cách giải quyết chuyện riêng","Bạn Minh nói với cô khi mãi không hiểu bài"],answer:2,explain:"Thầy cô là người tin cậy giúp Minh hiểu bài."},{id:"dd5-cach-vuot-kho-17",type:"tf",q:"Ghi lại những tiến bộ nhỏ mỗi ngày giúp em thêm động lực vượt khó.",answer:!0,explain:"Đúng. Nhìn thấy tiến bộ giúp em vui và cố gắng hơn."},{id:"dd5-cach-vuot-kho-18",type:"mc",q:"Câu nào thể hiện tinh thần cùng nhau vượt khó?",options:["Một cây làm chẳng nên non, ba cây chụm lại nên hòn núi cao","Ai lo phận nấy, chẳng cần ai giúp","Việc người thì sáng, việc mình thì quáng"],answer:0,explain:"Đoàn kết giúp nhau sẽ vượt qua được khó khăn lớn."}]},{questions:[{id:"dd5-cach-vuot-kho-19",type:"mc",q:"Dũng muốn đạt giải bơi nhưng mới tập bị chuột rút. Dũng nên làm gì?",options:["Bỏ tập luôn cho an toàn","Hỏi thầy cách khởi động cho đúng","Cố bơi tiếp dù chân đang đau"],answer:1,explain:"Học cách tập đúng giúp Dũng vừa an toàn vừa tiến bộ."},{id:"dd5-cach-vuot-kho-20",type:"tf",q:"Ngọc chưa thuộc bảng cửu chương lớp dưới, Ngọc dành mỗi ngày mười phút ôn lại. Ngọc đang vượt khó đúng cách.",answer:!0,explain:"Đúng. Ôn đều đặn từng chút giúp Ngọc lấp chỗ hổng kiến thức."},{id:"dd5-cach-vuot-kho-21",type:"multi",q:"Bạn Tùng bị ốm dài ngày, quay lại lớp bị chậm bài. Các bạn có thể làm gì?",options:["Cho Tùng mượn vở chép bài","Giảng lại bài khó cho Tùng","Trêu Tùng học chậm","Rủ Tùng học nhóm"],answers:[0,1,3],explain:"Cả lớp chung tay giúp Tùng bắt kịp bài."},{id:"dd5-cach-vuot-kho-22",type:"mc",q:"Khoa làm thí nghiệm khoa học thất bại ba lần. Khoa nên làm gì?",options:["Bịa ra kết quả cho xong việc","Đổ lỗi cho dụng cụ rồi bỏ cuộc","Xem lại từng bước, hỏi cô và làm lại"],answer:2,explain:"Trung thực và kiên trì là cách vượt khó đúng."},{id:"dd5-cach-vuot-kho-23",type:"tf",q:"Chi muốn giỏi vẽ nên vẽ liền năm tiếng, bỏ cả bữa tối. Đó là cách vượt khó hợp lí.",answer:!1,explain:"Sai. Chi nên luyện đều mỗi ngày và giữ sức khỏe."},{id:"dd5-cach-vuot-kho-24",type:"mc",q:"Vy thấy bạn ngồi buồn vì thua cuộc thi kể chuyện. Vy nên nói gì?",options:["Bạn đã cố gắng rồi, mình cùng tập nhé","Bạn kể chán thật, thua là phải","Thua thì thôi, lần sau đừng thi nữa"],answer:0,explain:"Lời động viên giúp bạn có thêm động lực."},{id:"dd5-cach-vuot-kho-25",type:"order",q:"Sắp xếp kế hoạch vượt khó của An khi viết chữ chưa đẹp.",items:["Nhận ra chữ viết chưa đều, chưa thẳng hàng","Tìm nguyên nhân: cầm bút sai, viết vội","Chọn cách: tập cầm bút đúng, viết chậm mỗi ngày","Sau hai tuần, xem lại tiến bộ"],explain:"Có kế hoạch rõ ràng giúp An viết đẹp dần."},{id:"dd5-cach-vuot-kho-26",type:"mc",q:"Thảo gặp chuyện buồn trong gia đình nên học sa sút. Thảo nên làm gì?",options:["Giữ trong lòng, không nói với ai","Chia sẻ với người lớn tin cậy","Nghỉ học cho đến khi hết buồn"],answer:1,explain:"Chia sẻ giúp Thảo nhẹ lòng và được hỗ trợ."},{id:"dd5-cach-vuot-kho-27",type:"mc",q:"Phúc nói: “Mình phải tự vượt khó, nhờ ai giúp là xấu hổ.” Em nghĩ sao?",options:["Phúc nói đúng, phải tự làm hết","Nhờ người khác làm hết cho nhanh","Biết nhờ giúp đỡ cũng là vượt khó"],answer:2,explain:"Tự cố gắng và biết nhờ giúp đỡ đều quan trọng."}]}],challenge:{questions:[{id:"dd5-cach-vuot-kho-28",type:"multi",q:"Những điều nào giúp em vượt khó hiệu quả?",options:["Tìm đúng nguyên nhân","Có kế hoạch từng bước","Biết tìm sự hỗ trợ","Chờ khó khăn tự hết"],answers:[0,1,2],explain:"Nguyên nhân, kế hoạch và sự hỗ trợ giúp em vượt khó hiệu quả."},{id:"dd5-cach-vuot-kho-29",type:"tf",q:"Giúp bạn vượt khó nghĩa là làm thay mọi việc cho bạn.",answer:!1,explain:"Sai. Giúp bạn là hỗ trợ để bạn tự làm được."},{id:"dd5-cach-vuot-kho-30",type:"mc",q:"Bước nào giúp em làm tốt hơn khi gặp khó khăn tương tự lần sau?",options:["Rút kinh nghiệm","Nhận ra khó khăn","Tìm nguyên nhân"],answer:0,explain:"Rút kinh nghiệm giúp em mạnh mẽ hơn cho lần sau."},{id:"dd5-cach-vuot-kho-19",type:"mc",q:"Dũng muốn đạt giải bơi nhưng mới tập bị chuột rút. Dũng nên làm gì?",options:["Bỏ tập luôn cho an toàn","Hỏi thầy cách khởi động cho đúng","Cố bơi tiếp dù chân đang đau"],answer:1,explain:"Học cách tập đúng giúp Dũng vừa an toàn vừa tiến bộ."},{id:"dd5-cach-vuot-kho-22",type:"mc",q:"Khoa làm thí nghiệm khoa học thất bại ba lần. Khoa nên làm gì?",options:["Bịa ra kết quả cho xong việc","Đổ lỗi cho dụng cụ rồi bỏ cuộc","Xem lại từng bước, hỏi cô và làm lại"],answer:2,explain:"Trung thực và kiên trì là cách vượt khó đúng."},{id:"dd5-cach-vuot-kho-25",type:"order",q:"Sắp xếp kế hoạch vượt khó của An khi viết chữ chưa đẹp.",items:["Nhận ra chữ viết chưa đều, chưa thẳng hàng","Tìm nguyên nhân: cầm bút sai, viết vội","Chọn cách: tập cầm bút đúng, viết chậm mỗi ngày","Sau hai tuần, xem lại tiến bộ"],explain:"Có kế hoạch rõ ràng giúp An viết đẹp dần."}]},summary:["Vượt khó theo các bước: nhận ra, tìm nguyên nhân, nghĩ cách, làm và rút kinh nghiệm.","Biết tìm sự hỗ trợ khi khó khăn quá sức.","Động viên, giúp đỡ bạn bè cùng vượt khó."]}]},{id:"bao-ve-cai-dung-cai-tot",title:"Bảo vệ cái đúng, cái tốt",lessons:[{id:"dd5-nhan-biet-cai-dung",title:"Bài 7: Nhận biết cái đúng, cái tốt",weeks:[13,14],learn:[{title:"Cái đúng, cái tốt là gì?",text:"Đó là những lời nói, việc làm phù hợp với đạo đức và pháp luật, đem lại lợi ích cho mình và mọi người: trung thực, giúp đỡ người khác, bảo vệ môi trường…",example:"✅ trung thực · 🤝 giúp đỡ"},{title:"Cái sai, cái xấu",text:"Đó là những việc làm hại người khác hoặc trái đạo đức, pháp luật: nói dối, gian lận, bắt nạt, phá hoại của công…",example:"❌ gian lận · ❌ bắt nạt"},{title:"Vì sao phải bảo vệ cái đúng?",text:"Bảo vệ cái đúng, cái tốt giúp lẽ phải được tôn trọng, người tốt được bảo vệ và cái xấu bị ngăn chặn.",example:"⚖️ lẽ phải"}],practice:[{questions:[{id:"dd5-nhan-biet-cai-dung-01",type:"multi",q:"Đâu là cái đúng, cái tốt?",options:["Nói thật khi mắc lỗi","Giúp đỡ bạn gặp khó khăn","Quay cóp khi kiểm tra","Nhặt rác ở sân trường"],answers:[0,1,3],explain:"Trung thực, giúp đỡ, giữ vệ sinh là những việc tốt."},{id:"dd5-nhan-biet-cai-dung-02",type:"multi",q:"Đâu là cái sai, cái xấu?",options:["Bắt nạt bạn nhỏ hơn","Nói dối bố mẹ","Trả lại của rơi","Viết bậy lên tường"],answers:[0,1,3],explain:"Bắt nạt, nói dối, phá hoại là những việc làm sai."},{id:"dd5-nhan-biet-cai-dung-03",type:"tf",q:"Bảo vệ cái đúng giúp lẽ phải được tôn trọng.",answer:!0,explain:"Đúng. Khi cái đúng được bảo vệ, mọi người sống công bằng hơn."},{id:"dd5-nhan-biet-cai-dung-04",type:"tf",q:"Việc gì nhiều người làm thì đó là việc đúng.",answer:!1,explain:"Sai. Đúng hay sai phụ thuộc vào đạo đức, pháp luật, không phải số đông."},{id:"dd5-nhan-biet-cai-dung-05",type:"mc",q:"Câu tục ngữ nào khen người ngay thẳng?",options:["Cây ngay không sợ chết đứng","Ăn cháo đá bát","Gió chiều nào che chiều ấy"],answer:0,explain:"“Cây ngay không sợ chết đứng” khen người ngay thẳng, không sợ bị vu oan."},{id:"dd5-nhan-biet-cai-dung-06",type:"mc",q:"Gian lận trong thi cử là việc làm thế nào?",options:["Thông minh, đáng học hỏi","Sai trái, không trung thực","Bình thường, ai cũng làm"],answer:1,explain:"Gian lận là không trung thực và không công bằng với các bạn khác."},{id:"dd5-nhan-biet-cai-dung-07",type:"tf",q:"Người dám bảo vệ cái đúng là người dũng cảm.",answer:!0,explain:"Đúng. Bảo vệ cái đúng đôi khi cần sự can đảm."},{id:"dd5-nhan-biet-cai-dung-08",type:"tf",q:"Bảo vệ cái đúng chỉ là việc của người lớn.",answer:!1,explain:"Sai. Học sinh cũng có thể bảo vệ cái đúng bằng việc làm phù hợp, an toàn."},{id:"dd5-nhan-biet-cai-dung-09",type:"mc",q:"Câu nào chỉ người không dám bảo vệ lẽ phải?",options:["Cây ngay không sợ chết đứng","Thẳng như ruột ngựa","Gió chiều nào che chiều ấy"],answer:2,explain:"“Gió chiều nào che chiều ấy” chỉ người không có lập trường, chạy theo số đông."}]},{questions:[{id:"dd5-nhan-biet-cai-dung-10",type:"match",q:"Nối việc làm với nhận xét đúng.",pairs:[["Nhận lỗi khi làm sai","Trung thực"],["Hùa theo bạn bắt nạt người khác","Sai trái"],["Bênh vực bạn bị oan","Bảo vệ lẽ phải"],["Im lặng khi thấy bạn gian lận","Chưa bảo vệ cái đúng"]],explain:"Phân biệt đúng sai giúp em biết hành động phù hợp."},{id:"dd5-nhan-biet-cai-dung-11",type:"mc",q:"Vì sao cần bảo vệ cái đúng, cái tốt?",options:["Để người tốt được bảo vệ","Để được mọi người khen ngợi","Để mình luôn thắng trong tranh cãi"],answer:0,explain:"Bảo vệ cái đúng giúp cuộc sống công bằng, tốt đẹp hơn."},{id:"dd5-nhan-biet-cai-dung-12",type:"tf",q:"Không hùa theo việc sai của bạn bè cũng là bảo vệ cái đúng.",answer:!0,explain:"Đúng. Dám nói “không” với việc sai là bảo vệ cái đúng."},{id:"dd5-nhan-biet-cai-dung-13",type:"tf",q:"Bạn thân làm sai thì mình nên bênh vực để giữ tình bạn.",answer:!1,explain:"Sai. Bạn tốt giúp nhau nhận ra cái sai để sửa."},{id:"dd5-nhan-biet-cai-dung-14",type:"multi",q:"Những biểu hiện nào là bảo vệ cái đúng?",options:["Bênh vực bạn bị nói oan","Góp ý khi bạn làm sai","Báo thầy cô khi thấy bạn bị bắt nạt","Lờ đi cho khỏi phiền"],answers:[0,1,2],explain:"Bênh vực, góp ý, báo người lớn là bảo vệ cái đúng."},{id:"dd5-nhan-biet-cai-dung-15",type:"mc",q:"Bảo vệ cái đúng cần đi kèm điều gì để em được an toàn?",options:["Liều lĩnh lao vào mọi nơi một mình","Cách làm an toàn, nhờ người lớn khi cần","Dùng sức mạnh để bắt người khác nghe"],answer:1,explain:"Bảo vệ cái đúng cần khôn khéo và giữ an toàn."},{id:"dd5-nhan-biet-cai-dung-16",type:"mc",q:"Ý kiến nào đúng?",options:["Lẽ phải thuộc về người nói to nhất","Lẽ phải thuộc về người đông bạn nhất","Lẽ phải dựa trên sự thật và pháp luật"],answer:2,explain:"Đúng sai phải dựa trên sự thật, không dựa vào số đông hay giọng nói."},{id:"dd5-nhan-biet-cai-dung-17",type:"tf",q:"Thừa nhận khi mình sai cũng là tôn trọng cái đúng.",answer:!0,explain:"Đúng. Dám nhận sai là người trung thực, cầu tiến."},{id:"dd5-nhan-biet-cai-dung-18",type:"mc",q:"Bạn nào đã bảo vệ cái tốt?",options:["Bạn Vy lên tiếng làm chứng giúp bạn bị đổ oan","Bạn Tùng cười khi thấy bạn bị đổ oan","Bạn Khoa bỏ đi chỗ khác cho xong chuyện"],answer:0,explain:"Vy dám nói sự thật để bảo vệ bạn."}]},{questions:[{id:"dd5-nhan-biet-cai-dung-19",type:"mc",q:"Lan thấy bạn nhặt được ví của cô giáo và định giữ lại. Lan nên làm gì?",options:["Xin bạn chia cho một ít","Khuyên bạn trả lại cô giáo","Giả vờ như không thấy"],answer:1,explain:"Khuyên bạn làm điều đúng là bảo vệ cái đúng."},{id:"dd5-nhan-biet-cai-dung-20",type:"tf",q:"Nam bị bạn rủ bỏ tiết đi chơi, Nam từ chối và khuyên bạn quay lại lớp. Nam bảo vệ cái đúng.",answer:!0,explain:"Đúng. Nam không làm điều sai và giúp bạn sửa sai."},{id:"dd5-nhan-biet-cai-dung-21",type:"multi",q:"Lớp bị mất bút của một bạn, một số bạn đổ lỗi cho Hà mà không có bằng chứng. Em có thể làm gì?",options:["Nhắc các bạn không nên kết luận khi chưa rõ","Báo cô giáo để cô tìm hiểu","Hùa theo đổ lỗi cho Hà","Động viên Hà bình tĩnh"],answers:[0,1,3],explain:"Không vội kết luận và nhờ cô tìm hiểu là bảo vệ lẽ phải."},{id:"dd5-nhan-biet-cai-dung-22",type:"mc",q:"Minh thấy bạn ném đá vào chó mèo hoang. Minh nên làm gì?",options:["Ném cùng bạn cho vui","Đứng xem và cổ vũ bạn ném tiếp","Khuyên bạn dừng lại vì làm đau con vật"],answer:2,explain:"Bảo vệ con vật khỏi bị hành hạ là việc làm tốt."},{id:"dd5-nhan-biet-cai-dung-23",type:"tf",q:"Khoa thấy anh lớn đang trộm xe đạp, Khoa xông vào giật lại xe. Đó là cách bảo vệ cái đúng an toàn.",answer:!1,explain:"Sai. Khoa nên tránh xa và báo ngay người lớn hoặc công an."},{id:"dd5-nhan-biet-cai-dung-24",type:"mc",q:"Chi được bạn nhờ làm hộ bài kiểm tra đổi lấy đồ chơi. Chi nên làm gì?",options:["Từ chối và giải thích đó là gian lận","Đồng ý vì sẽ được đồ chơi mới","Làm hộ một nửa bài thôi là được"],answer:0,explain:"Từ chối gian lận là bảo vệ sự trung thực."},{id:"dd5-nhan-biet-cai-dung-25",type:"mc",q:"Trong trò chơi, đội của Dũng thắng nhờ bạn ăn gian. Dũng nên làm gì?",options:["Vui vì đội mình đã thắng","Nói thật với trọng tài","Giữ bí mật cho đội mình"],answer:1,explain:"Thắng công bằng mới đáng tự hào."},{id:"dd5-nhan-biet-cai-dung-26",type:"order",q:"Sắp xếp cách xử lí khi thấy bạn bị nói oan.",items:["Bình tĩnh tìm hiểu sự thật","Nói lên điều mình biết","Nhờ thầy cô làm rõ nếu cần"],explain:"Tìm hiểu, lên tiếng và nhờ người lớn giúp bảo vệ lẽ phải."},{id:"dd5-nhan-biet-cai-dung-27",type:"mc",q:"Thảo nói: “Thấy việc sai thì cứ kệ, không phải chuyện của mình.” Em nghĩ sao?",options:["Thảo nói đúng, tránh xa cho đỡ phiền phức","Thảo nói đúng, vì mình còn nhỏ tuổi","Chưa đúng, mình nên góp ý hoặc báo người lớn"],answer:2,explain:"Mỗi người góp một phần thì cái xấu sẽ bị ngăn chặn."}]}],challenge:{questions:[{id:"dd5-nhan-biet-cai-dung-28",type:"multi",q:"Những câu nào đúng về bảo vệ cái đúng, cái tốt?",options:["Cần phân biệt đúng – sai","Cần cách làm an toàn, phù hợp","Phải theo số đông","Cần dũng cảm và trung thực"],answers:[0,1,3],explain:"Phân biệt đúng sai, dũng cảm, trung thực và an toàn là những điều cần có."},{id:"dd5-nhan-biet-cai-dung-29",type:"tf",q:"Im lặng trước việc sai luôn là cách tốt nhất để giữ an toàn.",answer:!1,explain:"Sai. Em có thể báo người lớn một cách an toàn, không cần im lặng."},{id:"dd5-nhan-biet-cai-dung-30",type:"mc",q:"“Thẳng như ruột ngựa” nói về người như thế nào?",options:["Người thẳng thắn, nghĩ sao nói vậy","Người hay nói dối, nói vòng vo","Người chạy rất nhanh như ngựa"],answer:0,explain:"Câu này chỉ người thẳng thắn, bộc trực."},{id:"dd5-nhan-biet-cai-dung-20",type:"tf",q:"Nam bị bạn rủ bỏ tiết đi chơi, Nam từ chối và khuyên bạn quay lại lớp. Nam bảo vệ cái đúng.",answer:!0,explain:"Đúng. Nam không làm điều sai và giúp bạn sửa sai."},{id:"dd5-nhan-biet-cai-dung-23",type:"tf",q:"Khoa thấy anh lớn đang trộm xe đạp, Khoa xông vào giật lại xe. Đó là cách bảo vệ cái đúng an toàn.",answer:!1,explain:"Sai. Khoa nên tránh xa và báo ngay người lớn hoặc công an."},{id:"dd5-nhan-biet-cai-dung-25",type:"mc",q:"Trong trò chơi, đội của Dũng thắng nhờ bạn ăn gian. Dũng nên làm gì?",options:["Vui vì đội mình đã thắng","Nói thật với trọng tài","Giữ bí mật cho đội mình"],answer:1,explain:"Thắng công bằng mới đáng tự hào."}]},summary:["Cái đúng, cái tốt là những việc phù hợp với đạo đức, pháp luật và có lợi cho mọi người.","Cần phân biệt rõ đúng – sai, tốt – xấu.","Bảo vệ cái đúng giúp xã hội tốt đẹp hơn."]},{id:"dd5-dung-cam-bao-ve-le-phai",title:"Bài 8: Dũng cảm bảo vệ lẽ phải",weeks:[15,16],learn:[{title:"Cách bảo vệ cái đúng",text:"Nói lên sự thật; không hùa theo cái sai; góp ý, khuyên ngăn bằng lời lẽ nhẹ nhàng; ủng hộ người làm việc tốt.",example:"🗣️ nói thật · 👍 ủng hộ"},{title:"An toàn là trên hết",text:"Với việc nguy hiểm như trộm cắp, đánh nhau, em không tự xông vào mà tránh xa và báo người lớn, thầy cô hoặc gọi 113.",example:"📞 113"},{title:"Dũng cảm nhận lỗi",text:"Bảo vệ cái đúng bắt đầu từ chính mình: dám nhận lỗi, sửa lỗi và giữ lời hứa.",example:"🙋 “Em xin lỗi, em sẽ sửa.”"}],practice:[{questions:[{id:"dd5-dung-cam-bao-ve-le-phai-01",type:"tf",q:"Nói lên sự thật là một cách bảo vệ cái đúng.",answer:!0,explain:"Đúng. Sự thật giúp mọi người hiểu đúng và công bằng."},{id:"dd5-dung-cam-bao-ve-le-phai-02",type:"tf",q:"Khi thấy hai nhóm đánh nhau, em nên lao vào can ngăn ngay.",answer:!1,explain:"Sai. Em nên tránh xa và báo ngay thầy cô hoặc người lớn."},{id:"dd5-dung-cam-bao-ve-le-phai-03",type:"mc",q:"Thấy kẻ gian đang trộm đồ, em nên gọi số nào?",options:["113","114","115"],answer:0,explain:"113 là số gọi công an khi có việc về an ninh, trật tự."},{id:"dd5-dung-cam-bao-ve-le-phai-04",type:"mc",q:"Việc nào là ủng hộ cái tốt?",options:["Chê bạn trả của rơi là ngốc","Khen ngợi bạn trả lại của rơi","Bảo bạn lần sau giữ lại"],answer:1,explain:"Khen ngợi việc tốt giúp việc tốt được lan tỏa."},{id:"dd5-dung-cam-bao-ve-le-phai-05",type:"multi",q:"Những cách bảo vệ cái đúng phù hợp với học sinh lớp 5 là gì?",options:["Nói sự thật","Góp ý nhẹ nhàng","Báo thầy cô khi cần","Đánh nhau để dạy bạn"],answers:[0,1,2],explain:"Lời nói và nhờ người lớn là cách phù hợp, an toàn."},{id:"dd5-dung-cam-bao-ve-le-phai-06",type:"tf",q:"Dám nhận lỗi của mình cũng là dũng cảm.",answer:!0,explain:"Đúng. Nhận lỗi cần can đảm và giúp em tiến bộ."},{id:"dd5-dung-cam-bao-ve-le-phai-07",type:"mc",q:"Câu góp ý nào nhẹ nhàng, hiệu quả?",options:["Bạn thật là xấu tính quá đi!","Mình sẽ đi mách với cả trường","Mình nghĩ làm thế chưa đúng đâu bạn"],answer:2,explain:"Lời góp ý nhẹ nhàng dễ được lắng nghe."},{id:"dd5-dung-cam-bao-ve-le-phai-08",type:"tf",q:"Bảo vệ cái đúng là phải tranh cãi to tiếng cho đến khi thắng.",answer:!1,explain:"Sai. Bình tĩnh, lịch sự mới giúp người khác lắng nghe."},{id:"dd5-dung-cam-bao-ve-le-phai-09",type:"mc",q:"Khi mình làm sai, cách nào là bảo vệ cái đúng?",options:["Nhận lỗi và sửa lỗi","Đổ lỗi cho bạn bên cạnh","Giấu đi để không ai biết"],answer:0,explain:"Nhận và sửa lỗi là bảo vệ cái đúng từ chính mình."}]},{questions:[{id:"dd5-dung-cam-bao-ve-le-phai-10",type:"match",q:"Nối tình huống với cách ứng xử an toàn, đúng đắn.",pairs:[["Bạn gian lận trong kiểm tra","Góp ý riêng với bạn, báo cô nếu cần"],["Thấy người lạ trộm đồ","Tránh xa, báo người lớn"],["Bạn bị đổ oan","Nói lên sự thật mình biết"],["Mình làm vỡ cốc","Nhận lỗi và dọn dẹp cẩn thận"]],explain:"Mỗi tình huống cần cách bảo vệ cái đúng phù hợp, an toàn."},{id:"dd5-dung-cam-bao-ve-le-phai-11",type:"mc",q:"Vì sao không nên tự xông vào ngăn kẻ trộm?",options:["Vì không phải việc của em","Vì rất nguy hiểm cho em","Vì kẻ trộm có thể là người quen"],answer:1,explain:"Giữ an toàn cho bản thân là điều quan trọng nhất."},{id:"dd5-dung-cam-bao-ve-le-phai-12",type:"tf",q:"Bảo vệ cái đúng cần sự khéo léo để người khác dễ tiếp nhận.",answer:!0,explain:"Đúng. Lời lẽ khéo léo giúp người sai dễ nhận ra lỗi."},{id:"dd5-dung-cam-bao-ve-le-phai-13",type:"multi",q:"Những điều gì có thể khiến em ngại bảo vệ cái đúng?",options:["Sợ bị bạn giận","Sợ bị trêu chọc","Nghĩ không phải việc của mình","Hiểu rõ việc nào đúng, việc nào sai"],answers:[0,1,2],explain:"Nhận ra nỗi ngại giúp em tìm cách vượt qua để làm điều đúng."},{id:"dd5-dung-cam-bao-ve-le-phai-14",type:"tf",q:"Nếu bị bạn giận vì góp ý, em nên thôi không bảo vệ cái đúng nữa.",answer:!1,explain:"Sai. Em vẫn giữ điều đúng, kiên nhẫn giải thích và nhờ thầy cô nếu cần."},{id:"dd5-dung-cam-bao-ve-le-phai-15",type:"mc",q:"Vì sao nên khen ngợi người làm việc tốt?",options:["Để người đó phải cảm ơn mình","Để mình được nổi tiếng","Để việc tốt được lan tỏa"],answer:2,explain:"Lời khen khích lệ mọi người cùng làm việc tốt."},{id:"dd5-dung-cam-bao-ve-le-phai-16",type:"mc",q:"Bạn nào dũng cảm bảo vệ lẽ phải?",options:["Bạn Bình nói thật dù có thể bị nhóm bạn giận","Bạn Lan im lặng khi thấy bạn bị đổ oan","Bạn Hà hùa theo số đông cho an toàn"],answer:0,explain:"Bình dũng cảm nói sự thật để bảo vệ lẽ phải."},{id:"dd5-dung-cam-bao-ve-le-phai-17",type:"tf",q:"Báo với thầy cô khi thấy bạn bị bắt nạt không phải là “mách lẻo”.",answer:!0,explain:"Đúng. Đó là giúp bảo vệ bạn khỏi bị tổn thương."},{id:"dd5-dung-cam-bao-ve-le-phai-18",type:"order",q:"Sắp xếp các bước khi mình lỡ làm điều sai.",items:["Nhận ra mình đã sai","Thành thật nhận lỗi","Xin lỗi người bị ảnh hưởng","Sửa lỗi và rút kinh nghiệm"],explain:"Dũng cảm nhận lỗi giúp em tiến bộ và được tin tưởng."}]},{questions:[{id:"dd5-dung-cam-bao-ve-le-phai-19",type:"mc",q:"Ngọc thấy bạn lấy tiền quỹ lớp. Ngọc nên làm gì?",options:["Giữ bí mật cho bạn mãi mãi","Khuyên bạn trả lại tiền quỹ lớp","Đòi bạn chia cho mình một ít"],answer:1,explain:"Khuyên bạn sửa sai và nhờ cô giúp là cách làm đúng."},{id:"dd5-dung-cam-bao-ve-le-phai-20",type:"tf",q:"Tùng làm vỡ lọ hoa của lớp, Tùng tự nhận lỗi với cô dù không ai thấy. Tùng dũng cảm.",answer:!0,explain:"Đúng. Tùng trung thực và dám chịu trách nhiệm."},{id:"dd5-dung-cam-bao-ve-le-phai-21",type:"multi",q:"Trên nhóm chat lớp, có bạn lan truyền tin sai về một bạn khác. Em có thể làm gì?",options:["Không chia sẻ tiếp tin đó","Nhắn rằng chưa rõ thì không nên đăng","Báo cô chủ nhiệm","Thêm bình luận chê bai"],answers:[0,1,2],explain:"Không lan truyền và báo cô giúp bảo vệ bạn bị nói sai."},{id:"dd5-dung-cam-bao-ve-le-phai-22",type:"mc",q:"Minh thấy một bác lớn tuổi bị người đi xe va vào rồi người đó bỏ đi. Minh nên làm gì?",options:["Chạy đuổi theo người đi xe","Bỏ đi vì sợ bị liên lụy","Gọi người lớn đến giúp bác"],answer:2,explain:"Gọi người lớn giúp bác và làm chứng là bảo vệ lẽ phải an toàn."},{id:"dd5-dung-cam-bao-ve-le-phai-23",type:"tf",q:"Phúc biết em mình nói dối bố mẹ, Phúc giấu giúp em để em khỏi bị mắng. Phúc làm đúng.",answer:!1,explain:"Sai. Phúc nên khuyên em nói thật với bố mẹ."},{id:"dd5-dung-cam-bao-ve-le-phai-24",type:"mc",q:"Cả nhóm muốn chép bài trên mạng để nộp, chỉ có Vy không đồng ý. Vy nên làm gì?",options:["Nói rõ chép bài là không trung thực","Đồng ý theo cả nhóm cho êm chuyện","Tự làm riêng, không nói gì với nhóm"],answer:0,explain:"Vy lên tiếng và giúp cả nhóm làm điều đúng."},{id:"dd5-dung-cam-bao-ve-le-phai-25",type:"mc",q:"Bạn Khoa bị một nhóm bạn lớp trên chặn đường đòi đồ. Em thấy vậy. Em nên làm gì?",options:["Lao vào đánh nhau với nhóm bạn đó","Nhanh chóng báo thầy cô hoặc bác bảo vệ","Đi chỗ khác như không nhìn thấy"],answer:1,explain:"Báo người lớn kịp thời giúp Khoa an toàn."},{id:"dd5-dung-cam-bao-ve-le-phai-26",type:"order",q:"Sắp xếp cách góp ý khi bạn vứt rác bừa bãi.",items:["Đến gần bạn một cách thân thiện","Nhẹ nhàng nói điều chưa đúng","Gợi ý bạn bỏ rác vào thùng","Cảm ơn khi bạn làm theo"],explain:"Góp ý thân thiện giúp bạn vui vẻ sửa sai."},{id:"dd5-dung-cam-bao-ve-le-phai-27",type:"mc",q:"Hà bị bạn giận vì đã nói thật với cô về việc bạn quay cóp. Hà nên làm gì?",options:["Xin lỗi bạn vì đã trót nói thật","Giận lại bạn và không chơi nữa","Giải thích nhẹ nhàng và vẫn đối xử tốt với bạn"],answer:2,explain:"Hà giữ điều đúng nhưng vẫn quan tâm bạn."}]}],challenge:{questions:[{id:"dd5-dung-cam-bao-ve-le-phai-28",type:"multi",q:"Những điều nào thể hiện em dũng cảm bảo vệ lẽ phải?",options:["Nói thật dù có thể bị giận","Dám nhận lỗi","Không hùa theo số đông khi họ sai","Dùng sức mạnh để bắt người khác nghe theo"],answers:[0,1,2],explain:"Dũng cảm là dám làm điều đúng bằng cách phù hợp."},{id:"dd5-dung-cam-bao-ve-le-phai-29",type:"tf",q:"Bảo vệ cái đúng nghĩa là luôn phải tự mình giải quyết, không nhờ ai.",answer:!1,explain:"Sai. Biết nhờ thầy cô, người lớn là cách bảo vệ cái đúng an toàn."},{id:"dd5-dung-cam-bao-ve-le-phai-30",type:"mc",q:"Điều gì quan trọng nhất khi bảo vệ cái đúng trong tình huống nguy hiểm?",options:["Giữ an toàn cho bản thân và báo người lớn","Phải thắng kẻ xấu bằng mọi giá","Quay video để làm bằng chứng"],answer:0,explain:"An toàn của em là trên hết; người lớn sẽ xử lí tiếp."},{id:"dd5-dung-cam-bao-ve-le-phai-19",type:"mc",q:"Ngọc thấy bạn lấy tiền quỹ lớp. Ngọc nên làm gì?",options:["Giữ bí mật cho bạn mãi mãi","Khuyên bạn trả lại tiền quỹ lớp","Đòi bạn chia cho mình một ít"],answer:1,explain:"Khuyên bạn sửa sai và nhờ cô giúp là cách làm đúng."},{id:"dd5-dung-cam-bao-ve-le-phai-21",type:"multi",q:"Trên nhóm chat lớp, có bạn lan truyền tin sai về một bạn khác. Em có thể làm gì?",options:["Không chia sẻ tiếp tin đó","Nhắn rằng chưa rõ thì không nên đăng","Báo cô chủ nhiệm","Thêm bình luận chê bai"],answers:[0,1,2],explain:"Không lan truyền và báo cô giúp bảo vệ bạn bị nói sai."},{id:"dd5-dung-cam-bao-ve-le-phai-25",type:"mc",q:"Bạn Khoa bị một nhóm bạn lớp trên chặn đường đòi đồ. Em thấy vậy. Em nên làm gì?",options:["Lao vào đánh nhau với nhóm bạn đó","Nhanh chóng báo thầy cô hoặc bác bảo vệ","Đi chỗ khác như không nhìn thấy"],answer:1,explain:"Báo người lớn kịp thời giúp Khoa an toàn."}]},summary:["Em bảo vệ cái đúng bằng lời nói thật, góp ý và ủng hộ việc tốt.","Với việc nguy hiểm, em tránh xa và báo người lớn.","Dũng cảm nhận lỗi là bảo vệ cái đúng từ chính mình."]}]},{id:"bao-ve-moi-truong",title:"Bảo vệ môi trường sống",lessons:[{id:"dd5-moi-truong-quanh-em",title:"Bài 9: Môi trường sống quanh em",weeks:[17,18],learn:[{title:"Môi trường sống",text:"Môi trường sống gồm không khí, nước, đất, cây cối, động vật và mọi thứ xung quanh con người.",example:"🌳 💧 🌬️ 🐦"},{title:"Môi trường bị ô nhiễm",text:"Rác thải bừa bãi, khói bụi, nước thải, chặt phá rừng, dùng nhiều túi ni lông làm môi trường bị ô nhiễm.",example:"🏭 khói bụi · 🛍️ túi ni lông"},{title:"Tác hại",text:"Môi trường ô nhiễm gây bệnh cho con người, làm chết cây cối, động vật và làm thời tiết thất thường hơn.",example:"😷 bệnh tật · 🐟 cá chết"}],practice:[{questions:[{id:"dd5-moi-truong-quanh-em-01",type:"multi",q:"Môi trường sống gồm những gì?",options:["Không khí","Nước","Đất và cây cối","Động vật"],answers:[0,1,2,3],explain:"Tất cả những thứ quanh ta đều thuộc môi trường sống."},{id:"dd5-moi-truong-quanh-em-02",type:"tf",q:"Vứt rác bừa bãi làm ô nhiễm môi trường.",answer:!0,explain:"Đúng. Rác thải bừa bãi làm bẩn đất, nước và không khí."},{id:"dd5-moi-truong-quanh-em-03",type:"tf",q:"Túi ni lông phân hủy rất nhanh nên không gây hại.",answer:!1,explain:"Sai. Túi ni lông rất lâu phân hủy, gây hại cho đất, nước và động vật."},{id:"dd5-moi-truong-quanh-em-04",type:"mc",q:"Việc làm nào gây ô nhiễm không khí?",options:["Đốt rác, đốt rơm rạ bừa bãi","Trồng thêm cây xanh quanh nhà","Đi xe đạp đến trường mỗi ngày"],answer:0,explain:"Đốt rác tạo khói bụi làm không khí ô nhiễm."},{id:"dd5-moi-truong-quanh-em-05",type:"mc",q:"Việc làm nào gây ô nhiễm nguồn nước?",options:["Thả cá vào ao","Đổ rác xuống ao hồ, sông suối","Tiết kiệm nước khi rửa tay"],answer:1,explain:"Rác thải làm nước bẩn, cá và sinh vật dưới nước bị chết."},{id:"dd5-moi-truong-quanh-em-06",type:"mc",q:"Rừng có vai trò gì với môi trường?",options:["Chỉ để lấy gỗ làm nhà cửa, bàn ghế","Làm cho đất đai khô cằn, ít mưa hơn","Điều hòa khí hậu, giữ đất, che chở muôn loài"],answer:2,explain:"Rừng là “lá phổi xanh” giúp bảo vệ môi trường."},{id:"dd5-moi-truong-quanh-em-07",type:"tf",q:"Môi trường ô nhiễm có thể gây bệnh cho con người.",answer:!0,explain:"Đúng. Không khí, nước bẩn gây nhiều bệnh về hô hấp, tiêu hóa."},{id:"dd5-moi-truong-quanh-em-08",type:"tf",q:"Bảo vệ môi trường là việc của riêng các nhà khoa học.",answer:!1,explain:"Sai. Mọi người, kể cả học sinh, đều có trách nhiệm bảo vệ môi trường."},{id:"dd5-moi-truong-quanh-em-09",type:"mc",q:"Ngày Môi trường Thế giới là ngày nào?",options:["Ngày 5 tháng 6","Ngày 1 tháng 6","Ngày 2 tháng 9"],answer:0,explain:"Ngày 5 tháng 6 hằng năm là Ngày Môi trường Thế giới."}]},{questions:[{id:"dd5-moi-truong-quanh-em-10",type:"match",q:"Nối hành động với tác hại.",pairs:[["Chặt phá rừng","Lũ lụt, sạt lở đất"],["Xả rác xuống sông","Ô nhiễm nguồn nước"],["Đốt rác bừa bãi","Ô nhiễm không khí"],["Dùng nhiều túi ni lông","Rác khó phân hủy"]],explain:"Mỗi hành động xấu gây một tác hại cho môi trường."},{id:"dd5-moi-truong-quanh-em-11",type:"mc",q:"Vì sao phải bảo vệ môi trường?",options:["Vì để cảnh vật trông đẹp hơn mà thôi","Vì đó là nơi sống của mọi người","Vì đó là việc bắt buộc ở trường học"],answer:1,explain:"Môi trường là nơi sống của tất cả chúng ta."},{id:"dd5-moi-truong-quanh-em-12",type:"tf",q:"Rác thải nhựa trôi ra biển có thể làm hại rùa biển và cá.",answer:!0,explain:"Đúng. Động vật biển có thể nuốt phải nhựa hoặc bị mắc vào rác."},{id:"dd5-moi-truong-quanh-em-13",type:"multi",q:"Những thói quen nào gây hại cho môi trường?",options:["Để vòi nước chảy khi đánh răng","Bật điện khi không có ai trong phòng","Mang bình nước riêng đi học","Vứt vỏ chai nhựa xuống mương"],answers:[0,1,3],explain:"Lãng phí điện nước và xả rác là thói quen có hại."},{id:"dd5-moi-truong-quanh-em-14",type:"tf",q:"Một người vứt rác thì không ảnh hưởng gì đến môi trường.",answer:!1,explain:"Sai. Nhiều người cùng nghĩ vậy sẽ thành rất nhiều rác."},{id:"dd5-moi-truong-quanh-em-15",type:"mc",q:"Tiết kiệm điện giúp bảo vệ môi trường vì sao?",options:["Vì hóa đơn tiền điện sẽ rẻ hơn","Vì bóng đèn sẽ bền lâu hơn nhiều","Vì làm ra điện tốn tài nguyên, gây ô nhiễm"],answer:2,explain:"Dùng ít điện là giảm tài nguyên phải sử dụng và giảm ô nhiễm."},{id:"dd5-moi-truong-quanh-em-16",type:"mc",q:"Câu nào nói đúng về cây xanh?",options:["Cây xanh làm không khí trong lành hơn","Cây xanh làm cho không khí bẩn hơn","Cây xanh không cần thiết ở thành phố"],answer:0,explain:"Cây xanh giúp điều hòa không khí, cho bóng mát."},{id:"dd5-moi-truong-quanh-em-17",type:"tf",q:"Phân loại rác giúp tái chế được nhiều vật liệu.",answer:!0,explain:"Đúng. Rác được phân loại có thể tái chế giấy, nhựa, kim loại."},{id:"dd5-moi-truong-quanh-em-18",type:"mc",q:"Hiện tượng nào là dấu hiệu môi trường bị ô nhiễm?",options:["Bầu trời trong xanh, nắng nhẹ","Mặt hồ nổi váng, bốc mùi hôi","Chim hót líu lo trên cành"],answer:1,explain:"Nước bốc mùi, nổi váng là dấu hiệu ô nhiễm."}]},{questions:[{id:"dd5-moi-truong-quanh-em-19",type:"mc",q:"Đi dã ngoại, nhóm Lan ăn xong còn nhiều vỏ hộp. Nhóm nên làm gì?",options:["Để lại tại chỗ vì sẽ có người dọn","Đào hố chôn cả vỏ nhựa xuống đất","Gom vào túi, bỏ đúng nơi quy định"],answer:2,explain:"Mang rác đi đúng nơi giữ cho nơi dã ngoại sạch đẹp."},{id:"dd5-moi-truong-quanh-em-20",type:"tf",q:"Nam đi mua đồ ăn sáng, mang hộp đựng từ nhà thay cho túi ni lông. Nam góp phần bảo vệ môi trường.",answer:!0,explain:"Đúng. Dùng hộp riêng giúp giảm rác thải nhựa."},{id:"dd5-moi-truong-quanh-em-21",type:"multi",q:"Khu phố của Hà có con mương đầy rác. Hà và các bạn có thể làm gì?",options:["Cùng người lớn tham gia dọn rác","Làm biển nhắc “Không xả rác”","Tuyên truyền cho hàng xóm phân loại rác","Vứt thêm rác vì mương đã bẩn"],answers:[0,1,2],explain:"Học sinh có thể góp sức cùng người lớn làm sạch môi trường."},{id:"dd5-moi-truong-quanh-em-22",type:"mc",q:"Minh thấy hàng xóm đốt rác nhựa khói đen mù mịt. Minh nên làm gì?",options:["Tránh xa khói, nhờ bố mẹ góp ý","Đến gần để xem lửa cháy","Ném thêm rác vào đống lửa"],answer:0,explain:"Khói nhựa rất độc; Minh tránh xa và nhờ người lớn góp ý."},{id:"dd5-moi-truong-quanh-em-23",type:"tf",q:"Khoa thấy bạn bẻ cành cây trong công viên, Khoa nghĩ cây còn nhiều cành nên không sao. Khoa nghĩ đúng.",answer:!1,explain:"Sai. Bẻ cành làm cây bị hại, Khoa nên nhắc bạn."},{id:"dd5-moi-truong-quanh-em-24",type:"mc",q:"Gia đình Chi muốn giảm rác nhựa. Việc nào phù hợp?",options:["Mua thêm thật nhiều chai nhựa","Dùng túi vải khi đi chợ","Đốt túi ni lông sau khi dùng"],answer:1,explain:"Túi vải dùng được nhiều lần, giảm rác nhựa."},{id:"dd5-moi-truong-quanh-em-25",type:"order",q:"Sắp xếp quá trình xử lí vỏ chai nhựa đúng cách.",items:["Uống hết nước trong chai","Tráng sạch và để ráo","Bỏ vào thùng rác tái chế","Chai được đưa đi tái chế"],explain:"Phân loại đúng giúp vỏ chai được tái chế thành đồ dùng mới."},{id:"dd5-moi-truong-quanh-em-26",type:"mc",q:"Vy nói: “Một mình mình tiết kiệm nước thì chẳng thay đổi được gì.” Em nghĩ sao?",options:["Đúng, phải có cả nước cùng làm mới được","Đúng, vì vậy không cần tiết kiệm","Mỗi người góp một chút sẽ thành nhiều"],answer:2,explain:"Việc làm nhỏ của mỗi người góp thành thay đổi lớn."},{id:"dd5-moi-truong-quanh-em-27",type:"mc",q:"Phúc nhìn thấy cá chết nổi trắng ở con sông gần nhà. Phúc nên làm gì?",options:["Báo người lớn để báo chính quyền","Vớt cá chết về nhà để ăn","Không quan tâm vì không phải việc của mình"],answer:0,explain:"Cá chết hàng loạt có thể do ô nhiễm, cần báo cho người có trách nhiệm."}]}],challenge:{questions:[{id:"dd5-moi-truong-quanh-em-28",type:"multi",q:"Những câu nào đúng về môi trường sống?",options:["Gồm không khí, nước, đất, sinh vật","Ô nhiễm gây hại cho sức khỏe","Rác thải không ảnh hưởng gì","Ai cũng có trách nhiệm bảo vệ"],answers:[0,1,3],explain:"Môi trường là của chung, cần mọi người cùng bảo vệ."},{id:"dd5-moi-truong-quanh-em-29",type:"tf",q:"Ô nhiễm môi trường chỉ ảnh hưởng đến con người, không ảnh hưởng đến động vật.",answer:!1,explain:"Sai. Ô nhiễm làm hại cả cây cối và động vật."},{id:"dd5-moi-truong-quanh-em-30",type:"mc",q:"Việc nào giúp giảm ô nhiễm không khí?",options:["Đốt rơm rạ ngay sau mùa gặt","Trồng cây xanh, đi bộ hoặc đi xe đạp","Để xe máy nổ máy lâu khi đứng chờ"],answer:1,explain:"Cây xanh và hạn chế khói xe giúp không khí sạch hơn."},{id:"dd5-moi-truong-quanh-em-21",type:"multi",q:"Khu phố của Hà có con mương đầy rác. Hà và các bạn có thể làm gì?",options:["Cùng người lớn tham gia dọn rác","Làm biển nhắc “Không xả rác”","Tuyên truyền cho hàng xóm phân loại rác","Vứt thêm rác vì mương đã bẩn"],answers:[0,1,2],explain:"Học sinh có thể góp sức cùng người lớn làm sạch môi trường."},{id:"dd5-moi-truong-quanh-em-22",type:"mc",q:"Minh thấy hàng xóm đốt rác nhựa khói đen mù mịt. Minh nên làm gì?",options:["Tránh xa khói, nhờ bố mẹ góp ý","Đến gần để xem lửa cháy","Ném thêm rác vào đống lửa"],answer:0,explain:"Khói nhựa rất độc; Minh tránh xa và nhờ người lớn góp ý."},{id:"dd5-moi-truong-quanh-em-25",type:"order",q:"Sắp xếp quá trình xử lí vỏ chai nhựa đúng cách.",items:["Uống hết nước trong chai","Tráng sạch và để ráo","Bỏ vào thùng rác tái chế","Chai được đưa đi tái chế"],explain:"Phân loại đúng giúp vỏ chai được tái chế thành đồ dùng mới."}]},summary:["Môi trường sống gồm không khí, nước, đất, cây cối và động vật quanh ta.","Nhiều việc làm của con người gây ô nhiễm môi trường.","Môi trường ô nhiễm gây hại cho sức khỏe và sự sống."]},{id:"dd5-hanh-dong-vi-moi-truong",title:"Bài 10: Hành động vì môi trường",weeks:[19,20],learn:[{title:"Giảm – Dùng lại – Tái chế",text:"Giảm dùng đồ nhựa dùng một lần; dùng lại chai lọ, giấy, túi; phân loại rác để tái chế.",example:"♻️ giảm · dùng lại · tái chế"},{title:"Tiết kiệm tài nguyên",text:"Tắt điện khi ra khỏi phòng; khóa vòi nước; dùng giấy hai mặt; giữ gìn đồ dùng.",example:"💡 tắt điện · 🚰 khóa nước"},{title:"Lan tỏa việc tốt",text:"Tham gia trồng cây, dọn vệ sinh; nhắc nhở người thân, bạn bè cùng bảo vệ môi trường.",example:"🌱 trồng cây · 📢 tuyên truyền"}],practice:[{questions:[{id:"dd5-hanh-dong-vi-moi-truong-01",type:"match",q:"Nối việc làm với nhóm hành động.",pairs:[["Mang bình nước riêng","Giảm rác thải"],["Dùng chai cũ làm chậu trồng cây","Dùng lại"],["Bỏ giấy vụn vào thùng tái chế","Tái chế"],["Tắt điện khi ra khỏi phòng","Tiết kiệm năng lượng"]],explain:"Mỗi việc làm nhỏ góp phần bảo vệ môi trường."},{id:"dd5-hanh-dong-vi-moi-truong-02",type:"tf",q:"Viết hai mặt giấy là một cách tiết kiệm tài nguyên.",answer:!0,explain:"Đúng. Tiết kiệm giấy là bớt chặt cây."},{id:"dd5-hanh-dong-vi-moi-truong-03",type:"tf",q:"Dùng ống hút nhựa mỗi ngày là thói quen tốt cho môi trường.",answer:!1,explain:"Sai. Ống hút nhựa dùng một lần tạo rất nhiều rác thải."},{id:"dd5-hanh-dong-vi-moi-truong-04",type:"mc",q:"Việc nào là “dùng lại”?",options:["Dùng hộp bánh cũ để đựng bút","Vứt hộp sữa ngay sau khi uống","Mua hộp bút mới mỗi tháng"],answer:0,explain:"Dùng lại đồ cũ giúp giảm rác thải."},{id:"dd5-hanh-dong-vi-moi-truong-05",type:"multi",q:"Những việc làm nào tiết kiệm nước?",options:["Khóa vòi khi đánh răng","Dùng nước vo gạo tưới cây","Để vòi chảy khi rửa bát","Báo người lớn khi thấy ống nước rò rỉ"],answers:[0,1,3],explain:"Tiết kiệm nước là bảo vệ nguồn tài nguyên quý giá."},{id:"dd5-hanh-dong-vi-moi-truong-06",type:"mc",q:"Rác nào nên bỏ vào nhóm rác tái chế?",options:["Vỏ trái cây, rau thừa","Giấy báo cũ, vỏ lon","Khăn giấy đã dùng bẩn"],answer:1,explain:"Giấy báo, vỏ lon có thể tái chế thành vật dụng mới."},{id:"dd5-hanh-dong-vi-moi-truong-07",type:"tf",q:"Trồng và chăm sóc cây xanh là hành động vì môi trường.",answer:!0,explain:"Đúng. Cây xanh làm không khí trong lành."},{id:"dd5-hanh-dong-vi-moi-truong-08",type:"mc",q:"Vỏ trái cây, rau thừa có thể dùng làm gì?",options:["Vứt xuống ao cho cá","Đốt đi cho nhanh","Ủ làm phân bón cho cây"],answer:2,explain:"Rác hữu cơ có thể ủ thành phân bón, rất có ích."},{id:"dd5-hanh-dong-vi-moi-truong-09",type:"tf",q:"Pin cũ có thể vứt chung với rác thường.",answer:!1,explain:"Sai. Pin cũ chứa chất độc hại, cần bỏ vào nơi thu gom riêng."}]},{questions:[{id:"dd5-hanh-dong-vi-moi-truong-10",type:"mc",q:"Vì sao nên phân loại rác tại nhà?",options:["Để dễ tái chế, giảm rác chôn lấp","Để thùng rác trông đẹp mắt hơn","Để mất thêm thời gian dọn dẹp"],answer:0,explain:"Phân loại rác giúp tái chế và bảo vệ môi trường."},{id:"dd5-hanh-dong-vi-moi-truong-11",type:"multi",q:"Những việc làm nào giảm rác thải nhựa?",options:["Dùng túi vải đi chợ","Mang bình nước cá nhân","Mua nước đóng chai nhỏ mỗi ngày","Từ chối ống hút nhựa khi không cần"],answers:[0,1,3],explain:"Thói quen nhỏ giúp giảm rất nhiều rác nhựa."},{id:"dd5-hanh-dong-vi-moi-truong-12",type:"tf",q:"Nhắc nhở người thân tắt điện, khóa nước là lan tỏa hành động xanh.",answer:!0,explain:"Đúng. Lan tỏa giúp cả gia đình cùng bảo vệ môi trường."},{id:"dd5-hanh-dong-vi-moi-truong-13",type:"mc",q:"Câu nào nói đúng về “tái chế”?",options:["Là vứt rác vào bất kì thùng nào cũng được","Là biến đồ đã dùng thành đồ dùng mới","Là đốt rác để lấy tro bón cây"],answer:1,explain:"Tái chế giúp tiết kiệm tài nguyên."},{id:"dd5-hanh-dong-vi-moi-truong-14",type:"tf",q:"Đi bộ hoặc đi xe đạp đến trường khi gần nhà chẳng giúp gì cho môi trường.",answer:!1,explain:"Sai. Đi bộ, đi xe đạp giảm khói bụi từ xe máy, ô tô."},{id:"dd5-hanh-dong-vi-moi-truong-15",type:"mc",q:"Bạn nào có hành động vì môi trường?",options:["Bạn Dũng bỏ giấy kẹo xuống gầm bàn","Bạn Tùng xả nước chơi trong nhà vệ sinh","Bạn Ngọc nhặt rác ở sân trường bỏ vào thùng"],answer:2,explain:"Ngọc giữ gìn trường lớp sạch đẹp."},{id:"dd5-hanh-dong-vi-moi-truong-16",type:"order",q:"Sắp xếp các bước làm chậu cây từ chai nhựa cũ.",items:["Rửa sạch chai nhựa","Nhờ người lớn cắt đôi chai","Đục lỗ thoát nước ở đáy","Cho đất vào và trồng cây"],explain:"Biến chai cũ thành chậu cây là cách dùng lại sáng tạo."},{id:"dd5-hanh-dong-vi-moi-truong-17",type:"mc",q:"Một gia đình nên làm gì với quần áo cũ còn tốt?",options:["Tặng cho người cần hoặc dùng lại","Vứt bỏ hết vào thùng rác","Đốt đi cho gọn nhà cửa"],answer:0,explain:"Tặng hoặc dùng lại giúp giảm rác thải và giúp đỡ người khác."},{id:"dd5-hanh-dong-vi-moi-truong-18",type:"tf",q:"Tiết kiệm đồ dùng học tập cũng là bảo vệ môi trường.",answer:!0,explain:"Đúng. Mỗi đồ dùng làm ra đều tốn tài nguyên."}]},{questions:[{id:"dd5-hanh-dong-vi-moi-truong-19",type:"mc",q:"Lớp Thảo muốn tổ chức “Ngày hội tái chế”. Ý tưởng nào phù hợp?",options:["Mua thật nhiều đồ mới để trang trí","Làm đồ chơi, đồ dùng từ giấy, chai lọ cũ","Đốt rác để làm lửa trại"],answer:1,explain:"Làm đồ từ vật liệu cũ là ý tưởng tái chế sáng tạo."},{id:"dd5-hanh-dong-vi-moi-truong-20",type:"tf",q:"Khoa thấy vòi nước công cộng chảy liên tục, Khoa khóa lại. Khoa có hành động vì môi trường.",answer:!0,explain:"Đúng. Việc nhỏ của Khoa giúp tiết kiệm nước."},{id:"dd5-hanh-dong-vi-moi-truong-21",type:"multi",q:"Gia đình Minh muốn tiết kiệm điện. Cả nhà có thể làm gì?",options:["Tắt điện khi ra khỏi phòng","Rút phích cắm khi không dùng","Tận dụng ánh sáng tự nhiên ban ngày","Bật điều hòa và mở cửa sổ cùng lúc"],answers:[0,1,2],explain:"Những thói quen này giúp tiết kiệm điện cho gia đình."},{id:"dd5-hanh-dong-vi-moi-truong-22",type:"mc",q:"Vy được mời uống nước bằng ly nhựa dùng một lần. Vy mang theo bình nước riêng. Vy nên làm gì?",options:["Lấy thêm vài ly nhựa cho chắc","Cầm ly nhựa rồi vứt đi ngay","Cảm ơn và dùng bình nước của mình"],answer:2,explain:"Dùng bình riêng giúp giảm rác nhựa."},{id:"dd5-hanh-dong-vi-moi-truong-23",type:"tf",q:"Phúc dọn nhà, bỏ chung pin cũ, chai thủy tinh vỡ và vỏ rau vào một túi. Phúc phân loại rác đúng.",answer:!1,explain:"Sai. Pin cũ, thủy tinh vỡ và rác hữu cơ cần được để riêng."},{id:"dd5-hanh-dong-vi-moi-truong-24",type:"mc",q:"Lan muốn rủ cả lớp cùng bảo vệ môi trường. Cách nào hiệu quả?",options:["Rủ cả lớp “Mỗi tuần một việc xanh”","Mắng các bạn vứt rác thật to","Chỉ một mình lặng lẽ dọn rác"],answer:0,explain:"Làm gương và tổ chức hoạt động chung giúp lan tỏa việc tốt."},{id:"dd5-hanh-dong-vi-moi-truong-25",type:"order",q:"Sắp xếp các bước ủ rác hữu cơ đơn giản cùng người lớn.",items:["Thu gom vỏ rau, lá khô","Cho vào thùng ủ có nắp","Trộn đều và đậy kín","Sau một thời gian, dùng làm phân bón cây"],explain:"Ủ rác hữu cơ biến rác thành phân bón có ích."},{id:"dd5-hanh-dong-vi-moi-truong-26",type:"mc",q:"Bình có nhiều sách giáo khoa cũ còn tốt. Bình nên làm gì?",options:["Bán ngay cho người mua giấy vụn","Tặng cho các em lớp dưới hoặc thư viện","Xé ra để gấp đồ chơi"],answer:1,explain:"Tặng sách giúp dùng lại và giúp đỡ các em."},{id:"dd5-hanh-dong-vi-moi-truong-27",type:"mc",q:"Chi thấy bạn hái lá non của cây cảnh ở sân trường để chơi. Chi nên nói gì?",options:["Hái thêm vài lá đi cho vui","Cây nào trong sân cũng hái được","Bạn đừng hái nhé, để cây lớn khỏe"],answer:2,explain:"Nhắc nhở nhẹ nhàng giúp bạn biết bảo vệ cây xanh."}]}],challenge:{questions:[{id:"dd5-hanh-dong-vi-moi-truong-28",type:"multi",q:"Những hành động nào thể hiện lối sống xanh?",options:["Giảm dùng đồ nhựa dùng một lần","Tiết kiệm điện, nước","Phân loại rác","Mua thật nhiều đồ rồi bỏ đi"],answers:[0,1,2],explain:"Lối sống xanh giúp bảo vệ môi trường mỗi ngày."},{id:"dd5-hanh-dong-vi-moi-truong-29",type:"tf",q:"Rác đã bỏ vào thùng thì không cần phân loại.",answer:!1,explain:"Sai. Phân loại giúp xử lí, tái chế rác đúng cách."},{id:"dd5-hanh-dong-vi-moi-truong-30",type:"mc",q:"Thứ tự ưu tiên nào đúng để giảm rác thải?",options:["Giảm dùng trước, rồi dùng lại, rồi tái chế","Tái chế trước, rồi mới giảm dùng","Cứ dùng thoải mái rồi đem tái chế"],answer:0,explain:"Giảm dùng là cách tốt nhất, tiếp theo là dùng lại, cuối cùng là tái chế."},{id:"dd5-hanh-dong-vi-moi-truong-20",type:"tf",q:"Khoa thấy vòi nước công cộng chảy liên tục, Khoa khóa lại. Khoa có hành động vì môi trường.",answer:!0,explain:"Đúng. Việc nhỏ của Khoa giúp tiết kiệm nước."},{id:"dd5-hanh-dong-vi-moi-truong-22",type:"mc",q:"Vy được mời uống nước bằng ly nhựa dùng một lần. Vy mang theo bình nước riêng. Vy nên làm gì?",options:["Lấy thêm vài ly nhựa cho chắc","Cầm ly nhựa rồi vứt đi ngay","Cảm ơn và dùng bình nước của mình"],answer:2,explain:"Dùng bình riêng giúp giảm rác nhựa."},{id:"dd5-hanh-dong-vi-moi-truong-25",type:"order",q:"Sắp xếp các bước ủ rác hữu cơ đơn giản cùng người lớn.",items:["Thu gom vỏ rau, lá khô","Cho vào thùng ủ có nắp","Trộn đều và đậy kín","Sau một thời gian, dùng làm phân bón cây"],explain:"Ủ rác hữu cơ biến rác thành phân bón có ích."}]},summary:["Em thực hiện giảm, dùng lại, tái chế.","Tiết kiệm điện, nước, giấy là bảo vệ môi trường.","Lan tỏa hành động xanh đến mọi người xung quanh."]}]},{id:"lap-ke-hoach-ca-nhan",title:"Lập kế hoạch cá nhân",lessons:[{id:"dd5-vi-sao-lap-ke-hoach",title:"Bài 11: Vì sao cần lập kế hoạch?",weeks:[21,22],learn:[{title:"Kế hoạch cá nhân là gì?",text:"Kế hoạch cá nhân là bảng sắp xếp những việc em sẽ làm, làm khi nào, làm thế nào để đạt được mục tiêu của mình.",example:"📝 việc gì · ⏰ khi nào · 🛠️ làm thế nào"},{title:"Lợi ích của kế hoạch",text:"Giúp em chủ động, không quên việc, dùng thời gian hợp lí, cân bằng giữa học, chơi, nghỉ ngơi và đạt mục tiêu nhanh hơn.",example:"✅ chủ động · ⚖️ cân bằng"},{title:"Các loại kế hoạch",text:"Có kế hoạch ngày, kế hoạch tuần, kế hoạch tháng, kế hoạch cho một việc cụ thể như ôn thi hay tập một môn thể thao.",example:"📅 ngày · tuần · tháng"}],practice:[{questions:[{id:"dd5-vi-sao-lap-ke-hoach-01",type:"tf",q:"Lập kế hoạch giúp em không quên những việc cần làm.",answer:!0,explain:"Đúng. Kế hoạch ghi rõ việc cần làm và thời gian làm."},{id:"dd5-vi-sao-lap-ke-hoach-02",type:"tf",q:"Chỉ người lớn mới cần lập kế hoạch.",answer:!1,explain:"Sai. Học sinh cũng cần kế hoạch để học tập và sinh hoạt hợp lí."},{id:"dd5-vi-sao-lap-ke-hoach-03",type:"multi",q:"Lập kế hoạch cá nhân giúp em điều gì?",options:["Chủ động trong công việc","Dùng thời gian hợp lí","Đạt mục tiêu dễ hơn","Không bao giờ phải cố gắng nữa"],answers:[0,1,2],explain:"Kế hoạch giúp em chủ động và đạt mục tiêu."},{id:"dd5-vi-sao-lap-ke-hoach-04",type:"mc",q:"Một kế hoạch cá nhân cần trả lời những câu hỏi nào?",options:["Làm việc gì, khi nào, làm thế nào?","Ai giàu nhất, ai học giỏi nhất?","Ai sẽ làm hộ mình mọi việc?"],answer:0,explain:"Kế hoạch cần rõ việc gì, khi nào và làm thế nào."},{id:"dd5-vi-sao-lap-ke-hoach-05",type:"mc",q:"Kế hoạch ôn tập cho bài kiểm tra cuối kì thuộc loại nào?",options:["Kế hoạch cho cả cuộc đời","Kế hoạch cho một việc cụ thể","Không phải là kế hoạch"],answer:1,explain:"Đó là kế hoạch cho một mục tiêu cụ thể."},{id:"dd5-vi-sao-lap-ke-hoach-06",type:"tf",q:"Kế hoạch giúp em cân bằng giữa học tập, vui chơi và nghỉ ngơi.",answer:!0,explain:"Đúng. Cân bằng giúp em khỏe mạnh và học tốt."},{id:"dd5-vi-sao-lap-ke-hoach-07",type:"tf",q:"Lập kế hoạch xong thì không cần làm theo.",answer:!1,explain:"Sai. Kế hoạch chỉ có ích khi em thực hiện nghiêm túc."},{id:"dd5-vi-sao-lap-ke-hoach-08",type:"mc",q:"Người không có kế hoạch thường gặp điều gì?",options:["Luôn hoàn thành sớm mọi việc","Có thật nhiều thời gian rảnh rỗi","Dễ quên việc, làm vội vàng"],answer:2,explain:"Thiếu kế hoạch dễ dẫn đến bỏ sót việc và làm vội."},{id:"dd5-vi-sao-lap-ke-hoach-09",type:"mc",q:"Câu nào nói về việc chuẩn bị trước?",options:["Chuẩn bị tốt là đã thành công một nửa","Nước đến chân mới nhảy","Được chăng hay chớ, việc gì cũng xong"],answer:0,explain:"Chuẩn bị kĩ giúp em làm việc hiệu quả hơn."}]},{questions:[{id:"dd5-vi-sao-lap-ke-hoach-10",type:"match",q:"Nối loại kế hoạch với ví dụ.",pairs:[["Kế hoạch ngày","Các việc từ sáng đến tối nay"],["Kế hoạch tuần","Lịch học thêm, việc nhà từ thứ Hai đến Chủ nhật"],["Kế hoạch tháng","Đọc xong ba cuốn sách trong tháng này"],["Kế hoạch việc cụ thể","Ôn tập cho bài kiểm tra Toán"]],explain:"Mỗi loại kế hoạch phù hợp với một khoảng thời gian, mục tiêu."},{id:"dd5-vi-sao-lap-ke-hoach-11",type:"mc",q:"“Nước đến chân mới nhảy” chỉ thói quen nào?",options:["Chuẩn bị mọi việc từ rất sớm","Để việc đến sát giờ mới làm","Làm việc gì cũng thật cẩn thận"],answer:1,explain:"Đó là thói quen thiếu kế hoạch, dễ làm vội và sai sót."},{id:"dd5-vi-sao-lap-ke-hoach-12",type:"tf",q:"Kế hoạch tốt cần phù hợp với sức và thời gian của bản thân.",answer:!0,explain:"Đúng. Kế hoạch quá sức sẽ khó thực hiện."},{id:"dd5-vi-sao-lap-ke-hoach-13",type:"multi",q:"Biểu hiện nào cho thấy một bạn sống có kế hoạch?",options:["Chuẩn bị sách vở từ tối hôm trước","Ghi bài tập vào sổ để không quên","Sáng nào cũng cuống cuồng tìm đồ","Biết sắp xếp thời gian ôn bài trước kì kiểm tra"],answers:[0,1,3],explain:"Chuẩn bị trước và sắp xếp thời gian là biểu hiện của người có kế hoạch."},{id:"dd5-vi-sao-lap-ke-hoach-14",type:"tf",q:"Kế hoạch càng nhiều việc thì càng tốt, dù không làm hết được.",answer:!1,explain:"Sai. Kế hoạch cần vừa sức để thực hiện được."},{id:"dd5-vi-sao-lap-ke-hoach-15",type:"mc",q:"Vì sao kế hoạch cần có thời gian cụ thể?",options:["Để bảng kế hoạch trông dài hơn","Để không bao giờ phải thay đổi","Để biết lúc nào làm việc gì"],answer:2,explain:"Thời gian cụ thể giúp em thực hiện và theo dõi kế hoạch."},{id:"dd5-vi-sao-lap-ke-hoach-16",type:"mc",q:"Bạn nào cần lập kế hoạch hơn?",options:["Bạn Tùng hay quên bài tập và thức khuya làm vội","Bạn Chi luôn làm bài xong trước giờ đi ngủ","Bạn Ngọc soạn cặp từ tối hôm trước"],answer:0,explain:"Tùng cần kế hoạch để không quên việc và ngủ đủ giấc."},{id:"dd5-vi-sao-lap-ke-hoach-17",type:"tf",q:"Lập kế hoạch giúp em tự lập, ít phải chờ người khác nhắc nhở.",answer:!0,explain:"Đúng. Có kế hoạch, em tự biết việc mình cần làm."},{id:"dd5-vi-sao-lap-ke-hoach-18",type:"mc",q:"Câu nào nói đúng về kế hoạch cá nhân?",options:["Kế hoạch phải giống hệt của bạn","Mỗi người có kế hoạch phù hợp với mình","Kế hoạch là do bố mẹ làm hộ"],answer:1,explain:"Kế hoạch cần phù hợp với mục tiêu và hoàn cảnh của từng người."}]},{questions:[{id:"dd5-vi-sao-lap-ke-hoach-19",type:"mc",q:"Lan hay quên mang đồ dùng học tập. Kế hoạch nào giúp Lan?",options:["Nhờ bạn mang đồ dùng hộ mỗi ngày","Mang tất cả sách vở đi mỗi ngày","Soạn cặp theo thời khóa biểu mỗi tối"],answer:2,explain:"Soạn cặp theo thời khóa biểu mỗi tối giúp Lan không quên đồ."},{id:"dd5-vi-sao-lap-ke-hoach-20",type:"tf",q:"Nam muốn đọc hết cuốn truyện 120 trang trong 2 tuần, Nam lên kế hoạch mỗi ngày đọc khoảng 10 trang. Kế hoạch đó hợp lí.",answer:!0,explain:"Đúng. Mười trang mỗi ngày trong 14 ngày là đủ, lại vừa sức."},{id:"dd5-vi-sao-lap-ke-hoach-21",type:"multi",q:"Hà xem ti vi quá nhiều nên không kịp làm bài. Hà nên làm gì?",options:["Lập thời gian biểu cho từng việc","Làm bài xong rồi mới xem ti vi","Đặt giới hạn thời gian xem ti vi","Thức khuya để vừa xem vừa học"],answers:[0,1,2],explain:"Thời gian biểu và giới hạn giúp Hà cân bằng."},{id:"dd5-vi-sao-lap-ke-hoach-22",type:"mc",q:"Khoa muốn học bơi trong hè. Việc đầu tiên Khoa nên làm là gì?",options:["Cùng bố mẹ bàn mục tiêu và nơi học","Nhảy ngay xuống hồ sâu để tập","Chờ đến khi hết hè rồi tính tiếp"],answer:0,explain:"Xác định mục tiêu và cách thực hiện là bước đầu lập kế hoạch."},{id:"dd5-vi-sao-lap-ke-hoach-23",type:"tf",q:"Thảo lập kế hoạch học từ 6 giờ sáng đến 10 giờ tối, không có giờ nghỉ. Kế hoạch đó hợp lí.",answer:!1,explain:"Sai. Kế hoạch cần có thời gian nghỉ ngơi, vui chơi."},{id:"dd5-vi-sao-lap-ke-hoach-24",type:"mc",q:"Minh lập kế hoạch nhưng hay bỏ dở. Minh nên làm gì?",options:["Thôi, không lập kế hoạch nào nữa","Chia việc nhỏ hơn và nhờ bố mẹ nhắc","Viết kế hoạch dài hơn và khó hơn"],answer:1,explain:"Việc nhỏ, có người nhắc và tự theo dõi giúp Minh làm đến cùng."},{id:"dd5-vi-sao-lap-ke-hoach-25",type:"order",q:"Sắp xếp kế hoạch buổi tối hợp lí cho học sinh lớp 5.",items:["Ăn tối cùng gia đình","Làm bài tập về nhà","Soạn cặp cho ngày mai","Đánh răng, đi ngủ đúng giờ"],explain:"Buổi tối có kế hoạch giúp em nghỉ ngơi đủ và sẵn sàng cho ngày mới."},{id:"dd5-vi-sao-lap-ke-hoach-26",type:"mc",q:"Vy có bài kiểm tra Tiếng Việt sau 5 ngày. Kế hoạch nào tốt hơn?",options:["Dồn ôn hết vào tối hôm trước","Không cần ôn vì đã học rồi","Mỗi ngày ôn một phần, ngày cuối ôn lại"],answer:2,explain:"Ôn dần mỗi ngày giúp nhớ lâu và đỡ căng thẳng."},{id:"dd5-vi-sao-lap-ke-hoach-27",type:"mc",q:"Phúc muốn tiết kiệm tiền mua quyển sách. Phúc nên làm gì trước?",options:["Biết giá sách và để dành mỗi tuần","Mua ngay bằng tiền vay của bạn","Đợi ai đó tặng sách cho mình"],answer:0,explain:"Biết số tiền cần và để dành đều đặn là một kế hoạch rõ ràng."}]}],challenge:{questions:[{id:"dd5-vi-sao-lap-ke-hoach-28",type:"multi",q:"Những điều nào đúng về kế hoạch cá nhân?",options:["Giúp em chủ động","Cần vừa sức, có thời gian cụ thể","Lập xong thì cất đi","Cần thực hiện nghiêm túc"],answers:[0,1,3],explain:"Kế hoạch tốt cần rõ ràng, vừa sức và được thực hiện."},{id:"dd5-vi-sao-lap-ke-hoach-29",type:"tf",q:"Có kế hoạch rồi thì không bao giờ được thay đổi.",answer:!1,explain:"Sai. Kế hoạch có thể điều chỉnh khi có việc bất ngờ hoặc chưa phù hợp."},{id:"dd5-vi-sao-lap-ke-hoach-30",type:"mc",q:"Câu nào trái với tinh thần lập kế hoạch?",options:["Chuẩn bị tốt là đã thành công một nửa","Được chăng hay chớ","Việc hôm nay chớ để ngày mai"],answer:1,explain:"“Được chăng hay chớ” chỉ cách làm việc tùy tiện, thiếu kế hoạch."},{id:"dd5-vi-sao-lap-ke-hoach-20",type:"tf",q:"Nam muốn đọc hết cuốn truyện 120 trang trong 2 tuần, Nam lên kế hoạch mỗi ngày đọc khoảng 10 trang. Kế hoạch đó hợp lí.",answer:!0,explain:"Đúng. Mười trang mỗi ngày trong 14 ngày là đủ, lại vừa sức."},{id:"dd5-vi-sao-lap-ke-hoach-22",type:"mc",q:"Khoa muốn học bơi trong hè. Việc đầu tiên Khoa nên làm là gì?",options:["Cùng bố mẹ bàn mục tiêu và nơi học","Nhảy ngay xuống hồ sâu để tập","Chờ đến khi hết hè rồi tính tiếp"],answer:0,explain:"Xác định mục tiêu và cách thực hiện là bước đầu lập kế hoạch."},{id:"dd5-vi-sao-lap-ke-hoach-25",type:"order",q:"Sắp xếp kế hoạch buổi tối hợp lí cho học sinh lớp 5.",items:["Ăn tối cùng gia đình","Làm bài tập về nhà","Soạn cặp cho ngày mai","Đánh răng, đi ngủ đúng giờ"],explain:"Buổi tối có kế hoạch giúp em nghỉ ngơi đủ và sẵn sàng cho ngày mới."}]},summary:["Kế hoạch cá nhân giúp em biết làm gì, khi nào và làm thế nào.","Có kế hoạch, em chủ động và dùng thời gian hợp lí hơn.","Em có thể lập kế hoạch ngày, tuần, tháng hoặc cho một việc cụ thể."]},{id:"dd5-cac-buoc-lap-ke-hoach",title:"Bài 12: Các bước lập kế hoạch cá nhân",weeks:[23,24],learn:[{title:"Bốn bước lập kế hoạch",text:"Xác định mục tiêu; liệt kê các việc cần làm; sắp xếp thời gian và cách làm; thực hiện, theo dõi và điều chỉnh.",example:"🎯 mục tiêu · 📝 việc · ⏰ thời gian · ✅ theo dõi"},{title:"Mục tiêu rõ ràng",text:"Mục tiêu tốt cần cụ thể, vừa sức và có thời hạn, ví dụ “Đọc xong hai cuốn truyện trong tháng này”.",example:"📚 2 cuốn / 1 tháng"},{title:"Theo dõi và điều chỉnh",text:"Đánh dấu việc đã làm; nếu chưa phù hợp thì điều chỉnh; khen thưởng mình khi hoàn thành.",example:"☑️ đánh dấu · 🔄 điều chỉnh"}],practice:[{questions:[{id:"dd5-cac-buoc-lap-ke-hoach-01",type:"order",q:"Sắp xếp các bước lập kế hoạch cá nhân.",items:["Xác định mục tiêu","Liệt kê các việc cần làm","Sắp xếp thời gian và cách làm","Thực hiện, theo dõi và điều chỉnh"],explain:"Làm theo bốn bước giúp em có kế hoạch rõ ràng."},{id:"dd5-cac-buoc-lap-ke-hoach-02",type:"mc",q:"Bước đầu tiên khi lập kế hoạch là gì?",options:["Xác định mục tiêu","Thực hiện ngay","Đánh dấu việc đã làm"],answer:0,explain:"Biết mục tiêu thì mới biết cần làm những việc gì."},{id:"dd5-cac-buoc-lap-ke-hoach-03",type:"mc",q:"Mục tiêu nào rõ ràng hơn?",options:["Mình sẽ học thật giỏi hơn trước nhiều","Thuộc bảng đơn vị đo độ dài trong tuần này","Mình sẽ cố gắng hết sức có thể"],answer:1,explain:"Mục tiêu cụ thể, có thời hạn giúp dễ thực hiện và kiểm tra."},{id:"dd5-cac-buoc-lap-ke-hoach-04",type:"tf",q:"Mục tiêu cần vừa sức với bản thân.",answer:!0,explain:"Đúng. Mục tiêu vừa sức giúp em tự tin thực hiện."},{id:"dd5-cac-buoc-lap-ke-hoach-05",type:"tf",q:"Theo dõi việc thực hiện kế hoạch là không cần thiết.",answer:!1,explain:"Sai. Theo dõi giúp em biết mình đã làm được gì và cần điều chỉnh gì."},{id:"dd5-cac-buoc-lap-ke-hoach-06",type:"multi",q:"Một mục tiêu tốt cần có đặc điểm gì?",options:["Cụ thể","Vừa sức","Có thời hạn","Càng khó càng tốt"],answers:[0,1,2],explain:"Mục tiêu cụ thể, vừa sức, có thời hạn giúp em dễ thành công."},{id:"dd5-cac-buoc-lap-ke-hoach-07",type:"mc",q:"Khi kế hoạch chưa phù hợp, em nên làm gì?",options:["Bỏ luôn kế hoạch","Vẫn làm y nguyên dù không được","Điều chỉnh cho phù hợp"],answer:2,explain:"Điều chỉnh giúp kế hoạch phù hợp với thực tế."},{id:"dd5-cac-buoc-lap-ke-hoach-08",type:"tf",q:"Đánh dấu những việc đã hoàn thành giúp em có thêm động lực.",answer:!0,explain:"Đúng. Nhìn thấy tiến bộ làm em vui và cố gắng hơn."},{id:"dd5-cac-buoc-lap-ke-hoach-09",type:"mc",q:"Công cụ nào giúp em theo dõi kế hoạch?",options:["Bảng kế hoạch có ô đánh dấu","Chiếc bút chì đã bị gãy","Cuốn truyện tranh mới mua"],answer:0,explain:"Bảng có ô đánh dấu giúp em dễ theo dõi việc đã làm."}]},{questions:[{id:"dd5-cac-buoc-lap-ke-hoach-10",type:"match",q:"Nối mỗi bước với ví dụ trong kế hoạch “Thuộc 50 từ tiếng Anh trong một tháng”.",pairs:[["Xác định mục tiêu","Thuộc 50 từ trong một tháng"],["Liệt kê việc cần làm","Chọn từ, làm thẻ từ, ôn lại"],["Sắp xếp thời gian","Mỗi tối học 2 từ mới trong 15 phút"],["Theo dõi, điều chỉnh","Cuối tuần kiểm tra, ôn lại từ quên"]],explain:"Áp dụng các bước giúp kế hoạch rõ ràng, dễ thực hiện."},{id:"dd5-cac-buoc-lap-ke-hoach-11",type:"mc",q:"Vì sao nên chia mục tiêu lớn thành việc nhỏ?",options:["Để có thêm nhiều việc phải làm","Để dễ làm và thấy được tiến bộ","Để kéo dài thời gian thực hiện"],answer:1,explain:"Việc nhỏ giúp em không nản và dễ theo dõi."},{id:"dd5-cac-buoc-lap-ke-hoach-12",type:"tf",q:"Nhờ bố mẹ, thầy cô góp ý kế hoạch giúp kế hoạch hợp lí hơn.",answer:!0,explain:"Đúng. Người lớn có kinh nghiệm để góp ý cho em."},{id:"dd5-cac-buoc-lap-ke-hoach-13",type:"multi",q:"Khi gặp việc bất ngờ làm lỡ kế hoạch, em nên làm gì?",options:["Bình tĩnh sắp xếp lại thời gian","Bù vào ngày khác","Bỏ hết kế hoạch","Rút kinh nghiệm cho lần sau"],answers:[0,1,3],explain:"Điều chỉnh linh hoạt giúp em vẫn đạt được mục tiêu."},{id:"dd5-cac-buoc-lap-ke-hoach-14",type:"tf",q:"Kế hoạch tốt là kế hoạch không có thời gian nghỉ.",answer:!1,explain:"Sai. Nghỉ ngơi hợp lí giúp em làm việc hiệu quả hơn."},{id:"dd5-cac-buoc-lap-ke-hoach-15",type:"mc",q:"Khen thưởng bản thân khi hoàn thành kế hoạch có tác dụng gì?",options:["Làm em chủ quan và lười biếng đi","Không có tác dụng gì cả","Tạo động lực cho những kế hoạch sau"],answer:2,explain:"Phần thưởng nhỏ giúp em hào hứng với mục tiêu mới."},{id:"dd5-cac-buoc-lap-ke-hoach-16",type:"mc",q:"Mục tiêu nào chưa vừa sức với học sinh lớp 5?",options:["Mỗi ngày thuộc 100 từ tiếng Anh mới","Mỗi ngày đọc sách khoảng 20 phút","Mỗi tuần giúp mẹ dọn nhà hai lần"],answer:0,explain:"Học 100 từ mới mỗi ngày là quá sức, khó duy trì."},{id:"dd5-cac-buoc-lap-ke-hoach-17",type:"tf",q:"Viết kế hoạch ra giấy và dán ở góc học tập giúp em dễ nhớ và làm theo.",answer:!0,explain:"Đúng. Nhìn thấy hằng ngày giúp em nhớ việc cần làm."},{id:"dd5-cac-buoc-lap-ke-hoach-18",type:"mc",q:"Việc nào thuộc bước “Thực hiện, theo dõi và điều chỉnh”?",options:["Chọn mục tiêu cho tháng này","Cuối tuần xem lại và sửa lịch","Viết ra các việc cần làm"],answer:1,explain:"Xem lại và sửa lịch là theo dõi, điều chỉnh kế hoạch."}]},{questions:[{id:"dd5-cac-buoc-lap-ke-hoach-19",type:"mc",q:"Dũng muốn tập chạy để tham gia hội khỏe Phù Đổng của trường sau 2 tháng. Mục tiêu nào phù hợp?",options:["Chạy nhanh nhất thế giới sau hai tháng","Ngày đầu tiên chạy thật xa thật lâu","Mỗi tuần tập chạy 3 buổi, mỗi buổi 20 phút"],answer:2,explain:"Mục tiêu cụ thể, vừa sức giúp Dũng tiến bộ đều."},{id:"dd5-cac-buoc-lap-ke-hoach-20",type:"tf",q:"Chi muốn viết chữ đẹp, Chi lên kế hoạch luyện viết 1 trang mỗi ngày và nhờ cô nhận xét mỗi tuần. Kế hoạch đó hợp lí.",answer:!0,explain:"Đúng. Kế hoạch rõ ràng, vừa sức và có theo dõi."},{id:"dd5-cac-buoc-lap-ke-hoach-21",type:"multi",q:"Ngọc lập kế hoạch đọc sách nhưng tuần đầu chỉ đọc được 2 ngày. Ngọc nên làm gì?",options:["Tìm nguyên nhân vì sao chưa đọc được","Chọn giờ đọc phù hợp hơn","Đặt lời nhắc hằng ngày","Bỏ kế hoạch vì thấy khó"],answers:[0,1,2],explain:"Tìm nguyên nhân và điều chỉnh giúp Ngọc tiếp tục kế hoạch."},{id:"dd5-cac-buoc-lap-ke-hoach-22",type:"mc",q:"Tuần này Khoa có lịch đá bóng và bài kiểm tra. Khoa nên làm gì?",options:["Ôn bài trước, rồi đến giờ đá bóng","Bỏ ôn bài để đi đá bóng","Thức thật khuya để làm cả hai"],answer:0,explain:"Ưu tiên và sắp xếp hợp lí giúp Khoa làm tốt cả hai việc."},{id:"dd5-cac-buoc-lap-ke-hoach-23",type:"order",q:"Sắp xếp kế hoạch tiết kiệm mua bộ màu vẽ của Vy.",items:["Xác định giá bộ màu","Tính mỗi tuần cần để dành bao nhiêu","Để dành tiền đều đặn mỗi tuần","Đủ tiền thì đi mua cùng bố mẹ"],explain:"Từng bước rõ ràng giúp Vy đạt mục tiêu."},{id:"dd5-cac-buoc-lap-ke-hoach-24",type:"tf",q:"Thảo đặt mục tiêu “Học tốt hơn” mà không ghi việc cụ thể. Mục tiêu đó đã rõ ràng.",answer:!1,explain:"Sai. Thảo cần ghi rõ học môn gì, làm gì và trong bao lâu."},{id:"dd5-cac-buoc-lap-ke-hoach-25",type:"mc",q:"Phúc lập kế hoạch tuần nhưng thứ Tư bị ốm. Phúc nên làm gì?",options:["Cố làm hết mọi việc dù đang ốm","Nghỉ cho khỏe rồi điều chỉnh lịch","Bỏ luôn cả kế hoạch của tuần"],answer:1,explain:"Sức khỏe là trên hết; kế hoạch có thể điều chỉnh."},{id:"dd5-cac-buoc-lap-ke-hoach-26",type:"mc",q:"Hà muốn giúp mẹ việc nhà đều đặn. Kế hoạch nào cụ thể nhất?",options:["Mình sẽ chăm giúp mẹ hơn trước","Khi nào rảnh thì mình giúp mẹ","Mỗi tối rửa bát, Chủ nhật lau nhà"],answer:2,explain:"Kế hoạch ghi rõ việc và thời gian giúp Hà dễ thực hiện."},{id:"dd5-cac-buoc-lap-ke-hoach-27",type:"mc",q:"Bình hoàn thành kế hoạch đọc 4 cuốn sách. Bình nên làm gì tiếp?",options:["Rút kinh nghiệm và đặt mục tiêu mới","Thôi không đọc sách nữa vì đã xong","Khoe khắp nơi và chê bạn đọc ít"],answer:0,explain:"Rút kinh nghiệm và đặt mục tiêu mới giúp Bình tiến bộ không ngừng."}]}],challenge:{questions:[{id:"dd5-cac-buoc-lap-ke-hoach-28",type:"multi",q:"Những điều nào giúp kế hoạch cá nhân thành công?",options:["Mục tiêu rõ ràng","Thời gian cụ thể","Theo dõi và điều chỉnh","Lập xong là đủ"],answers:[0,1,2],explain:"Mục tiêu, thời gian và sự theo dõi giúp kế hoạch thành công."},{id:"dd5-cac-buoc-lap-ke-hoach-29",type:"tf",q:"Thay đổi kế hoạch nghĩa là mình đã thất bại.",answer:!1,explain:"Sai. Điều chỉnh kế hoạch là cách làm thông minh khi hoàn cảnh thay đổi."},{id:"dd5-cac-buoc-lap-ke-hoach-30",type:"mc",q:"Bước nào giúp em biết kế hoạch có đang hiệu quả hay không?",options:["Xác định mục tiêu","Theo dõi và điều chỉnh","Liệt kê việc cần làm"],answer:1,explain:"Theo dõi giúp em biết kế hoạch đang tốt hay cần sửa."},{id:"dd5-cac-buoc-lap-ke-hoach-19",type:"mc",q:"Dũng muốn tập chạy để tham gia hội khỏe Phù Đổng của trường sau 2 tháng. Mục tiêu nào phù hợp?",options:["Chạy nhanh nhất thế giới sau hai tháng","Ngày đầu tiên chạy thật xa thật lâu","Mỗi tuần tập chạy 3 buổi, mỗi buổi 20 phút"],answer:2,explain:"Mục tiêu cụ thể, vừa sức giúp Dũng tiến bộ đều."},{id:"dd5-cac-buoc-lap-ke-hoach-21",type:"multi",q:"Ngọc lập kế hoạch đọc sách nhưng tuần đầu chỉ đọc được 2 ngày. Ngọc nên làm gì?",options:["Tìm nguyên nhân vì sao chưa đọc được","Chọn giờ đọc phù hợp hơn","Đặt lời nhắc hằng ngày","Bỏ kế hoạch vì thấy khó"],answers:[0,1,2],explain:"Tìm nguyên nhân và điều chỉnh giúp Ngọc tiếp tục kế hoạch."},{id:"dd5-cac-buoc-lap-ke-hoach-25",type:"mc",q:"Phúc lập kế hoạch tuần nhưng thứ Tư bị ốm. Phúc nên làm gì?",options:["Cố làm hết mọi việc dù đang ốm","Nghỉ cho khỏe rồi điều chỉnh lịch","Bỏ luôn cả kế hoạch của tuần"],answer:1,explain:"Sức khỏe là trên hết; kế hoạch có thể điều chỉnh."}]},summary:["Lập kế hoạch qua bốn bước: mục tiêu, việc cần làm, thời gian và cách làm, thực hiện và điều chỉnh.","Mục tiêu cần cụ thể, vừa sức, có thời hạn.","Theo dõi và điều chỉnh giúp kế hoạch thành công."]}]},{id:"phong-tranh-xam-hai",title:"Phòng, tránh xâm hại",lessons:[{id:"dd5-nhan-biet-xam-hai",title:"Bài 13: Nhận biết nguy cơ bị xâm hại",weeks:[25,27],learn:[{title:"Cơ thể em là của em",text:"Không ai được làm đau em, đe dọa em hay chạm vào vùng riêng tư của em (những chỗ đồ bơi che lại). Em có quyền nói “không”.",example:"🩱 vùng riêng tư · ✋ “Không!”"},{title:"Xâm hại là gì?",text:"Xâm hại là khi ai đó làm tổn hại đến cơ thể hoặc tinh thần của trẻ em: đánh đập, đe dọa, bắt nạt, chạm vào vùng riêng tư, bắt giữ bí mật xấu, quấy rối qua mạng.",example:"⚠️ cơ thể · tinh thần · trên mạng"},{title:"Dấu hiệu cần cảnh giác",text:"Ai đó cho quà rồi dặn giữ bí mật, rủ đi đến chỗ vắng, đòi xem hoặc chụp ảnh cơ thể em, nhắn tin làm em sợ. Người xâm hại có thể là người lạ hoặc người quen.",example:"🎁🤫 quà kèm bí mật"},{title:"Không phải lỗi của em",text:"Nếu điều không hay xảy ra, đó không phải lỗi của em. Em hãy kể với người lớn tin cậy để được giúp đỡ.",example:"💛 em được bảo vệ"}],practice:[{questions:[{id:"dd5-nhan-biet-xam-hai-01",type:"tf",q:"Vùng riêng tư là những chỗ trên cơ thể được đồ bơi che lại.",answer:!0,explain:"Đúng. Không ai được chạm vào hay đòi xem vùng riêng tư của em."},{id:"dd5-nhan-biet-xam-hai-02",type:"tf",q:"Em có quyền nói “không” khi ai đó chạm vào em làm em khó chịu.",answer:!0,explain:"Đúng. Cơ thể em là của em."},{id:"dd5-nhan-biet-xam-hai-03",type:"tf",q:"Người xâm hại trẻ em luôn là người lạ.",answer:!1,explain:"Sai. Người xâm hại có thể là người lạ hoặc cả người quen, vì vậy em cần cảnh giác."},{id:"dd5-nhan-biet-xam-hai-04",type:"mc",q:"Bí mật nào em KHÔNG nên giữ?",options:["Bí mật về việc ai đó chạm vào vùng riêng tư","Bí mật về món quà sinh nhật tặng mẹ","Bí mật về bữa tiệc bất ngờ cho bạn thân"],answer:0,explain:"Bí mật làm em sợ hãi, khó chịu thì phải kể với người lớn tin cậy."},{id:"dd5-nhan-biet-xam-hai-05",type:"multi",q:"Đâu là dấu hiệu nguy hiểm em cần cảnh giác?",options:["Người khác cho quà rồi dặn không được kể với bố mẹ","Có người rủ em đến chỗ vắng một mình","Có người đòi chụp ảnh cơ thể em","Cô giáo khen em làm bài tốt"],answers:[0,1,2],explain:"Quà kèm bí mật, rủ đến chỗ vắng, đòi chụp ảnh là dấu hiệu nguy hiểm."},{id:"dd5-nhan-biet-xam-hai-06",type:"mc",q:"Xâm hại có thể xảy ra ở đâu?",options:["Chỉ xảy ra ở ngoài đường","Ở nhiều nơi, kể cả trên mạng","Chỉ xảy ra ở những nơi đông người"],answer:1,explain:"Xâm hại có thể xảy ra ở nhiều nơi, kể cả qua tin nhắn, mạng xã hội."},{id:"dd5-nhan-biet-xam-hai-07",type:"tf",q:"Nếu bị xâm hại thì đó là lỗi của trẻ em.",answer:!1,explain:"Sai. Đó không bao giờ là lỗi của em; người làm hại mới là người có lỗi."},{id:"dd5-nhan-biet-xam-hai-08",type:"mc",q:"Bị đe dọa, bắt nạt liên tục làm em sợ hãi là bị xâm hại về mặt nào?",options:["Về đồ dùng","Về học tập","Về tinh thần"],answer:2,explain:"Đe dọa, bắt nạt làm tổn thương tinh thần cũng là xâm hại."},{id:"dd5-nhan-biet-xam-hai-09",type:"mc",q:"Số điện thoại tổng đài bảo vệ trẻ em là số nào?",options:["111","113","115"],answer:0,explain:"Tổng đài 111 miễn phí, luôn sẵn sàng giúp đỡ trẻ em."}]},{questions:[{id:"dd5-nhan-biet-xam-hai-10",type:"match",q:"Nối tình huống với cách nhận biết.",pairs:[["Người lạ cho kẹo rủ đi chơi","Dấu hiệu nguy hiểm"],["Bác sĩ khám bệnh khi có bố mẹ ở bên","An toàn"],["Có người nhắn tin đòi ảnh cơ thể","Xâm hại qua mạng"],["Bạn bị đánh và dọa không được kể","Bị xâm hại"]],explain:"Nhận biết đúng giúp em biết khi nào cần tìm sự giúp đỡ."},{id:"dd5-nhan-biet-xam-hai-11",type:"mc",q:"Vì sao kẻ xấu hay dặn trẻ em “giữ bí mật”?",options:["Vì họ muốn giúp em thật nhiều","Vì họ sợ người lớn biết và ngăn họ lại","Vì đó là trò chơi vui của người lớn"],answer:1,explain:"Lời dặn giữ bí mật là dấu hiệu cảnh báo, em cần kể với người lớn."},{id:"dd5-nhan-biet-xam-hai-12",type:"tf",q:"Bí mật vui như quà bất ngờ thì có thể giữ, còn bí mật làm em sợ thì phải kể.",answer:!0,explain:"Đúng. Bí mật vui sẽ được kể ra; bí mật xấu cần người lớn giúp."},{id:"dd5-nhan-biet-xam-hai-13",type:"multi",q:"Những việc làm nào giúp em phòng tránh xâm hại?",options:["Không đi một mình ở nơi vắng vẻ","Không nhận quà của người lạ","Báo bố mẹ biết em đi đâu, với ai","Ở một mình với người lạ cho lịch sự"],answers:[0,1,2],explain:"Những thói quen này giúp em giữ an toàn."},{id:"dd5-nhan-biet-xam-hai-14",type:"tf",q:"Người quen thân của gia đình thì được phép chạm vào vùng riêng tư của em.",answer:!1,explain:"Sai. Không ai được chạm vào vùng riêng tư của em, dù là người quen."},{id:"dd5-nhan-biet-xam-hai-15",type:"mc",q:"Khi được bác sĩ khám bệnh, điều gì giúp em an toàn?",options:["Đi khám một mình cho nhanh gọn","Không cần ai đi cùng em cả","Có bố mẹ hoặc người lớn tin cậy ở bên"],answer:2,explain:"Có người thân đi cùng giúp em yên tâm và an toàn."},{id:"dd5-nhan-biet-xam-hai-16",type:"mc",q:"Cảm giác nào nhắc em có thể đang gặp nguy hiểm?",options:["Thấy sợ hãi, khó chịu, bối rối","Thấy vui vẻ, thoải mái khi chơi","Thấy no bụng sau bữa ăn trưa"],answer:0,explain:"Hãy tin vào cảm giác khó chịu của mình và tìm người lớn giúp."},{id:"dd5-nhan-biet-xam-hai-17",type:"tf",q:"Trên mạng, người lạ có thể giả làm bạn cùng tuổi để làm quen.",answer:!0,explain:"Đúng. Em không gửi ảnh, thông tin riêng cho người quen qua mạng."},{id:"dd5-nhan-biet-xam-hai-18",type:"mc",q:"Người lớn tin cậy là người như thế nào?",options:["Người mới quen trên mạng hay khen em","Người luôn quan tâm, lắng nghe và bảo vệ em","Người hay cho quà và dặn em giữ bí mật"],answer:1,explain:"Bố mẹ, ông bà, thầy cô là những người lớn tin cậy của em."}]},{questions:[{id:"dd5-nhan-biet-xam-hai-19",type:"mc",q:"Một người hàng xóm hay cho Lan bánh rồi dặn “Đừng kể với bố mẹ nhé”. Lan nên làm gì?",options:["Giữ bí mật để được thêm bánh","Nhận bánh rồi chia cho các bạn","Không nhận nữa và kể với bố mẹ"],answer:2,explain:"Quà kèm lời dặn giữ bí mật là dấu hiệu cần báo cho bố mẹ."},{id:"dd5-nhan-biet-xam-hai-20",type:"tf",q:"Nam được một người lạ rủ lên xe đưa về nhà. Nam từ chối và đứng chờ ở chỗ đông người, gọi bố mẹ. Nam làm đúng.",answer:!0,explain:"Đúng. Nam không đi theo người lạ và tìm người lớn tin cậy."},{id:"dd5-nhan-biet-xam-hai-21",type:"multi",q:"Hà nhận tin nhắn lạ đòi gửi ảnh riêng, dọa sẽ đăng ảnh xấu nếu không gửi. Hà nên làm gì?",options:["Không gửi bất cứ ảnh nào","Kể ngay với bố mẹ hoặc thầy cô","Giữ lại tin nhắn để người lớn xem","Gửi ảnh cho xong để khỏi bị dọa"],answers:[0,1,2],explain:"Không làm theo, kể với người lớn và giữ bằng chứng là cách đúng."},{id:"dd5-nhan-biet-xam-hai-22",type:"mc",q:"Bạn của Minh kể bị một anh lớn hay đánh và dọa nếu kể sẽ đánh nặng hơn. Minh nên làm gì?",options:["Động viên bạn và cùng bạn kể với cô giáo","Giữ kín vì bạn đã dặn mình rồi","Tự mình đi tìm anh lớn đó nói chuyện"],answer:0,explain:"Kể với người lớn tin cậy giúp bạn được bảo vệ."},{id:"dd5-nhan-biet-xam-hai-23",type:"tf",q:"Khoa thấy khó chịu khi một người cứ ôm mình quá chặt, nhưng Khoa im lặng vì sợ bất lịch sự. Khoa nên tiếp tục im lặng.",answer:!1,explain:"Sai. Khoa có quyền nói “Cháu không thích” và kể với người lớn tin cậy."},{id:"dd5-nhan-biet-xam-hai-24",type:"mc",q:"Thảo đi học về, có người lạ nói “Mẹ cháu nhờ chú đón”. Thảo nên làm gì?",options:["Đi theo vì chú biết tên mẹ","Không đi theo, nhờ cô gọi cho mẹ","Đi theo chú một đoạn rồi tính tiếp"],answer:1,explain:"Cô giáo sẽ giúp Thảo kiểm tra với mẹ, giữ an toàn cho Thảo."},{id:"dd5-nhan-biet-xam-hai-25",type:"mc",q:"Vy được bạn mới quen trên trò chơi trực tuyến hẹn gặp ở công viên. Vy nên làm gì?",options:["Đi gặp một mình cho vui","Rủ thêm một bạn nhỏ đi cùng","Từ chối và kể với bố mẹ"],answer:2,explain:"Không hẹn gặp người quen qua mạng; bố mẹ sẽ giúp Vy an toàn."},{id:"dd5-nhan-biet-xam-hai-26",type:"order",q:"Sắp xếp cách ứng xử khi có người làm em thấy sợ, khó chịu.",items:["Nói to và rõ: “Không!”","Nhanh chóng rời đi đến chỗ an toàn","Kể ngay với người lớn tin cậy"],explain:"Nói không, rời đi, kể lại là ba bước tự bảo vệ."},{id:"dd5-nhan-biet-xam-hai-27",type:"mc",q:"Phúc nghĩ: “Mình là con trai nên không bao giờ bị xâm hại.” Em nghĩ sao?",options:["Chưa đúng, bạn nào cũng cần biết tự bảo vệ","Đúng, con trai thì không cần lo gì","Đúng, chỉ bạn gái mới cần học điều này"],answer:0,explain:"Mọi trẻ em đều cần biết cách tự bảo vệ mình."}]}],challenge:{questions:[{id:"dd5-nhan-biet-xam-hai-28",type:"multi",q:"Những câu nào đúng về xâm hại trẻ em?",options:["Có thể do người lạ hoặc người quen","Có thể xảy ra trên mạng","Không bao giờ là lỗi của trẻ em","Trẻ em nên giữ kín để khỏi phiền ai"],answers:[0,1,2],explain:"Biết những điều này giúp em tự tin tìm sự giúp đỡ."},{id:"dd5-nhan-biet-xam-hai-29",type:"tf",q:"Nếu đã lỡ giữ bí mật một thời gian thì không nên kể nữa.",answer:!1,explain:"Sai. Lúc nào kể với người lớn tin cậy cũng không muộn."},{id:"dd5-nhan-biet-xam-hai-30",type:"mc",q:"Điều gì quan trọng nhất khi em gặp chuyện làm em sợ hãi?",options:["Tự mình chịu đựng một mình","Kể với người lớn tin cậy để được giúp","Chờ cho mọi chuyện tự qua đi"],answer:1,explain:"Người lớn tin cậy sẽ lắng nghe và bảo vệ em."},{id:"dd5-nhan-biet-xam-hai-21",type:"multi",q:"Hà nhận tin nhắn lạ đòi gửi ảnh riêng, dọa sẽ đăng ảnh xấu nếu không gửi. Hà nên làm gì?",options:["Không gửi bất cứ ảnh nào","Kể ngay với bố mẹ hoặc thầy cô","Giữ lại tin nhắn để người lớn xem","Gửi ảnh cho xong để khỏi bị dọa"],answers:[0,1,2],explain:"Không làm theo, kể với người lớn và giữ bằng chứng là cách đúng."},{id:"dd5-nhan-biet-xam-hai-23",type:"tf",q:"Khoa thấy khó chịu khi một người cứ ôm mình quá chặt, nhưng Khoa im lặng vì sợ bất lịch sự. Khoa nên tiếp tục im lặng.",answer:!1,explain:"Sai. Khoa có quyền nói “Cháu không thích” và kể với người lớn tin cậy."},{id:"dd5-nhan-biet-xam-hai-26",type:"order",q:"Sắp xếp cách ứng xử khi có người làm em thấy sợ, khó chịu.",items:["Nói to và rõ: “Không!”","Nhanh chóng rời đi đến chỗ an toàn","Kể ngay với người lớn tin cậy"],explain:"Nói không, rời đi, kể lại là ba bước tự bảo vệ."}]},summary:["Cơ thể em là của em; em có quyền nói “không”.","Xâm hại có thể làm tổn hại cơ thể hoặc tinh thần, xảy ra cả ngoài đời và trên mạng.","Cảnh giác với quà kèm bí mật, lời rủ đến chỗ vắng, đòi xem hay chụp ảnh cơ thể.","Nếu bị xâm hại, đó không phải lỗi của em; hãy kể với người lớn tin cậy."]},{id:"dd5-noi-khong-va-tim-tro-giup",title:"Bài 14: Nói “không” và tìm người tin cậy",weeks:[28,29],learn:[{title:"Quy tắc ba bước",text:"Nói “Không!” thật to, rõ ràng; rời đi nhanh đến chỗ an toàn, đông người; kể ngay với người lớn tin cậy.",example:"✋ Không! · 🏃 Rời đi · 🗣️ Kể lại"},{title:"Bàn tay tin cậy",text:"Mỗi em nên nghĩ ra năm người lớn tin cậy, như năm ngón tay: bố, mẹ, ông bà, thầy cô… để kể khi gặp chuyện.",example:"🖐️ năm người tin cậy"},{title:"Gọi trợ giúp",text:"Tổng đài 111 bảo vệ trẻ em miễn phí. Khi nguy hiểm khẩn cấp, gọi 113 hoặc nhờ người lớn gần nhất.",example:"📞 111 · 113"},{title:"Giúp bạn",text:"Khi bạn kể chuyện bị xâm hại, em lắng nghe, tin bạn, không chê cười, và cùng bạn kể với người lớn tin cậy.",example:"💛 lắng nghe · tin bạn"}],practice:[{questions:[{id:"dd5-noi-khong-va-tim-tro-giup-01",type:"order",q:"Sắp xếp quy tắc ba bước tự bảo vệ.",items:["Nói “Không!” thật to, rõ ràng","Rời đi nhanh đến chỗ an toàn","Kể ngay với người lớn tin cậy"],explain:"Ba bước này giúp em thoát khỏi tình huống nguy hiểm."},{id:"dd5-noi-khong-va-tim-tro-giup-02",type:"multi",q:"Ai có thể là người lớn tin cậy của em?",options:["Bố mẹ","Ông bà","Thầy cô giáo","Người lạ mới quen trên mạng"],answers:[0,1,2],explain:"Người lớn tin cậy là người luôn quan tâm, bảo vệ em."},{id:"dd5-noi-khong-va-tim-tro-giup-03",type:"tf",q:"Tổng đài 111 giúp đỡ trẻ em và gọi không mất tiền.",answer:!0,explain:"Đúng. Em có thể gọi 111 khi cần giúp đỡ."},{id:"dd5-noi-khong-va-tim-tro-giup-04",type:"tf",q:"Nói “không” với người lớn là hỗn láo trong mọi trường hợp.",answer:!1,explain:"Sai. Khi bị làm điều khiến em sợ, khó chịu, nói “không” là đúng."},{id:"dd5-noi-khong-va-tim-tro-giup-05",type:"mc",q:"Khi nói “không”, em nên nói thế nào?",options:["Nói to, rõ ràng, nhìn thẳng","Nói thật nhỏ, cúi mặt xuống","Cười đùa cho nhẹ nhàng không khí"],answer:0,explain:"Nói to, rõ ràng giúp người kia hiểu em thật sự không đồng ý."},{id:"dd5-noi-khong-va-tim-tro-giup-06",type:"mc",q:"Sau khi rời khỏi chỗ nguy hiểm, em nên làm gì?",options:["Quên đi, coi như chưa có gì","Kể ngay với người lớn tin cậy","Chỉ kể với một bạn nhỏ hơn"],answer:1,explain:"Kể với người lớn giúp em được bảo vệ, chuyện không lặp lại."},{id:"dd5-noi-khong-va-tim-tro-giup-07",type:"tf",q:"Nếu người lớn đầu tiên không tin, em hãy kể với một người lớn tin cậy khác.",answer:!0,explain:"Đúng. Hãy kể tiếp cho đến khi có người giúp em."},{id:"dd5-noi-khong-va-tim-tro-giup-08",type:"mc",q:"Nơi nào an toàn để em chạy đến khi gặp nguy hiểm?",options:["Một con ngõ vắng gần đó","Một ngôi nhà hoang bỏ trống","Nơi đông người như cửa hàng, trường học"],answer:2,explain:"Nơi đông người có nhiều người lớn để giúp em."},{id:"dd5-noi-khong-va-tim-tro-giup-09",type:"tf",q:"Khi bạn kể bị xâm hại, em nên giữ kín và không nói với ai.",answer:!1,explain:"Sai. Em nên tin bạn và cùng bạn kể với người lớn tin cậy."}]},{questions:[{id:"dd5-noi-khong-va-tim-tro-giup-10",type:"match",q:"Nối tình huống với cách ứng xử.",pairs:[["Người lạ kéo tay em đi","Hét to “Không!” và chạy đến chỗ đông người"],["Bị nhắn tin dọa nạt","Không trả lời, kể với bố mẹ"],["Bạn kể bị đánh ở nhà","Lắng nghe, cùng bạn kể với cô"],["Lạc đường ở chợ","Nhờ cô chú bán hàng hoặc bảo vệ giúp"]],explain:"Mỗi tình huống cần cách ứng xử an toàn phù hợp."},{id:"dd5-noi-khong-va-tim-tro-giup-11",type:"mc",q:"Vì sao em cần có năm người lớn tin cậy?",options:["Để luôn có người khác giúp mình","Để nhận được thật nhiều quà","Để mỗi người dạy em một môn học"],answer:0,explain:"Nhiều người tin cậy giúp em luôn có chỗ dựa."},{id:"dd5-noi-khong-va-tim-tro-giup-12",type:"tf",q:"Khi bạn kể chuyện bị làm hại, em cần tin bạn và không chê cười.",answer:!0,explain:"Đúng. Sự tin tưởng giúp bạn dám tìm người lớn giúp đỡ."},{id:"dd5-noi-khong-va-tim-tro-giup-13",type:"multi",q:"Khi kể với người lớn tin cậy, em nên nói những gì?",options:["Chuyện gì đã xảy ra","Ai đã làm","Xảy ra ở đâu, khi nào","Chỉ nói “không có gì đâu”"],answers:[0,1,2],explain:"Kể rõ ràng giúp người lớn hiểu và giúp em kịp thời."},{id:"dd5-noi-khong-va-tim-tro-giup-14",type:"tf",q:"Em chỉ nên kể khi chắc chắn mình bị xâm hại.",answer:!1,explain:"Sai. Chỉ cần thấy sợ, khó chịu hay bối rối, em đã nên kể với người lớn tin cậy."},{id:"dd5-noi-khong-va-tim-tro-giup-15",type:"mc",q:"Bạn Chi rất buồn vì bị nhóm bạn đe dọa trên mạng, nhưng xấu hổ không dám kể. Em nên nói gì?",options:["Thôi kệ, chuyện trên mạng thôi mà","Không phải lỗi của bạn, mình cùng nói với cô","Bạn tự giải quyết đi, đừng kể với ai"],answer:1,explain:"Lời động viên giúp Chi dám tìm sự giúp đỡ."},{id:"dd5-noi-khong-va-tim-tro-giup-16",type:"mc",q:"Vì sao phải hét to khi bị người lạ kéo đi?",options:["Để luyện cho giọng nói to hơn","Để làm người lạ thấy buồn cười","Để mọi người chú ý và đến giúp"],answer:2,explain:"Hét to giúp em được mọi người chú ý và giúp đỡ."},{id:"dd5-noi-khong-va-tim-tro-giup-17",type:"tf",q:"Học quy tắc an toàn giúp em tự tin hơn, không phải để sợ hãi mọi người.",answer:!0,explain:"Đúng. Hầu hết mọi người đều tốt; em chỉ cần biết cách giữ an toàn."},{id:"dd5-noi-khong-va-tim-tro-giup-18",type:"mc",q:"Câu nói nào phù hợp khi muốn từ chối một cái ôm làm em khó chịu?",options:["Cháu không thích như vậy ạ","Ôm thêm nữa đi ạ","Thôi được, tùy bác ạ"],answer:0,explain:"Em có quyền từ chối lịch sự nhưng rõ ràng."}]},{questions:[{id:"dd5-noi-khong-va-tim-tro-giup-19",type:"mc",q:"Đi chơi công viên, một người lạ hỏi đường rồi bảo Lan dẫn vào chỗ khuất. Lan nên làm gì?",options:["Dẫn người đó đi cho tỏ ra tốt bụng","Chỉ đường bằng lời rồi về với bố mẹ","Đi cùng một đoạn rồi chạy về"],answer:1,explain:"Người lớn cần giúp sẽ hỏi người lớn khác; Lan không đi theo người lạ."},{id:"dd5-noi-khong-va-tim-tro-giup-20",type:"tf",q:"Nam thấy em họ ngồi buồn, kể bị người khác chạm vào vùng riêng tư. Nam tin em và báo ngay cho bố mẹ. Nam làm đúng.",answer:!0,explain:"Đúng. Nam tin em và tìm người lớn tin cậy giúp đỡ."},{id:"dd5-noi-khong-va-tim-tro-giup-21",type:"multi",q:"Hà đang ở nhà một mình, có người lạ gõ cửa nói là thợ sửa điện. Hà nên làm gì?",options:["Không mở cửa","Gọi điện cho bố mẹ để hỏi","Không cho người lạ biết mình ở nhà một mình","Mở cửa mời vào nhà"],answers:[0,1,2],explain:"Không mở cửa cho người lạ khi ở nhà một mình, liên lạc ngay với bố mẹ."},{id:"dd5-noi-khong-va-tim-tro-giup-22",type:"mc",q:"Khoa kể với cô giáo nhưng cô bận chưa nghe kĩ. Khoa nên làm gì?",options:["Thôi không kể với ai nữa","Tự mình giải quyết một mình","Kể với người lớn khác hoặc gọi 111"],answer:2,explain:"Hãy kể tiếp cho đến khi có người lắng nghe và giúp."},{id:"dd5-noi-khong-va-tim-tro-giup-23",type:"tf",q:"Minh bị dọa nếu kể sẽ bị đánh, nên Minh giữ im lặng. Đó là cách an toàn nhất.",answer:!1,explain:"Sai. Lời dọa là để em sợ; kể với người lớn tin cậy mới giúp Minh an toàn."},{id:"dd5-noi-khong-va-tim-tro-giup-24",type:"mc",q:"Vy bị một người quen chụp ảnh khi đang thay đồ. Vy nên làm gì?",options:["Kể ngay với bố mẹ hoặc người lớn tin cậy","Giữ kín vì đó là người quen","Tự xóa ảnh trên máy người đó"],answer:0,explain:"Việc đó là sai; Vy cần kể ngay để được bảo vệ."},{id:"dd5-noi-khong-va-tim-tro-giup-25",type:"order",q:"Sắp xếp cách giúp khi bạn kể bị xâm hại.",items:["Lắng nghe bạn bình tĩnh","Nói với bạn: “Mình tin bạn, không phải lỗi của bạn”","Cùng bạn kể với người lớn tin cậy"],explain:"Lắng nghe, tin bạn và cùng tìm người lớn là cách giúp bạn tốt nhất."},{id:"dd5-noi-khong-va-tim-tro-giup-26",type:"mc",q:"Ngọc lạc bố mẹ ở trung tâm thương mại. Ngọc nên nhờ ai?",options:["Một người lạ đứng ở góc vắng","Nhân viên ở quầy thông tin","Một người rủ Ngọc ra ngoài tìm"],answer:1,explain:"Nhân viên có đồng phục sẽ giúp gọi loa tìm bố mẹ an toàn."},{id:"dd5-noi-khong-va-tim-tro-giup-27",type:"mc",q:"Tùng thấy bạn có nhiều vết bầm và hay sợ hãi. Tùng nên làm gì?",options:["Trêu bạn hậu đậu, hay bị ngã","Kể chuyện đó cho cả lớp cùng nghe","Hỏi han nhẹ nhàng và báo cô giáo"],answer:2,explain:"Quan tâm và báo người lớn tin cậy giúp bạn được bảo vệ."}]}],challenge:{questions:[{id:"dd5-noi-khong-va-tim-tro-giup-28",type:"multi",q:"Những điều nào giúp em tự bảo vệ trước nguy cơ bị xâm hại?",options:["Quy tắc nói không, rời đi, kể lại","Bàn tay năm người tin cậy","Tổng đài 111","Giữ bí mật khi bị dọa nạt"],answers:[0,1,2],explain:"Ba điều này giúp em luôn có cách tìm sự giúp đỡ."},{id:"dd5-noi-khong-va-tim-tro-giup-29",type:"tf",q:"Chỉ cần kể với bạn bè cùng tuổi là đủ.",answer:!1,explain:"Sai. Em cần kể với người lớn tin cậy, vì người lớn mới có thể bảo vệ em."},{id:"dd5-noi-khong-va-tim-tro-giup-30",type:"mc",q:"Câu nào đúng nhất khi em gặp chuyện xấu?",options:["Đó không phải lỗi của em","Đó là lỗi của em vì đã không cẩn thận","Em nên giữ kín để mọi người không buồn"],answer:0,explain:"Em không có lỗi; hãy để người lớn giúp em."},{id:"dd5-noi-khong-va-tim-tro-giup-20",type:"tf",q:"Nam thấy em họ ngồi buồn, kể bị người khác chạm vào vùng riêng tư. Nam tin em và báo ngay cho bố mẹ. Nam làm đúng.",answer:!0,explain:"Đúng. Nam tin em và tìm người lớn tin cậy giúp đỡ."},{id:"dd5-noi-khong-va-tim-tro-giup-22",type:"mc",q:"Khoa kể với cô giáo nhưng cô bận chưa nghe kĩ. Khoa nên làm gì?",options:["Thôi không kể với ai nữa","Tự mình giải quyết một mình","Kể với người lớn khác hoặc gọi 111"],answer:2,explain:"Hãy kể tiếp cho đến khi có người lắng nghe và giúp."},{id:"dd5-noi-khong-va-tim-tro-giup-24",type:"mc",q:"Vy bị một người quen chụp ảnh khi đang thay đồ. Vy nên làm gì?",options:["Kể ngay với bố mẹ hoặc người lớn tin cậy","Giữ kín vì đó là người quen","Tự xóa ảnh trên máy người đó"],answer:0,explain:"Việc đó là sai; Vy cần kể ngay để được bảo vệ."}]},summary:["Nhớ quy tắc: Nói “Không!”, rời đi, kể lại với người lớn tin cậy.","Mỗi em có một “bàn tay tin cậy” gồm năm người lớn.","Tổng đài 111 luôn sẵn sàng giúp đỡ trẻ em.","Khi bạn kể chuyện, hãy tin bạn và cùng bạn tìm người lớn giúp."]}]},{id:"su-dung-tien-hop-li",title:"Sử dụng tiền hợp lí",lessons:[{id:"dd5-tien-va-chi-tieu",title:"Bài 15: Tiền và cách chi tiêu hợp lí",weeks:[30,32],learn:[{title:"Tiền từ đâu mà có?",text:"Tiền là thành quả lao động vất vả của bố mẹ và người thân, vì vậy cần được sử dụng hợp lí.",example:"💵 công sức lao động"},{title:"Cần và muốn",text:"“Cần” là thứ thiết yếu như đồ ăn, sách vở, quần áo. “Muốn” là thứ thích có nhưng chưa thật cần như đồ chơi mới, quà vặt. Hãy ưu tiên cái cần trước.",example:"✅ cần · 💭 muốn"},{title:"Chi tiêu hợp lí",text:"Chỉ mua thứ cần thiết, so sánh giá, không mua theo bạn bè hay quảng cáo, không lãng phí.",example:"🛒 so sánh giá · 🚫 lãng phí"}],practice:[{questions:[{id:"dd5-tien-va-chi-tieu-01",type:"tf",q:"Tiền là thành quả lao động của bố mẹ, cần được sử dụng hợp lí.",answer:!0,explain:"Đúng. Hiểu điều này giúp em biết quý trọng đồng tiền."},{id:"dd5-tien-va-chi-tieu-02",type:"multi",q:"Đâu là những thứ “cần”?",options:["Sách giáo khoa","Bữa ăn hằng ngày","Áo ấm mùa đông","Đồ chơi mới giống bạn"],answers:[0,1,2],explain:"Sách vở, đồ ăn, quần áo là những thứ cần thiết."},{id:"dd5-tien-va-chi-tieu-03",type:"mc",q:"Thứ nào là “muốn” chứ chưa thật cần?",options:["Thêm một con gấu bông thứ năm","Vở viết để mang đi học","Thuốc uống khi bị ốm"],answer:0,explain:"Gấu bông thứ năm là mong muốn, chưa phải thứ cần thiết."},{id:"dd5-tien-va-chi-tieu-04",type:"tf",q:"Thấy bạn có gì thì mình cũng phải mua bằng được.",answer:!1,explain:"Sai. Em chỉ mua thứ mình thật sự cần và phù hợp với gia đình."},{id:"dd5-tien-va-chi-tieu-05",type:"mc",q:"Chi tiêu hợp lí là gì?",options:["Mua thật nhiều khi có tiền","Mua đúng thứ cần, đúng giá","Không bao giờ tiêu tiền"],answer:1,explain:"Chi tiêu hợp lí là mua thứ cần thiết với giá phù hợp."},{id:"dd5-tien-va-chi-tieu-06",type:"mc",q:"Khi mua đồ, em nên ưu tiên điều gì?",options:["Những thứ quảng cáo nhiều","Những thứ bạn bè đang có","Những thứ thật sự cần thiết"],answer:2,explain:"Ưu tiên thứ cần trước, thứ muốn sau."},{id:"dd5-tien-va-chi-tieu-07",type:"tf",q:"So sánh giá trước khi mua giúp em chi tiêu hợp lí hơn.",answer:!0,explain:"Đúng. So sánh giá giúp em chọn được món phù hợp."},{id:"dd5-tien-va-chi-tieu-08",type:"tf",q:"Mua đồ đắt tiền nhất luôn là cách chi tiêu thông minh nhất.",answer:!1,explain:"Sai. Đắt nhất chưa chắc đã cần thiết hay phù hợp."},{id:"dd5-tien-va-chi-tieu-09",type:"mc",q:"Câu tục ngữ nào khuyên tiết kiệm?",options:["Năng nhặt chặt bị","Ăn xổi ở thì","Vung tay quá trán"],answer:0,explain:"“Năng nhặt chặt bị” khuyên góp nhặt từng chút sẽ thành nhiều."}]},{questions:[{id:"dd5-tien-va-chi-tieu-10",type:"match",q:"Nối món đồ với nhận xét phù hợp.",pairs:[["Hộp bút để đi học","Cần cho việc học"],["Thuốc hạ sốt khi ốm","Cần cho sức khỏe"],["Món đồ chơi thứ mười","Chỉ là muốn, chưa cần"],["Đôi giày mới khi giày cũ còn tốt","Muốn, có thể chờ thêm"]],explain:"Phân biệt cần và muốn giúp em chi tiêu khôn ngoan."},{id:"dd5-tien-va-chi-tieu-11",type:"mc",q:"“Vung tay quá trán” chỉ người thế nào?",options:["Người chăm chỉ tập thể dục","Người tiêu xài quá mức, hoang phí","Người biết tiết kiệm từng đồng"],answer:1,explain:"Câu này phê phán việc tiêu tiền quá khả năng."},{id:"dd5-tien-va-chi-tieu-12",type:"tf",q:"Quảng cáo có thể khiến em muốn mua những thứ không thật sự cần.",answer:!0,explain:"Đúng. Em cần suy nghĩ kĩ trước khi mua theo quảng cáo."},{id:"dd5-tien-va-chi-tieu-13",type:"multi",q:"Những việc làm nào là lãng phí tiền?",options:["Mua quà vặt mỗi ngày rồi ăn không hết","Mua đồ dùng học tập mới khi đồ cũ còn tốt","Dùng bút đến hết mực mới thay","Mua đồ chơi rồi chán ngay sau một hôm"],answers:[0,1,3],explain:"Mua thứ không cần hoặc dùng không hết là lãng phí."},{id:"dd5-tien-va-chi-tieu-14",type:"tf",q:"Tiền tiêu vặt bố mẹ cho thì em được tiêu thế nào cũng được.",answer:!1,explain:"Sai. Em vẫn cần tiêu hợp lí và có thể để dành một phần."},{id:"dd5-tien-va-chi-tieu-15",type:"mc",q:"Vì sao nên phân biệt “cần” và “muốn”?",options:["Để không bao giờ phải mua gì nữa","Để có cớ đòi bố mẹ mua nhiều hơn","Để ưu tiên thứ quan trọng, tránh lãng phí"],answer:2,explain:"Phân biệt giúp em dùng tiền đúng chỗ."},{id:"dd5-tien-va-chi-tieu-16",type:"mc",q:"Bạn nào chi tiêu hợp lí?",options:["Bạn Bình so sánh giá rồi mua vở cần dùng","Bạn Lan tiêu hết tiền vào quà vặt mỗi ngày","Bạn Hà mua thêm bút dù hộp bút còn đầy"],answer:0,explain:"Bình mua thứ cần, có so sánh giá."},{id:"dd5-tien-va-chi-tieu-17",type:"tf",q:"Giữ gìn đồ dùng bền lâu cũng là cách sử dụng tiền hợp lí.",answer:!0,explain:"Đúng. Đồ bền lâu thì không phải tốn tiền mua mới."},{id:"dd5-tien-va-chi-tieu-18",type:"mc",q:"Câu nào thể hiện thái độ đúng với đồng tiền?",options:["Tiền dễ kiếm nên cứ tiêu thoải mái","Quý trọng tiền vì đó là công sức lao động","Có tiền là có được tất cả mọi thứ"],answer:1,explain:"Quý trọng đồng tiền là trân trọng sức lao động."}]},{questions:[{id:"dd5-tien-va-chi-tieu-19",type:"mc",q:"Lan có 20 nghìn đồng, Lan cần mua một quyển vở và rất muốn mua thêm kẹo. Lan nên làm gì?",options:["Mua thật nhiều kẹo trước rồi tính","Mua kẹo rồi xin thêm tiền mua vở","Mua vở trước, dư thì mới mua kẹo"],answer:2,explain:"Ưu tiên thứ cần trước là chi tiêu hợp lí."},{id:"dd5-tien-va-chi-tieu-20",type:"tf",q:"Nam muốn mua đồ chơi theo quảng cáo, Nam đợi vài ngày xem mình còn muốn không. Đó là cách làm khôn ngoan.",answer:!0,explain:"Đúng. Chờ vài ngày giúp Nam tránh mua theo cảm hứng."},{id:"dd5-tien-va-chi-tieu-21",type:"multi",q:"Hà muốn mua một chiếc cặp mới. Hà nên làm gì trước?",options:["Xem cặp cũ còn dùng được không","Hỏi ý kiến bố mẹ","So sánh giá ở vài nơi","Mua ngay chiếc đắt nhất"],answers:[0,1,2],explain:"Suy nghĩ kĩ, hỏi bố mẹ và so sánh giá giúp Hà quyết định đúng."},{id:"dd5-tien-va-chi-tieu-22",type:"mc",q:"Khoa được bạn rủ góp tiền mua đồ chơi đắt tiền dù Khoa không thích lắm. Khoa nên làm gì?",options:["Từ chối lịch sự vì không cần thiết","Góp tiền để bạn khỏi giận mình","Xin bố mẹ tiền để góp với bạn"],answer:0,explain:"Khoa không cần mua theo bạn bè."},{id:"dd5-tien-va-chi-tieu-23",type:"tf",q:"Vy làm mất bút nên mua ngay chiếc bút đắt nhất để khỏi tiếc. Vy chi tiêu hợp lí.",answer:!1,explain:"Sai. Vy nên chọn chiếc bút vừa dùng, giá phù hợp và giữ gìn cẩn thận hơn."},{id:"dd5-tien-va-chi-tieu-24",type:"mc",q:"Minh thấy ăn quà vặt mỗi ngày tốn nhiều tiền. Minh nên làm gì?",options:["Ăn nhiều hơn để đỡ phí tiền","Ăn sáng đầy đủ ở nhà, bớt quà vặt","Mượn tiền bạn để ăn quà vặt"],answer:1,explain:"Ăn sáng ở nhà vừa tốt cho sức khỏe vừa tiết kiệm tiền."},{id:"dd5-tien-va-chi-tieu-25",type:"order",q:"Sắp xếp các bước suy nghĩ trước khi mua một món đồ.",items:["Tự hỏi: mình cần hay chỉ muốn?","Xem mình có đủ tiền không","So sánh giá và chất lượng","Quyết định mua hoặc không mua"],explain:"Suy nghĩ theo từng bước giúp em chi tiêu hợp lí."},{id:"dd5-tien-va-chi-tieu-26",type:"mc",q:"Thảo được tặng tiền mừng tuổi. Cách nào hợp lí nhất?",options:["Tiêu hết ngay trong ngày Tết","Cho bạn mượn hết để bạn mua đồ","Bàn với bố mẹ để dành phần lớn"],answer:2,explain:"Bàn với bố mẹ giúp Thảo dùng tiền hợp lí."},{id:"dd5-tien-va-chi-tieu-27",type:"mc",q:"Phúc nói: “Nhà mình có tiền, mình cứ mua thoải mái.” Em góp ý thế nào?",options:["Có tiền vẫn nên tiêu hợp lí","Đúng rồi, có tiền thì cứ tiêu","Bạn nên mua nhiều hơn nữa"],answer:0,explain:"Chi tiêu hợp lí là thói quen tốt với mọi gia đình."}]}],challenge:{questions:[{id:"dd5-tien-va-chi-tieu-28",type:"multi",q:"Những điều nào giúp em chi tiêu hợp lí?",options:["Phân biệt cần và muốn","So sánh giá","Không mua theo bạn bè, quảng cáo","Tiêu hết tiền ngay khi có"],answers:[0,1,2],explain:"Ba thói quen này giúp em dùng tiền khôn ngoan."},{id:"dd5-tien-va-chi-tieu-29",type:"tf",q:"Chi tiêu hợp lí nghĩa là không bao giờ được mua thứ mình thích.",answer:!1,explain:"Sai. Em có thể mua thứ mình thích khi đã lo đủ thứ cần và có kế hoạch."},{id:"dd5-tien-va-chi-tieu-30",type:"mc",q:"Câu “Ăn phải dành, có phải kiệm” khuyên điều gì?",options:["Phải ăn thật nhiều mỗi bữa","Biết để dành và tiết kiệm","Có gì thì tiêu hết ngay"],answer:1,explain:"Câu tục ngữ khuyên chúng ta tiết kiệm, để dành."},{id:"dd5-tien-va-chi-tieu-19",type:"mc",q:"Lan có 20 nghìn đồng, Lan cần mua một quyển vở và rất muốn mua thêm kẹo. Lan nên làm gì?",options:["Mua thật nhiều kẹo trước rồi tính","Mua kẹo rồi xin thêm tiền mua vở","Mua vở trước, dư thì mới mua kẹo"],answer:2,explain:"Ưu tiên thứ cần trước là chi tiêu hợp lí."},{id:"dd5-tien-va-chi-tieu-22",type:"mc",q:"Khoa được bạn rủ góp tiền mua đồ chơi đắt tiền dù Khoa không thích lắm. Khoa nên làm gì?",options:["Từ chối lịch sự vì không cần thiết","Góp tiền để bạn khỏi giận mình","Xin bố mẹ tiền để góp với bạn"],answer:0,explain:"Khoa không cần mua theo bạn bè."},{id:"dd5-tien-va-chi-tieu-25",type:"order",q:"Sắp xếp các bước suy nghĩ trước khi mua một món đồ.",items:["Tự hỏi: mình cần hay chỉ muốn?","Xem mình có đủ tiền không","So sánh giá và chất lượng","Quyết định mua hoặc không mua"],explain:"Suy nghĩ theo từng bước giúp em chi tiêu hợp lí."}]},summary:["Tiền là thành quả lao động, cần được sử dụng hợp lí.","Phân biệt “cần” và “muốn”, ưu tiên những thứ cần thiết.","Chi tiêu hợp lí là mua đúng thứ cần, đúng giá, không lãng phí."]},{id:"dd5-tiet-kiem-ke-hoach-chi-tieu",title:"Bài 16: Tiết kiệm và lập kế hoạch chi tiêu",weeks:[33,35],learn:[{title:"Tiết kiệm tiền",text:"Tiết kiệm là để dành một phần tiền đều đặn cho việc cần sau này, như mua sách, đồ dùng hay giúp người khó khăn.",example:"🐷 lợn đất · 📒 sổ ghi chép"},{title:"Kế hoạch chi tiêu",text:"Ghi số tiền em có; chia thành phần để chi, phần tiết kiệm, phần chia sẻ; ghi lại những gì đã tiêu.",example:"💰 chi · 🐷 để dành · 💝 chia sẻ"},{title:"Chia sẻ yêu thương",text:"Một phần tiền tiết kiệm có thể dùng để ủng hộ bạn khó khăn hoặc người gặp thiên tai.",example:"🤝 ủng hộ"}],practice:[{questions:[{id:"dd5-tiet-kiem-ke-hoach-chi-tieu-01",type:"tf",q:"Bỏ một phần tiền tiêu vặt vào lợn đất là cách tiết kiệm.",answer:!0,explain:"Đúng. Để dành đều đặn giúp em có tiền cho việc cần sau này."},{id:"dd5-tiet-kiem-ke-hoach-chi-tieu-02",type:"mc",q:"Kế hoạch chi tiêu đơn giản thường chia tiền thành mấy phần?",options:["Chi tiêu, tiết kiệm, chia sẻ","Chỉ một phần để tiêu hết","Ăn quà, mua đồ chơi, cho vay"],answer:0,explain:"Chia tiền thành phần chi tiêu, tiết kiệm và chia sẻ là cách làm hợp lí."},{id:"dd5-tiet-kiem-ke-hoach-chi-tieu-03",type:"tf",q:"Tiết kiệm là không tiêu một đồng nào, kể cả cho việc cần.",answer:!1,explain:"Sai. Tiết kiệm là chi tiêu hợp lí và để dành một phần, không phải nhịn những thứ cần thiết."},{id:"dd5-tiet-kiem-ke-hoach-chi-tieu-04",type:"mc",q:"Ghi chép chi tiêu giúp em điều gì?",options:["Biết thêm nhiều món đồ để mua","Biết tiền đã tiêu vào đâu","Có lí do xin thêm tiền bố mẹ"],answer:1,explain:"Ghi chép giúp em kiểm soát việc dùng tiền."},{id:"dd5-tiet-kiem-ke-hoach-chi-tieu-05",type:"multi",q:"Tiền tiết kiệm có thể dùng vào việc gì có ích?",options:["Mua sách hay","Ủng hộ bạn gặp khó khăn","Mua đồ dùng học tập cần thiết","Mua thật nhiều quà vặt một lúc"],answers:[0,1,2],explain:"Tiền tiết kiệm nên dùng cho việc có ích."},{id:"dd5-tiet-kiem-ke-hoach-chi-tieu-06",type:"mc",q:"Câu nào nói về sự tích lũy từng chút?",options:["Nước chảy bèo trôi","Ăn xổi ở thì","Góp gió thành bão"],answer:2,explain:"“Góp gió thành bão” nghĩa là góp từng chút sẽ thành nhiều."},{id:"dd5-tiet-kiem-ke-hoach-chi-tieu-07",type:"tf",q:"Dành một phần tiền để ủng hộ người gặp thiên tai là việc làm ý nghĩa.",answer:!0,explain:"Đúng. Đó là cách chia sẻ yêu thương."},{id:"dd5-tiet-kiem-ke-hoach-chi-tieu-08",type:"tf",q:"Cho bạn vay hết tiền tiết kiệm mà không hỏi bố mẹ là việc làm đúng.",answer:!1,explain:"Sai. Em nên hỏi ý kiến bố mẹ trước những việc liên quan đến tiền."},{id:"dd5-tiet-kiem-ke-hoach-chi-tieu-09",type:"mc",q:"Việc đầu tiên khi lập kế hoạch chi tiêu là gì?",options:["Biết mình có bao nhiêu tiền","Đi mua sắm ngay","Hỏi bạn đang có bao nhiêu"],answer:0,explain:"Biết số tiền mình có thì mới chia được các phần hợp lí."}]},{questions:[{id:"dd5-tiet-kiem-ke-hoach-chi-tieu-10",type:"match",q:"Nối việc làm với phần trong kế hoạch chi tiêu.",pairs:[["Mua vở viết","Chi tiêu"],["Bỏ vào lợn đất","Tiết kiệm"],["Ủng hộ bạn vùng lũ","Chia sẻ"],["Ghi vào sổ","Theo dõi"]],explain:"Mỗi việc làm thuộc một phần của kế hoạch chi tiêu."},{id:"dd5-tiet-kiem-ke-hoach-chi-tieu-11",type:"mc",q:"Vì sao nên tiết kiệm đều đặn mỗi tuần?",options:["Vì như vậy bố mẹ sẽ cho thêm tiền","Vì góp từng chút sẽ đủ cho việc cần","Vì tiết kiệm một lần thì không vui"],answer:1,explain:"Tiết kiệm đều đặn giúp em đạt mục tiêu."},{id:"dd5-tiet-kiem-ke-hoach-chi-tieu-12",type:"tf",q:"Đặt mục tiêu tiết kiệm cụ thể giúp em kiên trì hơn.",answer:!0,explain:"Đúng. Ví dụ: “Để dành đủ tiền mua quyển từ điển trong hai tháng”."},{id:"dd5-tiet-kiem-ke-hoach-chi-tieu-13",type:"multi",q:"Những thói quen nào giúp em tiết kiệm?",options:["Giữ gìn đồ dùng cẩn thận","Dùng hết đồ cũ mới mua đồ mới","Hạn chế quà vặt","Mua đồ mới mỗi khi chán đồ cũ"],answers:[0,1,2],explain:"Giữ gìn và dùng hết đồ cũ giúp tiết kiệm tiền."},{id:"dd5-tiet-kiem-ke-hoach-chi-tieu-14",type:"tf",q:"Tiết kiệm chỉ là việc của người lớn trong gia đình.",answer:!1,explain:"Sai. Trẻ em cũng có thể tiết kiệm từ tiền tiêu vặt, tiền mừng tuổi."},{id:"dd5-tiet-kiem-ke-hoach-chi-tieu-15",type:"mc",q:"Bạn nào biết lập kế hoạch chi tiêu?",options:["Bạn Tùng tiêu hết tiền ngay ngày đầu tuần","Bạn Dũng vay tiền bạn mỗi khi hết tiền","Bạn Ngọc ghi rõ để dành bao nhiêu, tiêu gì"],answer:2,explain:"Ngọc biết số tiền tiêu và để dành mỗi tuần."},{id:"dd5-tiet-kiem-ke-hoach-chi-tieu-16",type:"mc",q:"Mỗi tuần Chi để dành 10 nghìn đồng. Sau 5 tuần, Chi để dành được bao nhiêu?",options:["50 nghìn đồng","15 nghìn đồng","100 nghìn đồng"],answer:0,explain:"10 nghìn đồng nhân 5 tuần bằng 50 nghìn đồng."},{id:"dd5-tiet-kiem-ke-hoach-chi-tieu-17",type:"tf",q:"Khi chưa đủ tiền mua thứ mình muốn, em có thể kiên nhẫn để dành thêm.",answer:!0,explain:"Đúng. Kiên nhẫn giúp em mua được món đồ bằng chính tiền tiết kiệm."},{id:"dd5-tiet-kiem-ke-hoach-chi-tieu-18",type:"mc",q:"Vì sao nên hỏi ý kiến bố mẹ trước khi tiêu khoản tiền lớn?",options:["Vì bố mẹ thích được hỏi han","Vì bố mẹ giúp em cân nhắc kĩ hơn","Vì em không được phép tiêu tiền"],answer:1,explain:"Bố mẹ có kinh nghiệm để giúp em quyết định đúng."}]},{questions:[{id:"dd5-tiet-kiem-ke-hoach-chi-tieu-19",type:"mc",q:"Khoa muốn mua bộ sách 60 nghìn đồng, mỗi tuần để dành được 15 nghìn đồng. Khoa cần để dành mấy tuần?",options:["3 tuần","6 tuần","4 tuần"],answer:2,explain:"60 nghìn đồng chia cho 15 nghìn đồng mỗi tuần là 4 tuần."},{id:"dd5-tiet-kiem-ke-hoach-chi-tieu-20",type:"tf",q:"Lan ghi sổ thấy tuần này tiêu nhiều cho quà vặt, Lan quyết định tuần sau bớt lại. Lan biết điều chỉnh chi tiêu.",answer:!0,explain:"Đúng. Ghi chép giúp Lan nhận ra và điều chỉnh kịp thời."},{id:"dd5-tiet-kiem-ke-hoach-chi-tieu-21",type:"multi",q:"Lớp em quyên góp giúp bạn bị ốm nặng. Em có thể làm gì?",options:["Góp một phần tiền tiết kiệm","Hỏi ý kiến bố mẹ trước","Viết lời động viên gửi bạn","Lấy tiền của bố mẹ mà không xin"],answers:[0,1,2],explain:"Góp một phần tiền tiết kiệm sau khi hỏi bố mẹ là việc làm ý nghĩa."},{id:"dd5-tiet-kiem-ke-hoach-chi-tieu-22",type:"mc",q:"Minh có 50 nghìn đồng tiền thưởng. Cách chia nào hợp lí?",options:["Để dành 30 nghìn, tiêu 15 nghìn, ủng hộ 5 nghìn","Tiêu hết cả 50 nghìn vào trò chơi","Cho bạn vay cả 50 nghìn đồng ngay"],answer:0,explain:"Chia thành các phần giúp Minh vừa tiêu, vừa để dành, vừa chia sẻ."},{id:"dd5-tiet-kiem-ke-hoach-chi-tieu-23",type:"tf",q:"Hà để dành được tiền rồi lại tiêu hết vào quà vặt ngay hôm sau. Hà đã tiết kiệm tốt.",answer:!1,explain:"Sai. Tiết kiệm cần kiên trì và dùng tiền để dành cho việc có ích."},{id:"dd5-tiet-kiem-ke-hoach-chi-tieu-24",type:"order",q:"Sắp xếp các bước lập kế hoạch chi tiêu trong tuần.",items:["Ghi số tiền em có","Chia phần chi tiêu, tiết kiệm, chia sẻ","Ghi lại mỗi lần tiêu tiền","Cuối tuần xem lại và điều chỉnh"],explain:"Làm theo các bước giúp em quản lí tiền tốt."},{id:"dd5-tiet-kiem-ke-hoach-chi-tieu-25",type:"mc",q:"Vy muốn mua quà sinh nhật mẹ bằng tiền của mình. Vy nên làm gì?",options:["Xin bố tiền ngay hôm sinh nhật","Để dành dần từ vài tuần trước","Vay tiền bạn rồi trả sau"],answer:1,explain:"Để dành sớm giúp Vy tự mua được món quà ý nghĩa."},{id:"dd5-tiet-kiem-ke-hoach-chi-tieu-26",type:"mc",q:"Thảo thấy bạn tiêu tiền rất hoang phí. Thảo nên làm gì?",options:["Chê bạn hoang phí trước cả lớp","Tiêu hoang phí giống như bạn","Chia sẻ với bạn cách mình để dành tiền"],answer:2,explain:"Chia sẻ kinh nghiệm tốt giúp bạn thay đổi."},{id:"dd5-tiet-kiem-ke-hoach-chi-tieu-27",type:"mc",q:"Phúc tiết kiệm đủ tiền nhưng thấy món đồ định mua không còn cần nữa. Phúc nên làm gì?",options:["Giữ tiền cho việc cần khác","Vẫn mua cho đỡ tiếc công","Tiêu hết ngay vào việc khác"],answer:0,explain:"Không cần nữa thì không mua; giữ tiền cho việc có ích hơn."}]}],challenge:{questions:[{id:"dd5-tiet-kiem-ke-hoach-chi-tieu-28",type:"multi",q:"Những điều nào đúng về tiết kiệm và kế hoạch chi tiêu?",options:["Để dành đều đặn từng chút","Ghi chép và điều chỉnh","Có phần để chia sẻ","Tiêu hết rồi xin thêm"],answers:[0,1,2],explain:"Tiết kiệm, ghi chép và chia sẻ là thói quen tài chính tốt."},{id:"dd5-tiet-kiem-ke-hoach-chi-tieu-29",type:"tf",q:"Đã lập kế hoạch chi tiêu thì không được thay đổi.",answer:!1,explain:"Sai. Em có thể điều chỉnh kế hoạch khi cần."},{id:"dd5-tiet-kiem-ke-hoach-chi-tieu-30",type:"mc",q:"Mỗi tuần Bình để dành 5 nghìn đồng. Sau 8 tuần, Bình có bao nhiêu?",options:["13 nghìn đồng","40 nghìn đồng","45 nghìn đồng"],answer:1,explain:"5 nghìn đồng nhân 8 tuần bằng 40 nghìn đồng."},{id:"dd5-tiet-kiem-ke-hoach-chi-tieu-19",type:"mc",q:"Khoa muốn mua bộ sách 60 nghìn đồng, mỗi tuần để dành được 15 nghìn đồng. Khoa cần để dành mấy tuần?",options:["3 tuần","6 tuần","4 tuần"],answer:2,explain:"60 nghìn đồng chia cho 15 nghìn đồng mỗi tuần là 4 tuần."},{id:"dd5-tiet-kiem-ke-hoach-chi-tieu-22",type:"mc",q:"Minh có 50 nghìn đồng tiền thưởng. Cách chia nào hợp lí?",options:["Để dành 30 nghìn, tiêu 15 nghìn, ủng hộ 5 nghìn","Tiêu hết cả 50 nghìn vào trò chơi","Cho bạn vay cả 50 nghìn đồng ngay"],answer:0,explain:"Chia thành các phần giúp Minh vừa tiêu, vừa để dành, vừa chia sẻ."},{id:"dd5-tiet-kiem-ke-hoach-chi-tieu-25",type:"mc",q:"Vy muốn mua quà sinh nhật mẹ bằng tiền của mình. Vy nên làm gì?",options:["Xin bố tiền ngay hôm sinh nhật","Để dành dần từ vài tuần trước","Vay tiền bạn rồi trả sau"],answer:1,explain:"Để dành sớm giúp Vy tự mua được món quà ý nghĩa."}]},summary:["Tiết kiệm là để dành tiền đều đặn cho việc cần sau này.","Lập kế hoạch chi tiêu giúp em biết tiền đi đâu và đạt mục tiêu.","Em có thể dành một phần tiền để chia sẻ với người khó khăn."]}]}],g={grade:5,subject:n,title:i,review:h,topics:t};export{g as default,c as grade,h as review,n as subject,i as title,t as topics};
